INSERT INTO project_posts (id, project_id, author_id, title, priority, content, created_at, modified_at, deleted_at) VALUES
(1, 1, (SELECT id FROM users WHERE employee_no='DT22-0163'), '자동 심사 로직 영향도 분석 결과 공유', 'HIGH', '1/12 킥오프에서 말씀드렸던 자동 심사 로직 영향도 분석, 다 끝나서 공유드립니다.\n\n1. 분석 범위\n현재 여신 심사 규칙 엔진에 걸려 있는 규칙은 총 87개입니다. 이 중 자동 심사 확대 목표(60%)를 달성하려면 몇 개를 신규로 설계해야 하는지 하나씩 뜯어봤습니다.\n\n2. 결과\n- 기존 로직 재사용 가능: 62개\n- 신규 설계 필요: 25개\n\n재사용 가능한 62개는 대부분 소득 검증, 재직 확인처럼 판단 기준이 명확한 규칙들입니다. 신규 설계가 필요한 25개는 크게 세 갈래로 나뉩니다.\n\n- 담보 평가 기준 관련: 3건 (담보물 시가 변동을 어떻게 반영할지가 애매함)\n- 소득 검증 방식 관련: 2건 (프리랜서·사업소득자 케이스 처리 기준 없음)\n- 연체 이력 반영 기준: 2건 (단기 연체와 장기 연체를 같은 가중치로 볼지)\n- 나머지 18건: 담보대출 중도상환, 갱신 심사 등 절차성 규칙\n\n3. 리스크 판단\n25개 중 위 7건(담보/소득/연체)은 여신본부와 기준을 다시 맞춰야 확정할 수 있습니다. 나머지 18건은 저희 선에서 설계 가능한 수준이라고 판단합니다.\n\n4. 다음 단계\n7건은 제가 여신본부 쪽에 2/13까지 재협의 요청 넣어두겠습니다. 나머지 18건은 이번 주부터 설계 착수하겠습니다.\n\n질문이나 다른 의견 있으시면 편하게 댓글 남겨주세요.', '2026-01-23 09:00:00', '2026-01-23 09:00:00', NULL),
(2, 1, (SELECT id FROM users WHERE employee_no='DT22-0165'), '담보대출 자동 심사 규칙(트랙 A) 설계 초안', 'MID', '지난 3/2 회의에서 담보대출 쪽(트랙 A) 맡기로 한 것 관련해서, 설계 초안 정리했습니다. 배소현 선임 트랙 B랑 겹치는 부분(연체 이력 반영) 있어서 그 부분은 따로 표시해뒀습니다.\n\n1. 규칙 구조\n담보대출 자동 심사 규칙 44개를 아래 4개 그룹으로 나눴습니다.\n\n- 담보 평가군 (12개): LTV 계산, 담보물 시가 반영 로직\n- 상환능력 평가군 (15개): DSR 계산, 소득 대비 상환 비율\n- 예외 처리군 (12개): 중도상환, 담보 변경, 공동담보 케이스\n- 연체 이력군 (5개): *배소현 선임 트랙과 조율 필요*\n\n2. 담보 평가군 상세\nLTV(담보인정비율) 계산 시 담보물 시가를 어느 시점 기준으로 볼지가 쟁점이었는데, 최근 3개월 평균 시세를 쓰는 걸로 정리했습니다. 급등락 구간에서 왜곡될 수 있다는 우려가 있었는데, 3개월 평균이면 그 리스크가 어느 정도 상쇄됩니다.\n\n3. 예외 처리군 상세\n중도상환 케이스가 설계 당시 예상(7개)보다 실제로는 더 다양했습니다(12개). 아래 케이스들이 추가로 필요합니다.\n- 부분 중도상환 + 담보 유지\n- 전액 중도상환 + 담보 해지\n- 공동담보 중 일부만 상환\n\n4. 연체 이력군 (배소현 트랙과 조율 필요)\n연체 이력을 담보대출과 신용대출에서 같은 기준으로 볼지, 다르게 볼지 아직 결론이 안 났습니다. 다음 주 트랙 간 조율 미팅 때 같이 정하면 좋겠습니다.\n\n5. 일정\n1차 스프린트 마감(4/16) 기준으로 담보 평가군·상환능력 평가군은 4/10까지, 예외 처리군은 4/13까지 개발 완료 목표로 잡고 있습니다.\n\n설계 문서 전체는 첨부 파일로 올려뒀습니다. 리뷰 부탁드립니다.', '2026-03-09 09:00:00', '2026-03-09 09:00:00', NULL),
(3, 1, (SELECT id FROM users WHERE employee_no='DT22-0127'), '1차 스프린트 QA 발견 이슈 9건 상세 — 재현 조건 정리', 'HIGH', '3/30 회의에서 말씀드린 이슈 9건, 재현 조건이랑 우선순위 정리해서 다시 공유드립니다. 담당자분들 이거 보고 바로 착수하실 수 있게 최대한 구체적으로 적었습니다.\n\n[화면 이슈 — 5건]\n\n1. 서류 첨부 시 파일 용량 초과 에러 메시지 미표시 (Critical)\n- 재현: 10MB 이상 파일 첨부 시도 → 화면이 그냥 멈춘 것처럼 보임\n- 기대 동작: "파일 용량은 10MB 이하만 가능합니다" 안내 표시\n- 담당: 정하나\n\n2. 심사 이력 조회 페이지네이션 오류 (High)\n- 재현: 이력 21건 이상인 심사 건에서 2페이지 진입 시 1페이지 데이터가 중복 표시\n- 원인 추정: 백엔드 응답 스키마 쪽 offset 계산 문제로 보임(조민규 선임 확인 필요)\n- 담당: 정하나\n\n3. 첨부파일 미리보기 깨짐 (Medium)\n- 재현: PDF 첨부 후 미리보기 클릭 시 흰 화면만 표시\n- 담당: 정하나\n\n4. 담보 평가액 소수점 표기 오류 (Low)\n- 재현: 담보 평가액에 소수점 셋째 자리까지 표시됨(기대: 둘째 자리 반올림)\n- 담당: 정하나\n\n5. 심사 결과 알림 문구 오류 (Low)\n- 재현: 반려 케이스에서도 "승인되었습니다" 문구 노출\n- 담당: 정하나\n\n[자동 심사 로직 이슈 — 4건]\n\n6. 담보대출 중도상환 오분류 2건 (Critical)\n- 재현: 부분 중도상환 + 담보 유지 케이스가 "전액 상환"으로 잘못 분류됨\n- 원인: 예외 처리 로직 우선순위 버그로 확인(임건형 선임)\n- 담당: 임건형\n\n7. 심사 결과 코드 매핑 오류 (High)\n- 재현: 특정 조건(소득 검증 통과 + 담보 평가 보류)에서 결과 코드가 승인/보류 둘 다 아닌 미정의 값으로 나감\n- 담당: 조민규\n\n8~9. 나머지 2건은 재현 중이며 확인되는 대로 댓글로 업데이트하겠습니다.\n\n[정리]\n9건 중 6건은 원인 파악 완료, 3건은 재현/원인 확인 중입니다. 4/10 내부 마감 기준으로 전량 닫는 게 목표이고, 안 닫히면 완료 보고 일정 자체를 다시 논의해야 한다고 봅니다. 담당자분들 각자 항목 확인 부탁드립니다.', '2026-04-01 09:00:00', '2026-04-01 09:00:00', NULL),
(4, 1, (SELECT id FROM users WHERE employee_no='DT22-0116'), '1차 스프린트 결과 종합 정리', 'MID', '1차 스프린트가 끝나서 전체적으로 어떻게 진행됐는지 한 번 정리해봤습니다. 매 회의마다 나온 숫자들이 흩어져 있어서, 한 곳에 모아두면 다음 스프린트 계획할 때 참고하기 편할 것 같아서요.\n\n1. 개발 진행률\n- 자동 심사 로직: 확정 규칙 87개 중 71개(82%) 개발 완료\n- 화면 개발: 핵심 화면 5개 전체 1차 완료\n\n2. 이슈 처리 이력\n- 사전 발견 9건 전량 해결\n- QA 재검증 중 신규 3건 추가 발견(전부 중간 이하 심각도, 백로그 등록)\n\n3. 일정 준수 여부\n원래 계획 대비 큰 지연 없이 왔습니다. 다만 예외 처리 로직(임건형 선임 담당) 쪽에서 실제 케이스가 설계 당시 예상보다 많았던 점은 다음 스프린트 견적 잡을 때 참고해야 할 것 같습니다.\n\n4. 다음 스프린트\n자동 심사 로직 잔여 16개 규칙 개발이 최우선입니다. 대부분 트랙 B(신용대출, 배소현 선임) 쪽에 몰려 있어서, 인력 배분을 한 번 더 봐야 할 것 같습니다.\n\n의견 있으시면 댓글 부탁드립니다.', '2026-04-17 09:00:00', '2026-04-17 09:00:00', NULL),
(5, 1, (SELECT id FROM users WHERE employee_no='DT22-0017'), 'UI 전면 재작업 결정 공지 및 향후 일정', 'HIGH', '어제(6/11) 중간 시연에서 나온 결정사항, 다시 한번 정리해서 공유드립니다.\n\n1. 시연 결과\n자동 심사 처리 속도는 목표치(400ms 이하)를 충족했습니다. 다만 여신본부 실무진 대상 UX 피드백이 좋지 않았습니다. 핵심 지적은 "클릭 단계가 기존보다 오히려 늘었다"는 부분이었습니다.\n\n2. 결정\n윤태경 개발본부장님 배석하에 UI 전면 재작업을 결정했습니다. "숫자는 통과했으니 이제 사람이 쓰기 편한지가 남았다"는 게 이 결정의 핵심 취지입니다.\n\n3. 왜 이렇게 됐는지\n돌이켜보면, 화면 설계 초기에 클릭 단계 축소에만 집중하다 보니 정보 밀도를 충분히 고려하지 못했습니다. 서류 첨부 화면은 파일 종류별 업로드 버튼이 늘면서 오히려 클릭이 늘었고, 심사 결과 화면은 팝업 3단계를 거쳐야 상세 내역을 볼 수 있었습니다.\n\n4. 향후 일정\n남시우 FE파트장이 이번 주 내로 재작업 범위와 일정을 확정할 예정입니다. 여신본부에는 제가 재작업 일정을 공유하고 시연을 연기하겠다고 안내했습니다. 정식 오픈 일정 자체에는 영향이 없습니다.\n\n5. 당부\n일정이 다시 밀리는 건 아쉽지만, 결과적으로 더 나은 걸 내놓는 게 낫다고 봅니다. 재작업 범위가 나오면 바로 다시 공유드리겠습니다.', '2026-06-12 09:00:00', '2026-06-12 09:00:00', NULL),
(6, 1, (SELECT id FROM users WHERE employee_no='DT22-0142'), '타 금융사 여신 심사 UX 벤치마킹 결과', 'MID', 'UI 재작업 방향 잡기 전에, 다른 금융사들은 여신 심사 화면을 어떻게 만들어놨는지 몇 군데 훑어봤습니다. 공개된 화면 위주로만 봤고, 내부 로직까지는 당연히 알 수 없어서 화면 흐름 관점에서만 정리했습니다.\n\n1. 공통적으로 잘하는 것\n- 서류 첨부: 파일 종류를 구분해서 받되, 업로드 버튼은 하나로 통합하고 업로드 후 자동으로 종류를 분류해주는 방식이 많았습니다.\n- 결과 확인: 상세 내역을 팝업이 아니라 같은 화면 안에서 확장/축소하는 아코디언 형태로 보여주는 곳이 많았습니다.\n\n2. 저희 화면과 비교했을 때\n저희는 파일 종류별로 업로드 버튼을 따로 뒀는데, 이게 클릭 수 증가의 직접적인 원인이었습니다. 결과 확인도 팝업 중첩 구조라 뒤로 가기를 여러 번 눌러야 했고요.\n\n3. 제안\n- 서류 첨부: 업로드 버튼 통합 + 자동 분류 방식으로 변경\n- 심사 결과 확인: 팝업 대신 페이지 내 아코디언으로 변경\n\n다만 아코디언 방식은 정보 밀도가 낮아질 수 있다는 우려도 있어서, 재작업 범위 논의할 때 QA(문가온 파트장)랑 같이 검토하면 좋을 것 같습니다.\n\n참고한 화면 캡처는 별도 자료로 정리해서 공유드리겠습니다.', '2026-06-19 09:00:00', '2026-06-19 09:00:00', NULL),
(7, 1, (SELECT id FROM users WHERE employee_no='DT22-0127'), 'UI 재작업 QA 회고 — 회귀 테스트는 이렇게 했습니다', 'MID', '어제(7/21) 회의에서 재작업 완료를 확인했는데, QA 쪽에서 어떻게 검증했는지 과정을 좀 더 자세히 남겨두려고 합니다. 나중에 비슷한 규모 재작업 있을 때 참고할 수 있을 것 같아서요.\n\n1. 테스트 범위\n재작업 대상 8개 화면 전체 + 기존 기능 회귀 테스트 64건.\n\n2. 접근 방식\n재작업 전/후 화면을 나란히 두고 클릭 단계 수를 직접 세어봤습니다. 서류 첨부는 기존 5단계에서 3단계로, 심사 결과 확인은 3단계에서 2단계(초기 목표는 1단계였으나 정보 밀도 문제로 조정)로 줄었습니다.\n\n3. 발견된 이슈와 처리\n재작업 과정에서 정보 밀도 이슈가 한 번 있었습니다. 심사 결과 확인 화면을 1단계로 줄였더니 화면당 정보가 너무 없어서, 여러 화면을 오가야 하는 역설적인 상황이 생겼습니다. 이건 정하나 선임이 정보 밀도와 클릭 단계 사이 균형을 다시 잡아서 해결했습니다.\n\n4. 결과\n회귀 테스트 64건 전량 통과, 재작업 전 기능 중 깨진 것 없음 확인.\n\n5. 배운 점\n"클릭 단계 줄이기"를 목표로 잡으면 정보 밀도를 놓치기 쉽다는 걸 이번에 다시 확인했습니다. 다음에 비슷한 UX 개선 할 때는 두 지표를 처음부터 같이 놓고 보는 게 나을 것 같습니다.', '2026-07-22 09:00:00', '2026-07-22 09:00:00', NULL),
(8, 1, (SELECT id FROM users WHERE employee_no='DT22-0163'), '2차 스프린트 재개 — BE 트랙 현황 인수인계', 'MID', '2차 스프린트가 재작업 여파로 좀 밀렸다가 어제부터 재개됐습니다. 트랙별로 지금 상태 정리해서 남겨둡니다. 인력 재배치 논의도 있어서, 새로 합류하시는 분들도 참고하시면 좋을 것 같습니다.\n\n1. 현재 상태\n자동 심사 로직 잔여 16개 규칙 중 9개가 아직 미개발 상태입니다. 재작업 대응으로 인력이 잠시 그쪽으로 옮겨갔던 게 주된 이유입니다.\n\n2. 트랙별 현황\n- 트랙 A(담보대출, 조민규): 44개 규칙 전량 개발 완료, 재작업 지원에는 투입 안 됨\n- 트랙 B(신용대출, 배소현): 잔여 9개 중 대부분이 이쪽에 몰려 있음\n\n3. 왜 트랙 B에 몰렸나\n재작업 초반에 FE 인력이 부족해서 BE 쪽에서 일부 지원을 나갔는데, 트랙 B 담당자가 그 지원에 포함됐습니다. 트랙 A는 상대적으로 영향이 적었습니다.\n\n4. 앞으로\n구본재 PM실장이 인력 추가 투입을 검토 중입니다. 어느 트랙에서 지원 나갈지는 서강우 팀장과 협의 예정입니다. 새로 합류하시는 분은 트랙 B(신용대출) 쪽 문서부터 보시면 빠르게 파악되실 겁니다.\n\n문서 링크는 위키에 정리해뒀습니다.', '2026-08-05 09:00:00', '2026-08-05 09:00:00', NULL),
(9, 2, (SELECT id FROM users WHERE employee_no='DT22-0191'), 'A사 환율 API PoC 사전 테스트 결과', 'MID', '4/2 회의 전에 미리 공유드립니다. A사 환율 API PoC 진행 중인데, 지금까지 나온 수치를 정리했습니다.\n\n1. 응답 속도\n2주간 관찰한 평균 응답 시간은 118ms입니다(목표 200ms 이하). 피크 시간대(오전 9~10시)에도 큰 변동 없이 110~130ms 범위를 유지했습니다.\n\n2. 안정성\n타임아웃·오류 응답은 관찰 기간 동안 0건이었습니다.\n\n3. 비용\n호출 건당 단가는 B사보다 약간 높지만, C사보다는 낮습니다. 예상 월간 호출량 기준으로 계산하면 B사 대비 월 40만원 정도 차이입니다.\n\n4. 남은 확인 사항\n실제 서비스 트래픽 패턴(주문 몰리는 시간대)에서도 동일하게 안정적인지는 실환경 연동 이후에 확인이 필요합니다. 지금까지는 결과가 좋아서 4/2 회의에서 A사 확정 제안드리려고 합니다.', '2026-03-26 09:00:00', '2026-03-26 09:00:00', NULL),
(10, 2, (SELECT id FROM users WHERE employee_no='DT22-0157'), '주문 플로우 화면 재설계 시안 상세', 'MID', '4/2 회의에서 보여드린 재설계 시안, 세부 스펙 정리해서 공유드립니다.\n\n1. 변경 포인트\n- 환율 갱신 시각을 화면 상단에 고정 표시(기존에는 어디에도 안 보였음)\n- 호가 표시 항목에 툴팁 추가 — 오차 신고가 잦았던 부분이라 "왜 이 값이 표시되는지" 설명을 붙임\n- 주문 확인 단계에서 적용 환율을 한 번 더 명시\n\n2. 오하린 파트장 피드백 반영\n초안 리뷰 때 "갱신 시각 표시가 너무 작다"는 의견이 있어서, 폰트 크기를 키우고 색상도 눈에 띄게 조정했습니다.\n\n3. QA 검토 필요 사항\n정미르 팀장님 말씀대로 시안 확정 전에 QA 시나리오 검토 먼저 받으려고 합니다. 특히 갱신 시각 표시가 실시간으로 잘 갱신되는지가 핵심 확인 포인트일 것 같습니다.\n\n피그마 링크는 댓글에 남겨두겠습니다.', '2026-04-09 09:00:00', '2026-04-09 09:00:00', NULL),
(11, 2, (SELECT id FROM users WHERE employee_no='DT22-0191'), '환율 API 지연 이슈 — 원인 조사 경과', 'HIGH', '5/28 회의에서 말씀드린 환율 API 지연 건, 조사 진행 상황 공유드립니다.\n\n1. 증상 재확인\n5/29 실환경 연동 시점부터 A사 API 응답이 건당 3~5초까지 늘어났습니다. PoC 당시(118ms) 대비 25~40배입니다.\n\n2. 확인한 것\n- 네트워크 구간: 최윤성 DevOps팀장님 확인 결과 저희 쪽 네트워크는 이상 없음\n- A사 응답: A사 측에 문의한 결과 "내부 트래픽 급증으로 인한 일시적 저하"라는 답변\n- 요청 패턴: 저희 쪽 요청 방식은 PoC 때와 동일 (변경 없음)\n\n3. 아직 모르는 것\nA사가 말한 "일시적 저하"가 언제 해소될지 명확한 답을 못 받았습니다. 지수민 선임이 그동안 못 쓸 상황을 가정한 우회 방안을 같이 검토 중입니다.\n\n4. 오픈 일정 영향\n지금 시점에서는 QA 일정에 일부 영향이 있을 수 있으나, 정확한 지연 기간은 우회 방안이 정해지면 다시 안내드리겠습니다.', '2026-06-01 09:00:00', '2026-06-01 09:00:00', NULL),
(12, 2, (SELECT id FROM users WHERE employee_no='DT22-0055'), '캐싱 전략 검토 — TTL 캐싱을 제안하는 이유', 'MID', '환율 API 지연 우회 방안으로 캐싱을 검토 중인데, 왜 이 방식을 제안하는지 배경을 좀 더 자세히 적어봅니다.\n\n1. 문제의 본질\nA사 응답이 느려진 게 문제인데, 환율이라는 값 자체는 밀리초 단위로 바뀌는 게 아닙니다. 즉 "매번 최신값을 받아와야 하는가"에 대한 답이 사실 "아니오"에 가깝습니다.\n\n2. 검토한 대안들\n- 대안 1: B사로 즉시 전환 — 계약·연동 재작업에 시간이 더 걸림\n- 대안 2: A사 SLA 재협의로 해결 기다리기 — 시점을 예측할 수 없음\n- 대안 3: 짧은 TTL 캐싱 — 즉시 적용 가능, A사 지연과 무관하게 안정적\n\n3. TTL을 얼마로 잡을지\n환율은 통상 1분 내 큰 변동이 드뭅니다. TTL을 5초로 잡으면 사용자 체감상 "실시간"과 다를 바 없으면서, A사 호출 빈도 자체를 줄여서 지연 영향을 최소화할 수 있습니다.\n\n4. 제안\n캐싱 레이어를 정식 적용하는 방향으로 가되, A사와의 SLA 재협의는 별개로 계속 진행하는 게 맞다고 봅니다. 우회는 우회고, 근본 원인은 근본 원인대로 짚어야 하니까요.', '2026-06-16 09:00:00', '2026-06-16 09:00:00', NULL),
(13, 2, (SELECT id FROM users WHERE employee_no='DT22-0118'), '2분기 진행 상황 종합 정리', 'MID', '3월 킥오프부터 지금까지 진행 상황을 한 번 정리해서 공유드립니다. 이슈가 중간에 껴서 흐름이 좀 복잡해졌는데, 정리하고 넘어가면 좋을 것 같아서요.\n\n1. 목표 대비 진행\n- 주문 처리 시간: 목표 1.5초 이하, 개발 완료 시점 기준 실측 1.2초로 목표 상회 달성\n- 환율 오차 신고: 화면 개선 반영 완료, 실제 감소 효과는 QA 이후 운영 데이터로 확인 예정\n\n2. 일정 변화\n원래 계획보다 약 2주 지연됐습니다. 전적으로 5월 말 환율 API 지연 이슈 때문이며, 캐싱 레이어 정식 적용으로 복구 완료했습니다.\n\n3. 지금 상태\nQA 재개해서 진행 중입니다. 회귀 테스트 포함 42개 케이스 전량 다시 확인하고 있습니다.\n\n4. 남은 일정\n8월 중순 오픈 전 최종 리뷰를 목표로 하고 있습니다.', '2026-07-10 09:00:00', '2026-07-10 09:00:00', NULL),
(14, 2, (SELECT id FROM users WHERE employee_no='DT25-0052'), '잔여 이슈 대응 현황 — 브라우저별 표기 버그', 'MID', 'QA 진행 중 나온 잔여 이슈 2건 중 제가 맡은 브라우저별 표기 버그 관련해서 진행 상황 남겨둡니다.\n\n1. 증상\n환율 갱신 시각 표기가 특정 브라우저(구형 사파리)에서 깨져서 나옵니다. 시각 자체는 정상이지만 레이아웃이 밀려서 다른 텍스트와 겹칩니다.\n\n2. 원인\nCSS flex 속성 중 일부가 해당 브라우저 버전에서 지원이 안 되는 걸 확인했습니다. 다른 브라우저에서는 문제없어서 처음엔 원인 찾는 데 시간이 좀 걸렸습니다.\n\n3. 수정 방향\nflex 대신 그리드 레이아웃으로 바꿔서 호환성 문제를 우회하려고 합니다.\n\n4. 진행률\n수정안 적용 완료, 재현 테스트 중입니다. 8/1까지는 마무리될 것 같습니다.', '2026-07-31 09:00:00', '2026-07-31 09:00:00', NULL),
(15, 2, (SELECT id FROM users WHERE employee_no='DT22-0136'), '오픈 전 최종 QA 결과 및 회고', 'HIGH', '오늘 QA 최종 점검 회의에서 말씀드린 내용, 좀 더 자세히 남겨둡니다.\n\n1. 최종 결과\n총 42개 케이스 전량 통과. 잔여 이슈 8건도 전부 해결 확인했습니다.\n\n2. 성능 재확인\n주문 처리 시간 평균 1.2초(목표 1.5초 이하), 환율 연동 응답속도 평균 140ms로 안정적입니다.\n\n3. 이번 프로젝트에서 배운 점\n외부 API에 의존하는 기능은 아무리 PoC가 좋아도 실환경에서 다르게 동작할 수 있다는 걸 다시 확인했습니다. 캐싱처럼 "외부 요인과 무관하게 안정적인" 우회 경로를 처음부터 설계에 고려했으면 5월 이슈를 아예 피할 수 있었을 수도 있습니다.\n\n4. 다음 프로젝트에 참고할 점\n외부 연동이 있는 프로젝트는 설계 단계에서부터 "이 연동이 느려지거나 끊기면 어떻게 되는가"를 같이 검토하는 게 좋겠습니다.\n\n오픈 체크리스트는 하유진 파트장이 작성 중입니다.', '2026-08-06 09:00:00', '2026-08-06 09:00:00', NULL),
(16, 2, (SELECT id FROM users WHERE employee_no='DT22-0136'), 'QA 시나리오 초안 — 42개 케이스 구성 설명', 'LOW', '5/8 공유 예정인 QA 시나리오 최종본에 앞서, 지금까지 짠 케이스 구성을 미리 공유드립니다.\n\n1. 케이스 구성\n- 주문 처리: 24건 (정상 주문, 동시 주문, 예외 처리 등)\n- 환율 표시: 12건 (갱신 시각 표기, 오차 케이스 등)\n- 예외 케이스: 6건 (API 장애 시나리오 포함)\n\n2. 왜 이렇게 나눴는지\n주문 처리 로직을 건드리는 프로젝트라 회귀 리스크가 크다고 판단해서, 정상 케이스보다 예외·동시성 케이스 비중을 좀 높게 잡았습니다.\n\n피드백 있으시면 5/8 최종본 나가기 전에 말씀 부탁드립니다.', '2026-04-24 09:00:00', '2026-04-24 09:00:00', NULL),
(17, 3, (SELECT id FROM users WHERE employee_no='DT22-0200'), '미문서화 배치 잡 35개 목록 및 초기 파악 현황', 'HIGH', '6/1 회의에서 말씀드린 대로, 문서화 안 된 35개 배치 잡 목록 정리해서 공유드립니다.\n\n1. 전체 현황\n총 87개 잡 중 문서화된 12개를 제외한 35개가 조사 대상입니다.\n\n2. 카테고리별 분류\n- 정산 계산 관련: 14개\n- 데이터 정합성 체크: 9개\n- 대외계 연동: 8개\n- 기타(로그 정리, 알림 등): 4개\n\n3. 파악 난이도\n담당자가 바뀐 지 오래된 잡일수록 로직 파악이 어렵습니다. 특히 대외계 연동 8개는 대외 시스템 응답 형식과 얽혀 있어서 실행해보면서 역추적해야 하는 상황입니다.\n\n4. 진행 방식\n일단 실행 로그부터 훑어보고, 로직이 명확한 것부터 문서화하고 있습니다. 이번 주까지 정산 계산 관련 14개는 마무리할 수 있을 것 같습니다.\n\n중간중간 발견되는 특이사항은 계속 댓글로 업데이트하겠습니다.', '2026-06-05 09:00:00', '2026-06-05 09:00:00', NULL),
(18, 3, (SELECT id FROM users WHERE employee_no='DT22-0201'), '신규 정산 로직 설계 — 문서화된 12개 기준 1차안', 'MID', '최재원 선임 분석과 별개로, 이미 문서화된 12개 잡을 기준으로 신규 로직 설계를 먼저 시작했습니다. 진행 상황 공유드립니다.\n\n1. 설계 원칙\n기존 배치 잡 간 암묵적 의존관계를 코드가 아니라 명시적 설정 파일로 분리하는 걸 최우선 원칙으로 잡았습니다. 이번 장애의 근본 원인이 "의존관계가 코드에만 있어서 아무도 몰랐다"는 거였으니까요.\n\n2. 1차 설계 대상 (12개)\n정산 결과 집계, 수수료 계산, 정산 리포트 생성 등 상대적으로 독립적인 잡들입니다.\n\n3. 검증 방식 제안\n강지호 QA선임이 제안한 이중 계산(신규/레거시 결과 비교) 방식을 그대로 적용하려고 합니다. 신규 로직으로 돌린 결과와 레거시 결과를 나란히 비교해서 차이가 있으면 바로 알 수 있게 할 계획입니다.\n\n4. 다음 단계\n최재원 선임 분석이 끝나는 대로 강결합 잡 설계도 이어서 진행하겠습니다.', '2026-06-08 09:00:00', '2026-06-08 09:00:00', NULL),
(19, 3, (SELECT id FROM users WHERE employee_no='DT22-0200'), '강결합 배치 8개 — 왜 어려운지 하나씩 뜯어봤습니다', 'HIGH', '6/22 회의에서 말씀드린 강결합 배치 8개, 각각 어떤 부분이 문제인지 상세히 정리했습니다.\n\n1. 대외계 연동 5개\n대외 시스템(회계 시스템)의 응답 형식에 맞춰 임시방편으로 짜여 있습니다. 예를 들어 배치 하나는 회계 시스템이 특정 필드를 비워서 보내는 걸 전제로 예외 처리가 하드코딩돼 있었습니다. 그대로 옮기면 같은 문제가 재발할 수 있어서, 인터페이스 자체를 다시 설계해야 합니다.\n\n2. 회계 연동 3개\n결산 시점과 정산 배치 실행 시점이 맞물려야 하는 잡들입니다. 순서가 어긋나면 숫자가 안 맞게 되는데, 이 순서 의존성이 지금까지 코드 주석 하나 없이 실행 스케줄러 설정에만 암묵적으로 있었습니다.\n\n3. 공통적으로 필요한 작업\n8개 전부 인터페이스 설계부터 다시 시작해야 하는 수준입니다. 단순 리팩토링이 아니라 사실상 재설계에 가깝습니다.\n\n4. 예상 영향\n이 부분 때문에 전체 분석 일정이 2주 추가로 밀릴 것 같습니다. 다음 회의에서 조태현 파트장님께 별도로 보고드리겠습니다.', '2026-06-29 09:00:00', '2026-06-29 09:00:00', NULL),
(20, 3, (SELECT id FROM users WHERE employee_no='DT22-0198'), '일정 재수립 공지 — 1단계 분석 완료 목표 재조정', 'HIGH', '어제(7/13) 회의에서 논의된 일정 재수립 관련해서, 팀 전체에 다시 공유드립니다.\n\n1. 지연 배경\n강결합 배치 8개 분석 난도가 예상보다 높아, 1단계(레거시 분석) 완료 목표를 2주 순연합니다.\n\n2. 재조정된 일정\n- 1단계(레거시 분석) 완료: 8/4 목표\n- 2단계(신규 설계) 착수: 1단계 완료 즉시\n\n3. 서강우 팀장 코멘트\n"정산은 잘못되면 신뢰 문제로 바로 이어지니까, 서두르다 놓치는 것보다는 낫습니다." 이번 지연은 품질을 위한 것으로 판단하고 있습니다. 남기훈 부사장님께는 서강우 팀장님이 직접 보고하셨습니다.\n\n4. 팀에 당부\n일정이 늦어지는 게 아쉽지만, 여기서 놓치는 부분이 있으면 나중에 더 큰 문제로 돌아옵니다. 남은 기간 동안 강결합 8개 분석에 집중해주시기 바랍니다.', '2026-07-14 09:00:00', '2026-07-14 09:00:00', NULL),
(21, 3, (SELECT id FROM users WHERE employee_no='DT22-0119'), '프로젝트 1단계 진행 상황 종합 정리', 'MID', '5월 킥오프부터 지금까지 진행 상황을 정리해서 공유드립니다.\n\n1. 목표 재확인\n재발 방지 요건 세 가지: 배치 잡 의존관계 문서화, 실패 시 자동 재시도/알림 체계, 정산 결과 자동 검증 로직.\n\n2. 1단계(레거시 분석) 결과\n47개 배치 잡 전량 분석 완료. 강결합 8개를 포함해 의존관계 문서화 100% 달성. 당초 목표(6/1 전후) 대비 약 6주 지연됐으나, 재발 방지의 핵심인 "의존관계 파악"은 확실하게 끝냈습니다.\n\n3. 2단계(신규 설계) 착수 상황\n임소현 선임 담당으로 문서화된 12개 기준 설계는 20% 진행됐습니다. 강결합 8개는 이제 설계 시작 단계입니다.\n\n4. 일정 전망\n1단계가 예상보다 오래 걸린 만큼, 2단계는 설계 완료 목표를 9월 말로 보수적으로 재설정했습니다.', '2026-08-11 09:00:00', '2026-08-11 09:00:00', NULL),
(22, 3, (SELECT id FROM users WHERE employee_no='DT22-0137'), '정산 검증 방법론 리서치 — 이중 계산 방식 관련', 'MID', '이중 계산(신규/레거시 결과 비교) 검증 방식을 제안드렸었는데, 관련해서 다른 금융권 사례들을 좀 찾아봤습니다.\n\n1. 왜 찾아봤나\n이중 계산이 안전한 방식이라는 건 알겠는데, 실제로 어떻게 운영하는 게 효율적인지 참고할 사례가 필요했습니다.\n\n2. 찾은 패턴\n- 전량 이중 계산 후 전환: 가장 안전하지만 리소스 부담이 큼\n- 샘플링 이중 계산: 일부만 비교하고 나머지는 신뢰\n- 점진적 전환 + 상시 모니터링: 신규 로직 비중을 서서히 늘리면서 차이 발생 시 알림\n\n3. 제안\n저희 규모(정산 배치 47개)를 고려하면, 처음에는 전량 이중 계산으로 시작해서 안정성이 확인된 잡부터 점진적으로 전환하는 방식이 맞을 것 같습니다. 리소스는 좀 들겠지만 정산이라는 영역 특성상 안전이 우선이라고 봅니다.\n\n4. 다음 단계\n2단계 설계에 이 검증 전략을 반영하는 게 어떨지, 임소현 선임과 논의해보면 좋겠습니다.', '2026-07-02 09:00:00', '2026-07-02 09:00:00', NULL),
(23, 3, (SELECT id FROM users WHERE employee_no='DT22-0202'), '배치 잡 의존관계 조사 진행 방법 — 후임자를 위한 메모', 'LOW', '저 말고 다른 분이 나중에 이 조사를 이어받을 수도 있을 것 같아서, 지금까지 써온 방법을 정리해둡니다.\n\n1. 1단계: 실행 로그 확보\n최근 3개월치 배치 실행 로그를 먼저 뽑습니다. 어떤 순서로 실행되는지, 실패 시 어떤 잡이 같이 실패하는지가 여기서 대부분 드러납니다.\n\n2. 2단계: 코드 읽기\n로그로 안 잡히는 의존관계(같은 테이블을 참조하는데 실행 순서가 안 맞으면 문제가 되는 경우 등)는 코드를 직접 읽어야 합니다.\n\n3. 3단계: 실행 담당자 인터뷰\n담당자가 아직 있다면 직접 물어보는 게 제일 빠릅니다. 다만 담당자가 바뀐 지 오래된 잡은 이 단계를 건너뛰고 1·2단계에 더 의존해야 합니다.\n\n4. 헷갈렸던 부분\n같은 이름의 배치 잡이 부서별로 따로 있는 경우가 있어서, 잡 이름만 보고 같은 건 줄 알았다가 다른 잡이었던 적이 있습니다. 잡 ID까지 꼭 같이 확인하시길 권합니다.', '2026-06-15 09:00:00', '2026-06-15 09:00:00', NULL),
(24, 3, (SELECT id FROM users WHERE employee_no='DT22-0198'), '1단계 레거시 분석 마무리 회고', 'MID', '1단계 분석이 어제 끝나서, 이 과정 돌아보면서 느낀 점 정리해봤습니다.\n\n1. 예상과 달랐던 부분\n처음에는 "문서화만 하면 되는 일"이라고 생각했는데, 실제로는 코드 하나하나를 실행해가며 역추적하는 작업이었습니다. 특히 대외계 연동 잡들은 왜 그렇게 짜여 있는지 이유를 아는 사람이 아무도 없었습니다.\n\n2. 잘한 선택\n강결합 8개를 나중에 몰아서 보지 않고, 6월 중간에 별도로 떼어내서 집중 분석한 게 결과적으로 도움이 됐습니다. 덕분에 일정 재수립도 데이터 기반으로 할 수 있었고요.\n\n3. 아쉬운 점\n초기 견적(레거시 분석 1개월)이 너무 낙관적이었습니다. 다음에 비슷한 레거시 분석 작업을 할 때는 문서화율(지금은 12/87, 14%)을 먼저 확인하고 그걸 기준으로 견적을 잡는 게 나을 것 같습니다.\n\n2단계 설계 진행 상황은 계속 공유드리겠습니다.', '2026-08-04 09:00:00', '2026-08-04 09:00:00', NULL),
(25, 4, (SELECT id FROM users WHERE employee_no='DT22-0095'), '현장 인터뷰 상세 — 야간 배치 시간 관련 실무진 코멘트 모음', 'MID', '여신·수신 부서 실무진 8명 인터뷰 중 반복적으로 나온 얘기들을 정리했습니다.\n\n1. 공통 불만\n야간 배치 시간이 2년 전 2시간에서 지금 4시간으로 늘었다는 점을 8명 중 6명이 언급했습니다. "아침에 출근해서 배치가 안 끝나 있으면 그날 업무를 못 시작한다"는 얘기가 인상적이었습니다.\n\n2. 구체적 사례\n한 실무진은 월말 마감일에 배치가 예정보다 1시간 늦게 끝나서, 당일 여신 승인 건 5건을 다음 날로 넘긴 적이 있다고 했습니다.\n\n3. 시사점\n배치 시간 증가가 단순 불편이 아니라 실제 업무 지연으로 이어지고 있다는 게 확인됐습니다. 진단 보고서에 이 부분을 구체적 근거(추이 그래프 등)로 넣으면 설득력이 있을 것 같습니다.\n\n나머지 2명 인터뷰 내용은 정리되는 대로 추가하겠습니다.', '2026-06-30 09:00:00', '2026-06-30 09:00:00', NULL),
(26, 4, (SELECT id FROM users WHERE employee_no='DT22-0092'), '노후 모듈 진단 등급 기준 설명', 'MID', '진단 결과에서 "교체 필요" 등급을 어떤 기준으로 매겼는지 설명드립니다.\n\n1. 등급 기준\n- 교체 필요: 유지보수만으로 한계, 구조적 재작업 없이는 성능/안정성 개선 불가\n- 개선 필요: 부분 수정으로 개선 가능\n- 양호: 현행 유지 가능\n\n2. 교체 필요 등급 판정 사례 — 배치 스케줄러\n처리 시간이 2년간 지속적으로 증가하는 추세이고, 원인이 특정 로직 하나가 아니라 구조 자체(단일 스레드 순차 처리)에 있어서 부분 수정으로는 해결이 안 됩니다.\n\n3. 다른 두 모듈(여신 심사 엔진, 외환 정산 모듈)도 유사하게 구조적 원인으로 판정했습니다.\n\n이 기준으로 계속 진단 이어가겠습니다.', '2026-07-06 09:00:00', '2026-07-06 09:00:00', NULL),
(27, 4, (SELECT id FROM users WHERE employee_no='DT23-0027'), '데이터 이관 실사 — 미문서화 구간 상세', 'HIGH', '데이터 실사 결과 발견한 미문서화 이관 이력 관련 상세 내용입니다.\n\n1. 발견 규모\n전체 데이터의 약 15%에서 이관 이력 문서가 없습니다.\n\n2. 원인 추정\n시스템이 여러 차례 증축되면서, 증축 시점마다 이관 작업을 했는데 그 기록이 남아있는 것도 있고 없는 것도 있습니다. 최근 증축(3년 전)은 기록이 있지만, 그 이전 것들은 거의 없습니다.\n\n3. 리스크\n향후 실제 이관 작업 시, 이 15% 구간에서 데이터 정합성 문제가 발생할 가능성이 있습니다. 별도로 리스크 항목에 명시하겠습니다.\n\n4. 제안\n최종 보고서에 "이관 전 15% 구간 재검증 필요"를 권고사항으로 넣는 게 좋겠습니다.', '2026-07-13 09:00:00', '2026-07-13 09:00:00', NULL),
(28, 4, (SELECT id FROM users WHERE employee_no='DT22-0016'), '산출물 구성 확정 공지', 'MID', '보고서 목차 최종 확정해서 공유드립니다.\n\n1. 구성\n1) 현황 진단 2) 리스크 평가 3) 우선순위별 로드맵(단기/중기/장기)\n\n2. 왜 이 순서인가\n고객사가 예산 제약이 있는 상황이라, 로드맵을 단순 나열이 아니라 우선순위로 명확히 보여주는 게 중요하다고 판단했습니다.\n\n3. 단기 항목은 견적 수준까지\n안세희 팀장님 요청대로, 단기 항목은 대략적인 비용 규모까지 붙여서 구체성을 높이려고 합니다.\n\n각자 담당 섹션 초안 작성 부탁드립니다.', '2026-07-27 09:00:00', '2026-07-27 09:00:00', NULL),
(29, 4, (SELECT id FROM users WHERE employee_no='DT22-0016'), '중간 진행 상황 정리', 'MID', '한 달간 진행 상황을 정리했습니다.\n\n1. 인터뷰: 완료 (8명 전원)\n2. 데이터 실사: 완료, 미문서화 구간 15% 발견\n3. 진단: 노후 모듈 3개 "교체 필요" 등급 확정\n4. 산출물: 목차 확정, 작성 착수\n\n일정상 큰 지연은 없습니다. 다음 마일스톤은 8/3 산출물 최종 점검입니다.', '2026-08-01 09:00:00', '2026-08-01 09:00:00', NULL),
(30, 4, (SELECT id FROM users WHERE employee_no='DT22-0096'), '타 저축은행 코어뱅킹 현대화 사례 리서치', 'LOW', '공개된 자료 기준으로 유사 규모 저축은행들의 코어뱅킹 현대화 사례를 찾아봤습니다.\n\n1. 공통 패턴\n한 번에 전면 교체하기보다, 노후도가 높은 모듈부터 단계적으로 교체하는 방식이 많았습니다.\n\n2. 시사점\n저희가 제안하려는 우선순위 로드맵 방향과 일치합니다. 로드맵 발표할 때 이런 업계 패턴도 같이 언급하면 설득력이 더해질 것 같습니다.\n\n참고 자료는 별도 파일로 정리했습니다.', '2026-07-20 09:00:00', '2026-07-20 09:00:00', NULL),
(31, 4, (SELECT id FROM users WHERE employee_no='DT22-0097'), '고객사 현장 미팅 시 유의사항 메모', 'LOW', '이번 프로젝트 현장 미팅 몇 번 다녀오면서 느낀 점, 다음에 비슷한 컨설팅 들어가시는 분들 참고하시라고 남겨둡니다.\n\n1. 실무진과 경영진 반응이 다름\n실무진은 구체적 불편사항 위주로 얘기하고, 경영진은 예산·일정 위주로 묻습니다. 같은 미팅에 둘 다 있을 때는 양쪽 다 챙겨야 합니다.\n\n2. 자료는 미리 공유\n미팅 당일 자료를 처음 보여주면 반응이 즉흥적이라, 하루 전에 미리 공유하면 더 깊은 논의가 가능했습니다.', '2026-06-15 09:00:00', '2026-06-15 09:00:00', NULL),
(32, 4, (SELECT id FROM users WHERE employee_no='DT22-0100'), '1차 산출물 작성 회고', 'MID', '보고서 초안 작성하면서 느낀 점 남겨둡니다.\n\n1. 어려웠던 점\n노후 모듈 3개가 왜 교체가 필요한지 "근거 데이터"로 보여주는 게 생각보다 어려웠습니다. 정성적으로는 다 알고 있는데, 숫자로 보여줘야 설득력이 생기더라고요. 배치 스케줄러는 처리 시간 추이 그래프로 해결했습니다.\n\n2. 다음에 참고할 점\n진단 프로젝트는 착수 초반부터 "이 문제를 숫자로 어떻게 보여줄지"를 같이 고민하면서 데이터를 모으는 게 나을 것 같습니다. 나중에 몰아서 찾으려니 시간이 더 걸렸습니다.', '2026-08-04 09:00:00', '2026-08-04 09:00:00', NULL),
(33, 5, (SELECT id FROM users WHERE employee_no='DT22-0098'), '계약 범위 괴리 2건 상세 정리', 'HIGH', '3/24 회의에서 언급한 괴리 2건, 자세히 정리했습니다.\n\n1. 실시간 신용정보 조회\n계약서상 배치 조회(일 1회)로 명시돼 있는데, 실무진은 실시간 조회를 원합니다. 이유를 물어보니 "심사 도중 고객이 추가 대출을 받으면 그 정보가 바로 반영돼야 정확한 판단이 가능하다"는 겁니다. 이해는 되지만 계약 범위를 넘어서는 요청입니다.\n\n2. 결재선 1단계 추가\n계약 당시 논의한 결재선은 3단계였는데, 실제로는 리스크 금액 기준으로 4단계까지 있는 걸 확인했습니다. 계약 당시 이 기준을 놓친 것으로 보입니다.\n\n3. 대응 방향\n1번은 추가 계약 협의가 필요한 사안이라 판단됩니다. 2번은 계약서 문구 해석에 따라 기존 범위 내로 볼 수도 있어서, 안세희 팀장님이 서일캐피탈과 직접 조율하기로 했습니다.', '2026-03-25 09:00:00', '2026-03-25 09:00:00', NULL),
(34, 5, (SELECT id FROM users WHERE employee_no='DT24-0032'), '대외연계 API 설계 리스크 상세 분석', 'HIGH', 'C안(하이브리드 구조) 확정 이후, 대외연계 API 설계에서 예상되는 리스크를 정리했습니다.\n\n1. 리스크 1 — 신용정보 인증 방식\n외부 신용정보 기관 인증 방식이 저희가 기존에 써오던 방식과 달라서, 별도 인증 모듈이 필요합니다.\n\n2. 리스크 2 — 연동 지점 증가\n신용정보, 코어뱅킹, 전자결재 세 곳을 동시에 연동하다 보니, 하나가 느려지면 전체 응답이 밀리는 구조적 리스크가 있습니다.\n\n3. 리스크 3 — 장애 시 폴백\n외부 연동이 끊겼을 때 심사 프로세스를 어떻게 진행할지(수동 전환 등) 아직 정의가 안 됐습니다.\n\n4. 제안\n리스크 3(장애 시 폴백)은 설계 단계에서 반드시 짚고 가야 한다고 봅니다. 다음 회의 안건으로 올려주시면 좋겠습니다.', '2026-06-29 09:00:00', '2026-06-29 09:00:00', NULL),
(35, 5, (SELECT id FROM users WHERE employee_no='DT22-0196'), '보안 요건 반영 — TLS 1.3 전환 작업 상세', 'MID', '암호화 방식 변경 작업 진행 상황 공유드립니다.\n\n1. 변경 내용\n기존 TLS 1.2에서 TLS 1.3 + 필드 단위 추가 암호화로 변경 중입니다.\n\n2. 작업 범위\n대외연계 API 3개(신용정보, 코어뱅킹, 전자결재) 전체 통신 구간에 적용해야 합니다.\n\n3. 예상 이슈\n신용정보 기관 쪽 시스템이 TLS 1.3을 지원하는지 아직 확인 전입니다. 지원 안 하면 별도 협의가 필요할 수 있습니다.\n\n4. 일정\n설계 반영은 예정대로 1주 내 완료 가능할 것 같습니다. 신용정보 기관 확인 결과는 따로 공유드리겠습니다.', '2026-08-01 09:00:00', '2026-08-01 09:00:00', NULL),
(36, 5, (SELECT id FROM users WHERE employee_no='DT22-0016'), '계약 재조정 결과 공지', 'HIGH', '서일캐피탈과의 계약 범위 재조정 결과를 공식적으로 공지드립니다.\n\n1. 실시간 신용정보 조회\n추가 계약으로 별도 진행하기로 확정했습니다. 본 프로젝트 범위에는 포함되지 않습니다.\n\n2. 결재선 1단계 추가\n기존 계약 범위 내 반영으로 정리됐습니다. 이 부분은 추가 비용 없이 저희가 흡수합니다.\n\n3. 배경\n계약 당시 리스크 금액 기준 결재선을 세밀하게 파악하지 못했던 저희 쪽 실수도 있어서, 이 부분은 범위 내로 처리하는 게 맞다고 판단했습니다.\n\n이견 있으시면 이번 주까지 말씀 부탁드립니다.', '2026-06-02 09:00:00', '2026-06-02 09:00:00', NULL),
(37, 5, (SELECT id FROM users WHERE employee_no='DT22-0017'), '프로젝트 중간 점검 — 6개월 진행 종합', 'MID', '2월 착수 이후 진행 상황을 종합 정리했습니다.\n\n1. 완료된 것\n요구사항 분석(12단계 프로세스), 아키텍처 설계(C안, 95% 진행)\n\n2. 계약 관련\n괴리 2건 모두 해소. 실시간 신용정보는 별도 계약, 결재선은 범위 내 처리.\n\n3. 남은 리스크\n보안 요건 반영(TLS 1.3)이 신용정보 기관 지원 여부에 달려 있어 약간의 불확실성이 있습니다.\n\n4. 다음 단계\n설계 문서 최종본 완성 후 부사장님 기술 승인, 이후 개발 착수 예정입니다.', '2026-08-12 09:00:00', '2026-08-12 09:00:00', NULL),
(38, 5, (SELECT id FROM users WHERE employee_no='DT24-0034'), '실시간 처리 성능 요건 관련 참고 자료', 'LOW', '대외연계 API 성능 요건 정하는 데 참고할 만한 사례들 찾아봤습니다.\n\n1. 참고 사례\n타 캐피탈사들의 여신심사 시스템 응답 시간 목표는 보통 100~150ms 사이였습니다.\n\n2. 저희 상황\n정예린 선임 프로토타입 테스트 결과 응답 시간 문제는 없었는데(신용정보 인증만 별도 모듈로 분리), 참고 사례와 비교해도 무리 없는 수준입니다.\n\n3. 제안\n성능 요건 정의서에 100ms 이내를 목표로 명시하면 어떨까 합니다.', '2026-07-06 09:00:00', '2026-07-06 09:00:00', NULL),
(39, 5, (SELECT id FROM users WHERE employee_no='DT23-0030'), '현장 상주 시 커뮤니케이션 채널 활용 팁', 'LOW', '현장 상주 시작한 지 한 달 정도 됐는데, 도움이 됐던 방법 남겨둡니다.\n\n1. 공식 채널 개설\n개설한 공용 채널에 매일 그날 있었던 인터뷰 요약을 짧게라도 올려뒀더니, 본사에 있는 팀원들도 진행 상황을 실시간으로 파악할 수 있어서 좋았습니다.\n\n2. 현장 실무진과의 관계\n첫 인터뷰 때는 다들 경계하는 느낌이었는데, 매번 정리한 내용을 다시 확인받는 식으로 진행하니 신뢰가 쌓여서 나중엔 먼저 얘기해주시는 경우도 많았습니다.', '2026-03-10 09:00:00', '2026-03-10 09:00:00', NULL),
(40, 5, (SELECT id FROM users WHERE employee_no='DT22-0094'), '아키텍처 설계 마무리 회고', 'MID', '설계가 거의 마무리돼서 돌아보는 글 남깁니다.\n\n1. C안(하이브리드) 선택이 맞았나\n돌이켜보면 고객사가 기존 방식 유지를 원했던 요구사항과 잘 맞아떨어진 선택이었습니다. 완전 분리(A안)로 갔으면 나중에 다시 뜯어고쳤을 수도 있습니다.\n\n2. 아쉬운 점\n보안 요건이 설계 후반부에 추가로 나오면서 일정이 1주 밀렸습니다. 금융권 대상 프로젝트는 보안 요건을 초기 요구사항 분석 단계에서부터 명시적으로 물어봤어야 했다고 생각합니다.\n\n3. 다음 프로젝트에 참고할 점\n금융권 고객사 프로젝트는 착수 시점에 보안팀을 처음부터 참여시키는 게 나을 것 같습니다.', '2026-08-11 09:00:00', '2026-08-11 09:00:00', NULL),
(41, 6, (SELECT id FROM users WHERE employee_no='DT22-0104'), '데이터 항목 매핑 진행 — 14개 항목 상세 현황', 'MID', '매핑 작업 40% 완료 시점 상세 현황입니다.\n\n1. 완료된 항목 (5개)\n기존 데이터로 바로 매핑 가능한 항목들 — 계좌 잔액, 거래 이력 등 이미 표준화돼 있던 항목입니다.\n\n2. 진행 중 항목 (7개)\n신규 필드 추가나 계산 로직이 필요한 항목들입니다. 특히 "자산관리 카테고리" 항목은 기존 데이터에 없는 분류 체계라 새로 설계해야 합니다.\n\n3. 컴플라이언스 추가 항목 (2개)\n강지원 선임 리뷰로 추가된 항목입니다. 필수는 아니지만 감사 대응을 고려해 포함했습니다.\n\n5월 중 나머지 완료 목표로 계속 진행하겠습니다.', '2026-04-29 09:00:00', '2026-04-29 09:00:00', NULL),
(42, 6, (SELECT id FROM users WHERE employee_no='DT22-0105'), '배치 연동 설계 — 전송 주기 변경 영향 분석', 'MID', '일 1회에서 2회로 전송 주기가 바뀌는 데 따른 영향을 분석했습니다.\n\n1. 기존 배치 스케줄 확인\n현재 돌고 있는 배치들과 시간대가 겹치는지 확인한 결과, 다행히 충돌하는 배치는 없었습니다.\n\n2. 리소스 영향\n전송 횟수가 늘어나는 만큼 서버 리소스 사용량도 늘어나는데, 현재 여유 리소스로 충분히 감당 가능한 수준으로 확인했습니다.\n\n3. 설계 방향\n기존 배치 구조를 크게 바꾸지 않고, 전송 잡을 하나 더 추가하는 방식으로 갈 수 있을 것 같습니다.\n\n설계안 문서는 다음 주 초 공유드리겠습니다.', '2026-05-25 09:00:00', '2026-05-25 09:00:00', NULL),
(43, 6, (SELECT id FROM users WHERE employee_no='DT23-0031'), '규격 해석 이견 — 금융위 가이드라인 재확인 결과', 'HIGH', '6/24 회의에서 나왔던 규격 해석 이견 관련 재확인 결과 공유드립니다.\n\n1. 쟁점\n신규 항목 중 하나가 "해당 없음"일 때 필드를 아예 빼야 하는지, null로 채워야 하는지가 가이드라인에 명확히 안 나와 있습니다.\n\n2. 재확인 결과\n금융위 가이드라인 문서를 다시 봐도 명확한 답이 없었습니다. 유사 사례(타사 대응 사례 등 공개된 정보)를 참고한 결과, 보수적으로 필드는 유지하고 null 처리하는 쪽이 더 안전하다고 판단됩니다.\n\n3. 이유\n필드를 아예 빼면 나중에 감사에서 "왜 이 필드가 없냐"는 질문을 받을 수 있는데, null로 채워두면 최소한 "값이 없다"는 걸 명시적으로 보여줄 수 있습니다.\n\n이 방향으로 반영하겠습니다. 이견 있으시면 말씀 부탁드립니다.', '2026-06-25 09:00:00', '2026-06-25 09:00:00', NULL),
(44, 6, (SELECT id FROM users WHERE employee_no='DT22-0023'), '마이데이터 3.0 대응 목표 재확인 공지', 'MID', '킥오프 이후 다시 한번 목표를 명확히 공지드립니다.\n\n1. 목표\n2027년 2월 규제 시행에 맞춰 신규 항목 12개(추가 2개 포함 14개) 전송 대응 완료.\n\n2. 내부 목표\n규제 마감보다 이르게, 2026년 말까지 완료하는 걸 내부 목표로 잡습니다. 규제 대응은 항상 막판에 이슈가 생기니, 여유를 두려는 취지입니다.\n\n3. 우선순위\n다른 프로젝트 대비 이 프로젝트는 마감이 고정돼 있는 규제 대응이라, 일정 관리를 최우선으로 봐주시기 바랍니다.', '2026-04-15 09:00:00', '2026-04-15 09:00:00', NULL),
(45, 6, (SELECT id FROM users WHERE employee_no='DT22-0102'), '중간 진행 상황 정리', 'MID', '4월 킥오프 이후 진행 상황을 정리합니다.\n\n1. 매핑: 완료 (14개 전체)\n2. 배치 설계: 완료\n3. 배치 개발: 55% 진행, 규격 해석 이견 1건은 보수적 해석으로 결론\n4. 남은 일정: 배치 개발 완료 후 데이터 검증 단계 진입 예정\n\n내부 목표(연말 완료) 대비 순조롭게 가고 있습니다.', '2026-07-20 09:00:00', '2026-07-20 09:00:00', NULL),
(46, 6, (SELECT id FROM users WHERE employee_no='DT23-0003'), '금융위 가이드라인 유사 해석 사례 조사', 'LOW', '규격 해석 이견 관련해서 참고할 만한 자료를 찾아본 내용입니다.\n\n1. 조사 방법\n공개된 마이데이터 관련 세미나 자료, 협회 공지 등을 확인했습니다.\n\n2. 결과\n명시적인 지침은 못 찾았지만, 몇몇 발표 자료에서 "값이 없을 때는 null 처리를 권장"한다는 뉘앙스의 언급이 있었습니다.\n\n김태율 파트장님께 참고 자료로 전달드렸습니다.', '2026-06-10 09:00:00', '2026-06-10 09:00:00', NULL),
(47, 6, (SELECT id FROM users WHERE employee_no='DT25-0046'), '데이터 검증 절차 안내', 'LOW', '데이터 검증 착수를 앞두고, 진행 방식을 미리 안내드립니다.\n\n1. 1단계: 표본 검증\n먼저 표본 데이터로 정합성을 확인합니다.\n\n2. 2단계: 전체 범위 확대\n표본에서 이상 없으면 전체 범위로 넓혀서 검증합니다.\n\n3. 참고\n표본 검증에서 이상이 발견되면 원인 파악 전까지 전체 확대를 미루겠습니다.', '2026-07-25 09:00:00', '2026-07-25 09:00:00', NULL),
(48, 6, (SELECT id FROM users WHERE employee_no='DT22-0106'), '이상 데이터 정제 작업 회고', 'MID', '이상 데이터 120건 정제 작업을 마치고 돌아본 내용입니다.\n\n1. 발견된 패턴\n대부분 예전 시스템에서 넘어온 값이 신규 항목 형식과 안 맞는 케이스였습니다. 데이터 자체보다는 형식 문제가 대부분이었습니다.\n\n2. 처리 방식\n데이터를 직접 고치는 대신 변환 로직에서 처리하도록 해서, 원본 데이터는 건드리지 않았습니다. 이렇게 하면 나중에 원인 재확인이 필요할 때도 원본이 남아있어서 좋습니다.\n\n3. 배운 점\n레거시 데이터 정제는 데이터를 고치기보다 변환 계층에서 흡수하는 게 안전하다는 걸 다시 확인했습니다.', '2026-08-08 09:00:00', '2026-08-08 09:00:00', NULL),
(49, 7, (SELECT id FROM users WHERE employee_no='DT24-0041'), '모델 실험 3종 상세 비교 결과', 'MID', '4/10 회의에서 보고드린 3종 알고리즘 실험, 세부 수치 정리해서 공유드립니다.\n\n1. 그래디언트 부스팅\n오탐률 12% 개선. 추론 속도도 목표(100ms 이내) 대비 여유 있음.\n\n2. 딥러닝 앙상블\n개선폭은 비슷한 수준이나 추론 시간이 기존 대비 3배 이상. 실시간 처리 목표에 안 맞습니다.\n\n3. 랜덤포레스트 개선형\n개선폭이 3~4% 수준으로 미미했습니다. 기존 룰 기반과 큰 차이가 없었습니다.\n\n4. 결론\n그래디언트 부스팅이 성능·속도 균형이 가장 좋습니다. 정밀 튜닝 여지도 있어 보여서, 이쪽으로 집중하는 게 맞다고 봅니다.\n\n튜닝 결과는 다음 주 중 다시 공유드리겠습니다.', '2026-04-11 09:00:00', '2026-04-11 09:00:00', NULL),
(50, 7, (SELECT id FROM users WHERE employee_no='DT22-0205'), '서빙 아키텍처 최적화 상세 — 피처 캐싱 적용 방식', 'HIGH', '5/22 회의에서 지적된 성능 이슈(150ms) 관련 최적화 방향 상세 공유드립니다.\n\n1. 병목 지점 분석\n모델 추론 자체는 빠른데, 피처 조회 과정에서 시간이 걸리고 있었습니다. 매 요청마다 피처를 새로 계산하는 구조였습니다.\n\n2. 해결 방향 — 피처 사전 캐싱\n자주 쓰이는 피처를 미리 계산해서 캐싱해두는 방식으로 전환합니다. TTL은 1분으로 잡아서 최신성도 크게 해치지 않으면서 속도를 확보하려고 합니다.\n\n3. 왜 1분인가\nFDS 피처 특성상(최근 거래 패턴 등) 1분 이내 변화는 판단에 큰 영향을 주지 않는다고 판단했습니다.\n\n4. 예상 효과\n초기 테스트에서 150ms → 90ms대로 줄어드는 걸 확인했습니다. 목표(100ms 이내) 달성 가능할 것 같습니다.', '2026-05-30 09:00:00', '2026-05-30 09:00:00', NULL),
(51, 7, (SELECT id FROM users WHERE employee_no='DT22-0110'), '파이프라인 잔여 이슈 2건 상세', 'MID', '8/4 회의에서 언급한 잔여 이슈, 상세 내용입니다.\n\n1. 피크 시간대 지연\n오전 9~10시 트래픽 급증 시 파이프라인 처리가 간헐적으로 지연됩니다. 재현은 되는데 매번은 아니라서 원인 특정이 좀 걸렸습니다. 결국 해당 시간대 리소스 자동 스케일링으로 대응하기로 했습니다.\n\n2. 해외 카드 거래 피처 지연\n환율 정보가 얽혀 있는 거래 유형에서 피처 계산이 늦게 반영되는 케이스입니다. 환율 정보 캐싱 방식을 개선해서 해결했습니다.\n\n두 건 모두 해결 완료 확인했습니다.', '2026-08-05 09:00:00', '2026-08-05 09:00:00', NULL),
(52, 7, (SELECT id FROM users WHERE employee_no='DT22-0103'), '모델 확정 공지 — 그래디언트 부스팅 최종 채택', 'HIGH', '모델 선정 회의 결과 공식 공지드립니다.\n\n1. 최종 모델\n그래디언트 부스팅 기반 모델을 v3 최종 모델로 확정했습니다.\n\n2. 성능\n정밀 튜닝 결과 오탐률 18% 개선(v2 대비). 애초 목표(절반 이하)에는 못 미치지만, 유의미한 개선입니다.\n\n3. 향후 방향\n남은 개선은 운영 데이터가 쌓이면서 점진적으로 진행하는 걸로 방향을 잡았습니다. 완벽을 기다리기보다 지금 성과로 다음 단계(백엔드 연동)로 넘어갑니다.\n\n연동 설계는 배민아 선임이 착수합니다.', '2026-05-02 09:00:00', '2026-05-02 09:00:00', NULL),
(53, 7, (SELECT id FROM users WHERE employee_no='DT22-0023'), '프로젝트 중간 점검 — 4개월 진행 종합', 'MID', '3월 킥오프부터 지금까지 진행 상황을 종합 정리했습니다.\n\n1. 모델: 확정 완료 (그래디언트 부스팅, 오탐률 18% 개선)\n2. 백엔드 연동: 서빙 최적화 완료(92ms 달성)\n3. 파이프라인: 안정화 진행 중(현재 80%)\n4. 사업성: 6/12 검토 완료, 리스크 관리 가치 인정받아 지속 결정\n\n최종 오탐률 검증(목표 4% 이하)만 남았습니다. 8월 정기 점검에서 최종 확정하겠습니다.', '2026-07-10 09:00:00', '2026-07-10 09:00:00', NULL),
(54, 7, (SELECT id FROM users WHERE employee_no='DT22-0082'), '손익 시나리오 산정 방법론 참고 자료', 'LOW', '6/12 사업성 검토 회의 이후, 손익 시나리오 산정 방식에 참고할 자료를 정리했습니다.\n\n1. 왜 필요했나\nFDS처럼 직접 매출이 없는 리스크 관리형 사업은 손익 산정이 까다롭습니다. "방지된 손실"을 어떻게 정량화할지가 핵심입니다.\n\n2. 참고한 방법론\n이상 거래 탐지율 개선폭 × 평균 피해 금액 × 발생 빈도로 방지 손실을 추산하는 방식을 참고했습니다.\n\n3. 적용\n이 방식으로 재산정하면, 오탐률 18% 개선이 실제로 어느 정도 손실 방지 효과가 있는지 좀 더 구체적으로 보여줄 수 있을 것 같습니다. 다음 손익 보고 때 반영해보겠습니다.', '2026-06-18 09:00:00', '2026-06-18 09:00:00', NULL),
(55, 7, (SELECT id FROM users WHERE employee_no='DT22-0109'), '데이터 파이프라인 안정화 진행 가이드', 'LOW', '파이프라인 안정화 작업 진행 방식을 공유드립니다. 비슷한 작업 하실 때 참고하시면 좋을 것 같습니다.\n\n1. 순서\n먼저 모델 서빙과의 연동 구간을 점검하고, 그다음 데이터 소스별 안정성을 확인하는 순서로 진행하고 있습니다.\n\n2. 모니터링\n각 구간별로 지연 시간을 실시간으로 볼 수 있게 대시보드를 만들어뒀습니다. 문제 생기면 어느 구간인지 바로 확인 가능합니다.\n\n대시보드 링크는 댓글에 남겨두겠습니다.', '2026-07-15 09:00:00', '2026-07-15 09:00:00', NULL),
(56, 7, (SELECT id FROM users WHERE employee_no='DT24-0040'), '모델 튜닝 과정 회고', 'MID', '튜닝 작업 마치고 돌아보는 글입니다.\n\n1. 시행착오\n처음엔 하이퍼파라미터를 무작위로 여러 조합 시도했는데 시간만 오래 걸리고 개선폭이 크지 않았습니다. 피처 엔지니어링 쪽을 먼저 손보고 나서야 눈에 띄는 개선(12%→18%)이 나왔습니다.\n\n2. 배운 점\n하이퍼파라미터 튜닝보다 피처 자체의 품질이 성능에 더 큰 영향을 준다는 걸 다시 확인했습니다. 다음에는 피처 엔지니어링을 먼저 충분히 하고 튜닝에 들어가는 순서로 하려고 합니다.\n\n추가 개선 여지는 있지만, 지금 수준(18%)으로도 의미 있는 결과라고 생각합니다.', '2026-05-05 09:00:00', '2026-05-05 09:00:00', NULL),
(57, 8, (SELECT id FROM users WHERE employee_no='DT22-0039'), '작년 지적사항 3건 재발 여부 사전 점검', 'MID', '킥오프에서 언급한 작년 권고사항 3건, 재발 여부를 미리 확인해봤습니다.\n\n1. 접근권한 관리 로그 보관 기간 미흡\n현재 보관 기간을 확인한 결과, 기준(1년)은 충족하고 있습니다. 재발 없음.\n\n2. 일부 서버 패치 주기 초과\n전수 점검 예정이라 아직 확정은 아니지만, 샘플 점검에서는 이상 없었습니다.\n\n3. 비상연락망 최신화 누락\n최근 조직 개편 반영이 안 된 부분이 있어서, 이건 확실히 다시 업데이트가 필요합니다.\n\n본 점검 때 3건 다 다시 확인하겠습니다.', '2026-07-06 09:00:00', '2026-07-06 09:00:00', NULL),
(58, 8, (SELECT id FROM users WHERE employee_no='DT22-0039'), '기술 취약점 점검 항목 체크리스트', 'LOW', '점검 진행에 앞서 확인할 항목 리스트를 정리했습니다.\n\n1. 접근 관리\n- 퇴사자·부서이동자 권한 회수 여부\n- 관리자 계정 사용 이력\n\n2. 시스템 관리\n- 서버 OS 패치 현황\n- 방화벽 정책 최신화 여부\n\n3. 로그 관리\n- 보관 기간 준수 여부\n- 실제 설정값과 정책 문서 일치 여부\n\n체크리스트대로 순서대로 점검 진행하겠습니다.', '2026-07-08 09:00:00', '2026-07-08 09:00:00', NULL),
(59, 8, (SELECT id FROM users WHERE employee_no='DT22-0039'), '발견 항목 4건 조치 진행 상황', 'MID', '7/24 회의에서 보고드린 발견 항목 4건, 조치 진행 상황입니다.\n\n1. 개발 서버 OS 패치 지연 (2개월)\n패치 적용 완료. 재점검에서 이상 없음 확인.\n\n2. 퇴사자 계정 3건 미회수\n전량 회수 완료. 접근 이력이 없었던 걸 재확인해서 별도 보안 사고 여지는 없었습니다.\n\n3. 로그 보관 정책 불일치\n실제 설정값을 문서 기준에 맞춰 정정 완료.\n\n4. 방화벽 미사용 룰 5건\n확인 결과 3건은 실제 미사용으로 삭제, 2건은 특정 배치 작업에서 쓰고 있어서 유지하기로 했습니다.\n\n8/14까지 전량 완료 목표 순조롭게 진행 중입니다.', '2026-07-25 09:00:00', '2026-07-25 09:00:00', NULL),
(60, 8, (SELECT id FROM users WHERE employee_no='DT22-0024'), '부서별 자료 제출 기한 공지', 'MID', '각 부서 접근권한 현황 자료 제출 관련 재공지드립니다.\n\n1. 제출 기한\n7/17까지입니다.\n\n2. 제출 항목\n부서별 시스템 접근권한 보유자 명단, 권한 부여 사유, 최근 변경 이력.\n\n3. 안내\n작년 심사 때 이 자료 취합이 늦어져서 전체 일정에 영향을 준 적이 있습니다. 이번엔 기한 꼭 지켜주시면 감사하겠습니다.\n\n문의사항은 임재현 선임에게 연락 부탁드립니다.', '2026-07-04 09:00:00', '2026-07-04 09:00:00', NULL),
(61, 8, (SELECT id FROM users WHERE employee_no='DT22-0024'), 'ISMS-P 갱신 준비 중간 점검', 'MID', '7월 킥오프 이후 진행 상황 정리입니다.\n\n1. 사전 재발 점검: 완료 (2건 재발 없음, 1건 갱신 필요 확인)\n2. 기술 취약점 점검: 완료, 경미한 항목 4건 발견\n3. 조치: 4건 전량 조치 완료\n4. 감사 대응 자료: 작성 중\n\n전반적으로 큰 이슈 없이 순조롭습니다. 다음 단계는 감사 대응 자료 완성입니다.', '2026-08-01 09:00:00', '2026-08-01 09:00:00', NULL),
(62, 8, (SELECT id FROM users WHERE employee_no='DT22-0041'), 'ISMS-P 심사 기준 변경사항 확인', 'LOW', '이번 심사부터 바뀐 부분이 있는지 확인해봤습니다.\n\n1. 확인 결과\n큰 틀에서 심사 기준 변화는 없으나, 클라우드 환경 관련 점검 항목이 세부적으로 조금 더 늘었습니다.\n\n2. 저희 영향\n저희는 클라우드 사용 비중이 크지 않아 영향은 제한적일 것으로 보이나, 감사 대응 자료에 관련 항목을 미리 포함해두는 게 안전할 것 같습니다.', '2026-08-08 09:00:00', '2026-08-08 09:00:00', NULL),
(63, 8, (SELECT id FROM users WHERE employee_no='DT22-0029'), '부서별 협조 요청 시 안내 절차', 'LOW', '자료 요청하러 각 부서 다니면서 정리해둔 절차입니다. 다음에 비슷한 요청 하실 때 참고하세요.\n\n1. 사전 공지\n요청 전에 부서장님께 먼저 목적을 간단히 설명드리면 자료 취합이 훨씬 빨라집니다.\n\n2. 양식 제공\n빈 양식을 먼저 드리고 채워달라고 하면, 형식이 안 맞아 다시 받는 일이 줄어듭니다.', '2026-07-10 09:00:00', '2026-07-10 09:00:00', NULL),
(64, 8, (SELECT id FROM users WHERE employee_no='DT22-0041'), '감사 대응 자료 작성 회고', 'MID', '자료 작성 마무리하면서 느낀 점입니다.\n\n1. 작년과 달라진 점\n작년엔 자료 취합이 늦어서 급하게 작성했는데, 이번엔 부서별 기한을 명확히 공지한 덕분에 여유 있게 작성할 수 있었습니다.\n\n2. 남은 일\n발견 항목 4건에 대한 조치 계획을 자료에 포함해서 마무리하겠습니다. 심사 전까지는 여유가 있어서 큰 걱정은 없습니다.', '2026-08-13 09:00:00', '2026-08-13 09:00:00', NULL),
(65, 9, (SELECT id FROM users WHERE employee_no='DT22-0065'), '회선사업자 3곳 비교 상세 결과', 'MID', '3/23 회의에서 보고드린 B사 선정, 비교 과정 상세 공유드립니다.\n\n1. 비교 기준\n경로 분리 여부, SLA, 비용 세 가지로 봤습니다.\n\n2. A사(기존)\n이미 쓰고 있는 사업자, 경로 분리 대상에서 제외.\n\n3. B사\n물리적으로 완전히 분리된 경로 확인. SLA 99.95%, 비용은 중간 수준.\n\n4. C사\n경로는 분리돼 있으나 SLA가 99.9%로 B사보다 낮고, 비용은 오히려 더 높았습니다.\n\n5. 결론\nB사가 세 기준 모두에서 무난하게 우위라 최종 선정했습니다. 계약 협의 착수하겠습니다.', '2026-03-24 09:00:00', '2026-03-24 09:00:00', NULL),
(66, 9, (SELECT id FROM users WHERE employee_no='DT22-0065'), '라우팅 이중화 설계 상세', 'MID', '네트워크 이중화 설계 세부 내용 공유드립니다.\n\n1. 구조\nA사(기존)-B사(신규) 두 경로를 BGP로 이중화합니다. 한쪽 장애 시 자동으로 다른 쪽으로 전환됩니다.\n\n2. 전환 시간 목표\n장애 발생부터 전환 완료까지 5초 이내를 목표로 잡았습니다.\n\n3. 검증 계획\n실제 시공 후 한쪽 회선을 의도적으로 끊어보는 방식으로 전환 시간을 측정할 예정입니다.\n\n설계 문서는 첨부파일로 공유드립니다.', '2026-05-05 09:00:00', '2026-05-05 09:00:00', NULL),
(67, 9, (SELECT id FROM users WHERE employee_no='DT22-0061'), '자산 목록 불일치 사례 — 실물 확인 중 발견한 것들', 'MID', '자산 목록 갱신 작업 중 발견한 불일치 사례를 공유드립니다.\n\n1. 사례 1\n대장에는 A모델 스위치로 등록돼 있는데, 실제로는 B모델이 꽂혀 있었습니다. 과거 교체 작업 시 대장 갱신이 누락된 것으로 보입니다.\n\n2. 사례 2\n대장에 없는 장비가 랙에 꽂혀 있는 경우도 있었습니다. 임시로 설치했다가 그대로 방치된 것 같습니다.\n\n3. 현재까지 발견\n총 18건의 불일치를 발견해서 정정 중입니다.\n\n실물 확인 계속 진행하면서 추가 발견 사항 업데이트하겠습니다.', '2026-03-25 09:00:00', '2026-03-25 09:00:00', NULL),
(68, 9, (SELECT id FROM users WHERE employee_no='DT22-0022'), '시공 업체 최종 확정 공지', 'HIGH', '현장 실사 결과를 반영해 시공 업체를 최종 확정했습니다.\n\n1. 선정 업체\n데이터센터 시공 경력이 있고 무중단 작업 경험이 풍부한 업체로 확정했습니다.\n\n2. 선정 이유\n견적만 보면 더 저렴한 곳도 있었지만, 이번 작업은 무중단으로 진행해야 하는 만큼 경험이 검증된 업체를 우선했습니다.\n\n3. 다음 단계\n시공 전 현장 점검 체크리스트를 하도경 사원이 준비 중입니다. 완료되는 대로 최종 리허설 진행하겠습니다.', '2026-06-19 09:00:00', '2026-06-19 09:00:00', NULL),
(69, 9, (SELECT id FROM users WHERE employee_no='DT22-0022'), '프로젝트 진행 상황 종합 정리', 'MID', '2월 킥오프 이후 진행 상황을 정리합니다.\n\n1. 네트워크 이중화 설계: 완료, B사 계약 체결\n2. 시공 업체: 확정\n3. 자산 목록 갱신: 완료(불일치 18건 정정)\n4. 시공: 8월 첫 주 착수 예정\n\n전체적으로 계획대로 진행되고 있습니다. 전원 이중화는 네트워크 이중화 완료 후 착수 예정입니다.', '2026-07-21 09:00:00', '2026-07-21 09:00:00', NULL),
(70, 9, (SELECT id FROM users WHERE employee_no='DT22-0058'), '타사 데이터센터 이중화 사례 조사', 'LOW', '다른 금융 IT 자회사들의 DC 이중화 사례를 공개 자료 기준으로 찾아봤습니다.\n\n1. 공통점\n대부분 서버 → 네트워크 → 전원 순으로 단계적으로 진행하는 패턴이었습니다. 저희와 비슷한 순서입니다.\n\n2. 참고할 점\n일부 사례에서는 네트워크 이중화 시 기존 회선사업자와의 계약 조건 때문에 신규 사업자 확보에 시간이 오래 걸렸다는 언급이 있었습니다. 저희도 B사 계약 협의 시 참고하면 좋을 것 같습니다.', '2026-04-10 09:00:00', '2026-04-10 09:00:00', NULL),
(71, 9, (SELECT id FROM users WHERE employee_no='DT22-0064'), '시공 전 현장 점검 체크리스트 상세', 'MID', '시공 전 준비 사항을 체크리스트로 정리했습니다.\n\n1. 작업 구간\n전원 차단 없이 진행해야 하는 구간을 사전에 명확히 표시해뒀습니다.\n\n2. 접근 통제\n시공 인력의 데이터센터 출입 절차, 신원 확인 절차를 정리했습니다.\n\n3. 비상 연락 체계\n작업 중 문제 발생 시 연락할 담당자 목록과 연락처를 준비했습니다.\n\n4. 리허설\n실제 시공 전 시공 업체와 리허설을 진행해서 절차를 한 번 맞춰볼 예정입니다.\n\n체크리스트 전문은 공유 문서함에 올려뒀습니다.', '2026-06-25 09:00:00', '2026-06-25 09:00:00', NULL),
(72, 9, (SELECT id FROM users WHERE employee_no='DT22-0065'), '네트워크 이중화 1일차 작업 회고', 'MID', '시공 1일차 작업을 마치고 돌아보는 글입니다.\n\n1. 진행 상황\nB사 신규 회선 포설 작업은 예정대로 완료됐습니다. 무중단 진행 원칙을 지키면서도 큰 이슈 없이 마쳤습니다.\n\n2. 사전 준비의 효과\n체크리스트와 리허설을 미리 해둔 덕분에 실제 작업이 매끄럽게 진행됐습니다. 특히 접근 통제 절차를 미리 정리해둔 게 현장에서 시간을 많이 아껴줬습니다.\n\n3. 다음 단계\n라우팅 이중화 설정이 다음 주부터 순차 진행됩니다. 이상 징후 있으면 바로 공유드리겠습니다.', '2026-08-05 09:00:00', '2026-08-05 09:00:00', NULL),
(73, 10, (SELECT id FROM users WHERE employee_no='DT22-0065'), '서버 이중화 설계 상세 — 액티브-액티브 구성', 'MID', '서버 이중화 설계안 세부 내용 공유드립니다.\n\n1. 대상\n핵심 API 서버군과 인증 서버를 액티브-액티브 구성으로 전환합니다.\n\n2. 트래픽 분산\n두 서버가 동시에 요청을 받아 처리하는 구조라, 한쪽이 죽어도 서비스 중단 없이 나머지가 받습니다.\n\n3. 스토리지는 별도 검토\n서버와 달리 지금 쓰는 스토리지 장비가 이중화를 기본 지원하는 모델이 아니라서, 방식 자체를 다시 봐야 합니다. 이 부분은 지동원 파트장이 조사 중입니다.\n\n설계 문서는 첨부로 공유드립니다.', '2024-03-18 09:00:00', '2024-03-18 09:00:00', NULL),
(74, 10, (SELECT id FROM users WHERE employee_no='DT22-0058'), '스토리지 이중화 방식 검토 — 액티브-스탠바이 결정 배경', 'HIGH', '4/15 회의 전에 미리 검토 내용을 공유드립니다.\n\n1. 검토한 방식\n- 액티브-액티브: 현재 장비로 지원 불가\n- 액티브-스탠바이: 지원 가능, 전환 시간 발생\n\n2. 왜 액티브-스탠바이인가\n완전한 무중단은 아니지만, 장애 시 전환 시간을 수 분 이내로 줄일 수 있습니다. 지금 상태(전환 자체가 안 되는 상태)보다는 훨씬 나은 수준입니다.\n\n3. 예상 전환 시간\n수 분 이내를 목표로 하고 있으나, 실제 테스트는 시공 완료 후 진행 예정입니다.\n\n다음 회의에서 이 방향으로 최종 확정 제안드리겠습니다.', '2024-04-08 09:00:00', '2024-04-08 09:00:00', NULL),
(75, 10, (SELECT id FROM users WHERE employee_no='DT22-0058'), '예산안 준비 관련 진행 상황', 'MID', '서버·스토리지 설계가 확정돼서 예산안 준비 중입니다.\n\n1. 예산 항목\n서버 이중화 장비, 스토리지 이중화 장비, 시공 비용으로 구성했습니다.\n\n2. 진행 상황\n진병호 팀장님이 하수민 본부장님께 직접 보고하기로 하셨습니다.\n\n3. 일정 영향\n예산 승인이 확정돼야 시공 착수가 가능해서, 승인 시점에 따라 전체 일정이 좌우됩니다. 승인되는 대로 바로 공유드리겠습니다.', '2024-04-18 09:00:00', '2024-04-18 09:00:00', NULL),
(76, 10, (SELECT id FROM users WHERE employee_no='DT22-0022'), 'SPOF 제거 우선순위 결정 공지', 'HIGH', '킥오프에서 논의된 우선순위를 공식 공지드립니다.\n\n1. 우선순위\n1순위 핵심 API 서버군, 2순위 인증 서버, 3순위 스토리지.\n\n2. 결정 기준\n장애 시 전사 서비스 영향 범위와 발생 가능성을 기준으로 판단했습니다.\n\n3. 배경\n지금 구조는 핵심 서버 하나만 죽어도 서비스 전체가 멈출 수 있는 상태입니다. 이 우선순위대로 순차적으로 없애나가겠습니다.', '2024-02-06 09:00:00', '2024-02-06 09:00:00', NULL),
(77, 10, (SELECT id FROM users WHERE employee_no='DT22-0022'), '1단계 프로젝트 중간 점검', 'MID', '2월 킥오프 이후 진행 상황 정리입니다.\n\n1. 설계: 완료 (서버 액티브-액티브, 스토리지 액티브-스탠바이)\n2. 예산: 승인 완료\n3. 시공: 착수, 초기 진행 순조로움\n\n서버 이중화가 먼저 진행 중이며, 완료되는 대로 스토리지로 넘어갈 예정입니다.', '2024-06-10 09:00:00', '2024-06-10 09:00:00', NULL),
(78, 10, (SELECT id FROM users WHERE employee_no='DT22-0065'), '액티브-스탠바이 구성 사례 조사', 'LOW', '스토리지 이중화 방식 검토에 참고할 사례를 찾아봤습니다.\n\n1. 참고 사례\n비슷한 규모의 다른 회사들도 스토리지 이중화 초기 단계에서는 액티브-스탠바이 방식을 많이 씁니다. 완전한 무중단(액티브-액티브)은 장비 투자 규모가 훨씬 커서, 단계적으로 접근하는 경우가 일반적이었습니다.\n\n2. 시사점\n저희가 검토 중인 방향이 업계에서도 일반적인 접근이라는 걸 확인했습니다. 참고 자료는 지동원 파트장님께 전달했습니다.', '2024-03-05 09:00:00', '2024-03-05 09:00:00', NULL),
(79, 10, (SELECT id FROM users WHERE employee_no='DT22-0058'), '시공 진행 방식 안내', 'LOW', '서버 이중화 시공이 어떻게 진행되고 있는지 안내드립니다.\n\n1. 진행 방식\n무중단으로 진행해야 해서, 서버를 하나씩 순차적으로 전환하는 방식입니다. 한 대 전환하고 안정성 확인 후 다음 대로 넘어갑니다.\n\n2. 확인 사항\n각 전환 시점마다 트래픽이 제대로 분산되는지 모니터링하고 있습니다.\n\n진행 상황은 격주로 계속 공유드리겠습니다.', '2024-06-05 09:00:00', '2024-06-05 09:00:00', NULL),
(80, 10, (SELECT id FROM users WHERE employee_no='DT22-0022'), '1단계 프로젝트 완료 회고', 'MID', '무중단 전환 테스트까지 마치고 프로젝트를 마무리하며 돌아보는 글입니다.\n\n1. 결과\n서버는 완전 무중단 전환 확인, 스토리지는 평균 전환 시간 40초로 목표(수 분 이내)를 크게 상회하는 결과를 냈습니다.\n\n2. 잘된 점\n우선순위를 명확히 정하고 순차적으로 진행한 게 일정 관리에 도움이 됐습니다. 서버부터 확실히 끝내고 스토리지로 넘어간 순서가 맞았다고 봅니다.\n\n3. 남은 과제\n회선·전원 이중화는 이번 범위에 없었는데, 이건 규모가 더 커서 별도 프로젝트(2단계)로 진행하는 게 맞다고 판단했습니다.', '2024-09-26 09:00:00', '2024-09-26 09:00:00', NULL),
(81, 11, (SELECT id FROM users WHERE employee_no='DT22-0185'), '토큰 발급 로직 설계 상세', 'MID', '3/27 회의에서 논의된 JWT 발급 로직, 세부 설계 공유드립니다.\n\n1. 토큰 구조\n액세스 토큰(짧은 만료)과 리프레시 토큰(긴 만료) 이중 구조로 갑니다.\n\n2. 서명 방식\n서버 간 상태 공유 없이 검증 가능하도록 비대칭키 서명(RS256)을 씁니다.\n\n3. 만료 시간\n액세스 토큰 30분, 리프레시 토큰 2주로 설계했습니다. 세 서비스가 동일 정책을 쓰게 되는 겁니다.\n\n설계 문서는 첨부로 공유드립니다.', '2024-03-30 09:00:00', '2024-03-30 09:00:00', NULL),
(82, 11, (SELECT id FROM users WHERE employee_no='DT22-0184'), '서비스별 권한 범위(스코프) 초안 상세', 'MID', '권한 범위 설계 초안 자세히 공유드립니다.\n\n1. 스코프 구성\n은행·증권·페이 각 서비스별로 접근 가능한 API 범위를 정의했습니다.\n\n2. 초안의 문제점\n검토하다 보니, 은행 서비스 토큰에 증권·페이 API 접근 권한까지 광범위하게 포함돼 있다는 걸 발견했습니다. 사용성을 위해 넓게 잡은 건데, 보안 관점에서는 문제가 될 수 있어 보입니다.\n\n3. 다음 단계\n정보보안팀 검토를 받아보려고 합니다. 검토 결과에 따라 스코프를 다시 좁혀야 할 수도 있습니다.', '2024-04-24 09:00:00', '2024-04-24 09:00:00', NULL),
(83, 11, (SELECT id FROM users WHERE employee_no='DT22-0184'), '정보보안팀과의 이견 상세 — 최소 권한 원칙 vs 사용성', 'HIGH', '6/18 회의에서 논의된 이견을 좀 더 자세히 정리했습니다.\n\n1. 정보보안팀 입장\n토큰 하나에 모든 권한을 담기보다, 서비스 전환 시점마다 필요한 권한만 재발급하는 방식을 제안했습니다. 최소 권한 원칙에 충실한 방식입니다.\n\n2. 저희 입장\n완전히 그 방식대로 가면 사용자가 서비스를 넘어갈 때마다 재발급 과정에서 지연이 생길 수 있습니다.\n\n3. 절충 방향 검토\n최소 권한 원칙은 지키되, 짧은 TTL의 권한 캐싱을 둬서 지연을 최소화하는 방안을 검토 중입니다. 보안팀과 다음 주 재협의 예정입니다.', '2024-06-20 09:00:00', '2024-06-20 09:00:00', NULL),
(84, 11, (SELECT id FROM users WHERE employee_no='DT22-0183'), '절충안 확정 공지 — 최소 권한 + 짧은 캐싱', 'HIGH', '정보보안팀과 합의한 절충안을 공식 공지드립니다.\n\n1. 확정 내용\n최소 권한 원칙을 따르되, TTL 30초의 권한 캐싱을 적용합니다.\n\n2. 왜 30초인가\n보안팀이 요구한 짧은 TTL 조건을 충족하면서도, 사용자가 서비스 전환 시 체감하는 지연은 거의 없는 수준입니다.\n\n3. 개발 재개\n이 절충안으로 개발을 재개합니다. 잔여 개발 항목(권한 재발급 로직 등)은 임도현 선임이 8월 초까지 마무리할 예정입니다.', '2024-07-17 09:00:00', '2024-07-17 09:00:00', NULL),
(85, 11, (SELECT id FROM users WHERE employee_no='DT22-0183'), '프로젝트 중간 점검', 'MID', '3월 킥오프 이후 진행 상황 정리입니다.\n\n1. 토큰 발급 로직: 설계 완료\n2. 로그인 통합 화면: 개발 중\n3. 권한 스코프: 정보보안팀 검토 대기 중(개발은 화면 위주로 병행 진행)\n\n권한 스코프 검토 결과에 따라 일정에 변화가 있을 수 있어, 확정되는 대로 다시 공유드리겠습니다.', '2024-05-15 09:00:00', '2024-05-15 09:00:00', NULL),
(86, 11, (SELECT id FROM users WHERE employee_no='DT22-0187'), 'JWT vs 세션 방식 비교 자료', 'LOW', '토큰 방식 결정에 참고했던 비교 자료를 공유드립니다.\n\n1. 세션 방식\n서버가 상태를 들고 있어야 해서, 세 서비스가 서로 다른 서버군에서 돌 때 세션 공유가 번거롭습니다.\n\n2. JWT 방식\n서버 간 상태 공유 없이 토큰 자체로 검증 가능합니다. 다만 토큰 탈취 시 만료 전까지 무효화가 어렵다는 단점이 있습니다.\n\n3. 결론\n저희 구조(여러 서비스, 분산된 서버군)에는 JWT가 더 적합하다고 판단해서 이 방식으로 결정했습니다.', '2024-04-02 09:00:00', '2024-04-02 09:00:00', NULL),
(87, 11, (SELECT id FROM users WHERE employee_no='DT22-0186'), '로그인 통합 화면 개발 진행 가이드', 'LOW', '화면 개발 진행 중인 내용 공유드립니다.\n\n1. 화면 구성\n세 서비스 로고를 함께 보여주면서 하나의 로그인 폼으로 처리하는 형태로 만들고 있습니다.\n\n2. 고려 사항\n어느 서비스에서 진입했는지에 따라 로그인 후 리다이렉트 경로가 달라져야 해서, 이 부분을 신경 써서 개발 중입니다.\n\n진행률은 계속 공유드리겠습니다.', '2024-05-20 09:00:00', '2024-05-20 09:00:00', NULL),
(88, 11, (SELECT id FROM users WHERE employee_no='DT22-0184'), '프로젝트 마무리 회고', 'MID', '오픈 완료 후 돌아보는 글입니다.\n\n1. 가장 어려웠던 부분\n권한 범위를 둘러싼 정보보안팀과의 이견 조율에 시간이 꽤 걸렸습니다. 사용성과 보안이 충돌하는 지점이었는데, 결과적으로는 둘 다 챙긴 절충안이 나와서 다행이었습니다.\n\n2. 배운 점\n보안 관련 이견은 한쪽이 이기고 지는 문제가 아니라, 기술적으로 절충 가능한 지점을 찾는 게 중요하다는 걸 다시 느꼈습니다.\n\n3. 운영 현황\n오픈 후 초기 오류 모니터링 결과 특이 이슈 없습니다. 1개월 안정화 모니터링 계속 진행 중입니다.', '2024-08-31 09:00:00', '2024-08-31 09:00:00', NULL),
(89, 12, (SELECT id FROM users WHERE employee_no='DT22-0095'), '여신관리 프로세스 4단계 분석 상세', 'MID', '9/27 회의에서 말씀드린 프로세스 분석, 단계별 상세 내용 공유드립니다.\n\n1. 접수 단계\n서류 접수부터 초기 심사 배정까지. 실무진 인터뷰 결과 종이 서류와 시스템 입력을 병행하는 부분에서 시간이 많이 걸린다는 지적이 있었습니다.\n\n2. 심사 단계\n담보 평가, 소득 검증 등 심사 로직이 핵심입니다.\n\n3. 실행 단계\n승인 이후 실제 대출 실행까지의 절차.\n\n4. 사후관리 단계\n연체 관리, 만기 관리 등.\n\n각 단계별 소요 시간과 병목 구간을 계속 조사 중입니다.', '2024-10-04 09:00:00', '2024-10-04 09:00:00', NULL),
(90, 12, (SELECT id FROM users WHERE employee_no='DT24-0055'), '화면 요구사항 정의서 — UX 개선 사항 상세', 'MID', '10/18 회의에서 언급한 UX 개선 사항, 자세히 정리했습니다.\n\n1. 여신 이력 한 화면 조회\n기존에는 여신 이력을 보려면 여러 화면을 오가야 했는데, 한 화면에서 조회 가능하도록 개선했습니다.\n\n2. 실무진 인터뷰 반영\n인터뷰에서 나온 요청사항(승인 이력, 담보 변경 이력 등)을 화면 요구사항에 반영했습니다.\n\n3. 화면 수\n기존 대비 절반 가까이 줄여서 32개로 확정했습니다. 중복 기능과 안 쓰는 화면을 정리한 결과입니다.\n\n화면 요구사항 정의서 전문은 공유 문서함에 있습니다.', '2024-10-25 09:00:00', '2024-10-25 09:00:00', NULL),
(91, 12, (SELECT id FROM users WHERE employee_no='DT23-0027'), '데이터 정합성 오류 340건 — 유형별 상세', 'HIGH', '1/17 회의에서 보고드린 정합성 오류, 유형별로 정리했습니다.\n\n1. 유형 1 — 실행일자 누락 (280건)\n여신 실행일자가 없는데 완료 상태로 표시된 건들입니다. 예전에 수기로 처리하고 시스템 입력을 누락한 것으로 보입니다.\n\n2. 유형 2 — 금액 불일치 (40건)\n승인 금액과 실행 금액이 다른데 사유가 기록 안 된 건들입니다.\n\n3. 유형 3 — 담보 정보 누락 (20건)\n담보 대출인데 담보 정보 필드가 비어있는 건들입니다.\n\n4. 대응 방향\n유형별로 고객사 실무진과 확인해서 정정하는 절차를 진행 중입니다.', '2025-01-20 09:00:00', '2025-01-20 09:00:00', NULL),
(92, 12, (SELECT id FROM users WHERE employee_no='DT22-0016'), '착수 후 계약 범위 재확인 공지', 'MID', '킥오프 이후 계약 범위를 다시 한번 명확히 공지드립니다.\n\n1. 범위\n여신 접수부터 사후관리까지 전체 프로세스 시스템 전환 + 레거시 데이터 이관.\n\n2. 데이터 이관이 핵심 리스크\n레거시가 15년 넘은 시스템이라, 데이터 이관이 이번 프로젝트에서 가장 리스크가 큰 부분입니다. 화면·프로세스는 저희가 많이 해본 영역이지만, 데이터 쪽은 처음부터 신경 써서 봐야 합니다.\n\n3. 역할\n권도영 - 프로세스 분석. 홍재현 - 데이터 이관. 여도경 - 화면 요구사항.', '2024-09-10 09:00:00', '2024-09-10 09:00:00', NULL),
(93, 12, (SELECT id FROM users WHERE employee_no='DT22-0016'), '프로젝트 중간 점검', 'MID', '9월 착수 이후 진행 상황 정리입니다.\n\n1. 프로세스 분석: 완료\n2. 데이터 이관 계획: 초안 완료(87개 테이블 중 61개가 실제 이관 대상)\n3. 화면 개발: 60% 진행\n\n고객사 반응은 양호합니다. 다만 세부 필드 요청이 조금씩 늘고 있어 범위 관리는 계속 신경 써야 합니다.', '2024-11-15 09:00:00', '2024-11-15 09:00:00', NULL),
(94, 12, (SELECT id FROM users WHERE employee_no='DT22-0095'), '레거시 시스템 데이터 이관 유사 사례 조사', 'LOW', '레거시 데이터 이관 관련해서 참고할 만한 사례를 찾아봤습니다.\n\n1. 공통 이슈\n오래된 시스템일수록 수기 처리 이력이 시스템에 반영 안 된 케이스가 많다는 게 공통적으로 언급됐습니다.\n\n2. 시사점\n저희 프로젝트에서도 비슷한 패턴이 나올 가능성이 있어, 데이터 실사 단계에서 특히 오래된 데이터를 꼼꼼히 봐야 할 것 같습니다. 실제로 나중에 340건의 정합성 오류가 나온 걸 보면 이 우려가 맞았습니다.', '2024-10-10 09:00:00', '2024-10-10 09:00:00', NULL),
(95, 12, (SELECT id FROM users WHERE employee_no='DT23-0027'), '데이터 실사 진행 방법론', 'MID', '데이터 실사를 어떻게 진행하고 있는지 방법을 공유드립니다.\n\n1. 1단계 — 테이블 생존 여부 확인\n87개 테이블 중 실제로 데이터가 갱신되고 있는지부터 확인합니다.\n\n2. 2단계 — 샘플 데이터 검증\n생존 테이블 중 샘플을 뽑아 데이터 정합성을 확인합니다.\n\n3. 3단계 — 전수 검증\n샘플에서 이슈가 발견된 테이블은 전수로 검증 범위를 넓힙니다.\n\n이 방식으로 진행 중이며, 발견 사항은 계속 업데이트하겠습니다.', '2024-09-20 09:00:00', '2024-09-20 09:00:00', NULL),
(96, 12, (SELECT id FROM users WHERE employee_no='DT22-0016'), '프로젝트 마무리 회고', 'MID', '시스템 오픈 완료 후 돌아보는 글입니다.\n\n1. 가장 큰 리스크였던 부분\n데이터 정합성 문제(340건)를 이관 전에 발견하고 정리한 게 이번 프로젝트의 핵심이었다고 봅니다. 만약 이관 후에 발견했다면 훨씬 큰 문제가 됐을 겁니다.\n\n2. 고객사 피드백\n고객사 쪽에서 특히 이 부분에 대해 감사하다는 얘기를 많이 하셨습니다.\n\n3. 다음 유사 프로젝트에 참고할 점\n레거시 데이터 이관이 포함된 프로젝트는 데이터 실사를 프로세스 분석과 병행해서 최대한 일찍 시작하는 게 좋겠습니다. 저희는 요구사항 분석 완료 후에 시작해서, 결과적으로는 잘 마무리됐지만 좀 더 여유를 두고 갔으면 더 좋았을 것 같습니다.', '2025-03-21 09:00:00', '2025-03-21 09:00:00', NULL),
(97, 13, (SELECT id FROM users WHERE employee_no='DT22-0145'), '핵심 컴포넌트 10종 상세 스펙', 'MID', '11/27 회의에서 보여드린 컴포넌트 목록, 각각 상세 스펙 정리했습니다.\n\n1. 버튼\n크기 3종(대/중/소), 상태 4종(기본/호버/비활성/로딩)으로 구성.\n\n2. 입력폼\n텍스트, 숫자, 날짜 등 타입별 공통 검증 로직 포함.\n\n3. 테이블\n정렬, 페이지네이션 기본 내장.\n\n4. 차트\nMTS 특성상 가장 많이 쓰이는 컴포넌트라 옵션을 가장 유연하게 설계 중입니다. 여기가 제일 손이 많이 갑니다.\n\n나머지 6종(모달, 탭, 토스트 등)은 다음 주까지 스펙 확정하겠습니다.', '2024-12-01 09:00:00', '2024-12-01 09:00:00', NULL),
(98, 13, (SELECT id FROM users WHERE employee_no='DT22-0145'), '차트 컴포넌트 설계 상세 — 왜 시간이 오래 걸리나', 'MID', '차트 컴포넌트가 왜 오래 걸리는지 설명드립니다.\n\n1. 사용처 다양성\n주문 화면, 시세 화면, 잔고 화면 등 여러 곳에서 서로 다른 형태로 씁니다. 하나의 컴포넌트로 다 커버하려니 옵션이 많아집니다.\n\n2. 성능 이슈\n실시간 시세 데이터를 반영해야 해서, 렌더링 성능도 같이 고려해야 합니다.\n\n3. 진행 방향\n먼저 가장 많이 쓰이는 캔들차트 형태부터 완성하고, 나머지 형태는 옵션으로 확장하는 방식으로 가고 있습니다.\n\n1월 중 완성 목표입니다.', '2024-12-15 09:00:00', '2024-12-15 09:00:00', NULL),
(99, 13, (SELECT id FROM users WHERE employee_no='DT22-0143'), '정보 밀도 이슈 상세 — 화면 재조정 경과', 'HIGH', '1/22 회의 이후 발견된 정보 밀도 이슈, 상세 내용입니다.\n\n1. 문제\n실무진 리뷰에서 "첨부 화면은 확실히 나아졌다"는 긍정 반응이 있었지만, 정보 밀도가 너무 낮아서 여러 화면을 오가야 하는 역설적인 상황이 지적됐습니다.\n\n2. 원인\n클릭 단계를 줄이는 데 집중하다 보니, 화면당 정보량을 충분히 고려하지 못했습니다.\n\n3. 조정 방향\n클릭 단계와 정보 밀도 사이 균형을 다시 잡고 있습니다. 완전히 1단계로 줄이는 게 능사는 아니었다는 걸 이번에 확인했습니다.\n\n조정 완료 목표는 다음 주입니다.', '2025-01-30 09:00:00', '2025-01-30 09:00:00', NULL),
(100, 13, (SELECT id FROM users WHERE employee_no='DT22-0018'), '사용성 테스트 일정 확정 공지', 'MID', '리뉴얼 관련 사용성 테스트 일정을 공지드립니다.\n\n1. 일정\n개발 완료 이후인 4월로 확정합니다.\n\n2. 배경\n디자인시스템 도입 목적 자체가 사용자 경험 개선이니, 실제 사용자 반응을 꼭 확인하고 넘어가야 합니다.\n\n3. 참가 인원\n15명 규모로 진행할 예정입니다.\n\n시나리오 작성은 최이안 선임이 맡습니다.', '2024-11-08 09:00:00', '2024-11-08 09:00:00', NULL),
(101, 13, (SELECT id FROM users WHERE employee_no='DT22-0018'), '프로젝트 진행 상황 종합 정리', 'MID', '11월 킥오프 이후 진행 상황입니다.\n\n1. 디자인시스템: 컴포넌트 10종 완성\n2. 화면 적용: 8개 중 4개 완료(우선순위대로 거래 화면 먼저)\n3. 정보 밀도 이슈: 발견 후 조정 완료\n\n계획보다 2주 정도 늦어졌지만 (컴포넌트 완성 지연 + 정보밀도 재조정), 전체 일정에 큰 영향은 없습니다.', '2025-02-10 09:00:00', '2025-02-10 09:00:00', NULL),
(102, 13, (SELECT id FROM users WHERE employee_no='DT22-0142'), '타사 디자인시스템 벤치마킹', 'LOW', 'MTS 디자인시스템 방향 잡는 데 참고한 자료입니다.\n\n1. 참고한 곳\n다른 증권사·핀테크 앱들의 컴포넌트 라이브러리를 공개된 화면 기준으로 살펴봤습니다.\n\n2. 참고할 점\n차트 컴포넌트를 별도 팀에서 전담 관리하는 곳들이 많았습니다. 저희도 향후 다른 서비스로 확산할 때는 차트 쪽만 별도로 떼서 관리하는 걸 고려해볼 만합니다.', '2024-12-20 09:00:00', '2024-12-20 09:00:00', NULL),
(103, 13, (SELECT id FROM users WHERE employee_no='DT22-0143'), '화면 적용 시 컴포넌트 사용 가이드', 'LOW', '컴포넌트 적용하면서 정리한 가이드입니다.\n\n1. 우선순위\n거래 관련 화면부터 적용하고 있습니다. 사용자 체감이 큰 화면부터 우선했습니다.\n\n2. 적용 팁\n기존 화면 스타일을 그대로 컴포넌트로 옮기려 하지 말고, 컴포넌트 기본값을 최대한 활용하는 게 일관성 유지에 좋습니다.\n\n적용하면서 나온 컴포넌트 개선 요청은 최이안 선임에게 전달 부탁드립니다.', '2025-01-25 09:00:00', '2025-01-25 09:00:00', NULL),
(104, 13, (SELECT id FROM users WHERE employee_no='DT22-0145'), '디자인시스템 구축 프로젝트 회고', 'MID', '오픈 완료 후 돌아보는 글입니다.\n\n1. 제일 오래 걸린 부분\n디자인시스템을 처음 잡는 작업 자체가 제일 오래 걸렸습니다. 한번 만들어두니 이후 컴포넌트 조합이나 화면 적용은 확실히 빨라졌습니다.\n\n2. 정보 밀도 이슈에서 배운 점\n클릭 단계를 줄이는 것과 정보 밀도를 유지하는 것, 이 둘은 트레이드오프 관계라는 걸 명확히 배웠습니다. 다음에 비슷한 UX 개선을 할 때는 두 지표를 처음부터 같이 놓고 검토해야겠습니다.\n\n3. 확산 계획\n이번에 만든 디자인시스템을 다른 서비스에도 확산하는 게 다음 과제입니다.', '2025-06-30 09:00:00', '2025-06-30 09:00:00', NULL),
(105, 14, (SELECT id FROM users WHERE employee_no='DT22-0103'), '모델 후보 3종 비교 상세', 'MID', '2/12 회의에서 보고드린 비교, 세부 수치 공유드립니다.\n\n1. 로지스틱 회귀\n해석이 쉽고 빠르지만 성능 개선폭이 작습니다(v1 대비 5% 수준).\n\n2. 랜덤포레스트\n성능 개선폭이 크고(12~15%) 속도도 준수합니다.\n\n3. SVM\n성능은 나쁘지 않으나 대용량 데이터에서 학습 속도가 눈에 띄게 느립니다.\n\n4. 종합 의견\n저희 데이터 규모를 감안하면 랜덤포레스트가 균형이 제일 좋아 보입니다. 다만 최종 결정 전에 실제 데이터로 한 번 더 검증해보고 싶습니다.', '2025-02-16 09:00:00', '2025-02-16 09:00:00', NULL),
(106, 14, (SELECT id FROM users WHERE employee_no='DT22-0103'), '랜덤포레스트 최종 선정 근거', 'HIGH', '3/19 회의에서 확정한 모델 선정 근거를 자세히 남겨둡니다.\n\n1. 실제 데이터 검증 결과\n세 후보 중 랜덤포레스트가 가장 안정적인 결과를 보였습니다. 특히 소수 클래스(이상 거래) 탐지에서 다른 후보보다 편차가 적었습니다.\n\n2. 운영 관점 고려\n모델 재학습 주기를 고려했을 때도, 랜덤포레스트가 재학습 비용이 상대적으로 낮아 운영 부담이 적습니다.\n\n3. 다음 단계\n학습 데이터셋 구축에 착수합니다.', '2025-03-25 09:00:00', '2025-03-25 09:00:00', NULL),
(107, 14, (SELECT id FROM users WHERE employee_no='DT24-0040'), '학습 데이터셋 구축 — 라벨링 데이터 부족 문제 해결 과정', 'HIGH', '4/23 회의에서 언급한 데이터셋 구축, 어려웠던 점을 자세히 적어봅니다.\n\n1. 문제\n이상 거래로 명확히 라벨링된 데이터가 생각보다 적었습니다. 실제 이상 거래 신고 건수 자체가 전체 거래 대비 매우 적은 비율이기 때문입니다.\n\n2. 해결 방법\n신고 이력뿐 아니라 수기 처리 이력(신고까지는 안 갔지만 내부적으로 이상 처리된 건)까지 모아서 라벨링 데이터를 보강했습니다.\n\n3. 결과\n2년치 데이터를 결합해서 충분한 규모의 학습셋을 구성했습니다. 초기 학습 결과 오탐률 15% 개선을 확인했습니다.', '2025-05-01 09:00:00', '2025-05-01 09:00:00', NULL),
(108, 14, (SELECT id FROM users WHERE employee_no='DT22-0023'), 'v1 한계 및 v2 방향 공지', 'HIGH', '킥오프에서 논의된 v1 한계와 v2 방향을 공식 공지드립니다.\n\n1. v1의 구조적 문제\n룰 기반이라, 신종 이상거래 패턴에 대응하려면 룰을 계속 추가해야 합니다. 룰이 늘어날수록 오탐도 같이 늘어나는 딜레마가 있습니다.\n\n2. v2 방향\n머신러닝 기반 탐지 모델을 도입합니다. 패턴을 사람이 룰로 짜는 게 아니라 데이터에서 학습하게 하는 접근입니다.\n\n3. 목표\n오탐률 개선. 구체적 수치 목표는 모델 후보 검토 후 정하겠습니다.', '2025-01-09 09:00:00', '2025-01-09 09:00:00', NULL),
(109, 14, (SELECT id FROM users WHERE employee_no='DT22-0023'), '프로젝트 중간 점검', 'MID', '1월 킥오프 이후 진행 상황입니다.\n\n1. 모델: 랜덤포레스트 확정\n2. 학습 데이터셋: 구축 완료, 초기 학습 오탐률 15% 개선\n3. 정밀 튜닝: 착수\n\n다음 단계로 사업성 논의를 병행할 예정입니다. 성과가 가시화되고 있는 시점이라, 미리 공유해두는 게 나을 것 같아서요.', '2025-06-20 09:00:00', '2025-06-20 09:00:00', NULL),
(110, 14, (SELECT id FROM users WHERE employee_no='DT22-0082'), '손익 시나리오 산정 참고 자료', 'LOW', '사업성 검토 준비하면서 참고한 자료입니다.\n\n1. 방향\nFDS처럼 직접 매출이 없는 사업은 "방지된 손실"을 정량화하는 게 핵심입니다.\n\n2. 참고 방법론\n탐지율 개선폭에 이상거래 평균 피해 금액을 곱해서 방지 손실을 추산하는 방식을 참고했습니다.\n\n7/9 사업성 검토 회의 자료에 반영하겠습니다.', '2025-06-25 09:00:00', '2025-06-25 09:00:00', NULL),
(111, 14, (SELECT id FROM users WHERE employee_no='DT22-0103'), '백엔드 연동 진행 가이드', 'MID', '백엔드 연동 개발 진행 방식 공유드립니다.\n\n1. 설계 방향\n거래 발생 시점에 모델 추론 결과를 즉시 반영하는 실시간 구조입니다.\n\n2. v1과의 차이\nv1도 실시간이었지만 룰 기반이라 단순했는데, 모델 추론이 들어가면서 구조가 좀 더 복잡해졌습니다. 성능 확보가 핵심 관건입니다.\n\n3. 현재 진행률\n초기 설계 진행 중이며, 성능 테스트 결과는 별도 공유드리겠습니다.', '2025-08-20 09:00:00', '2025-08-20 09:00:00', NULL),
(112, 14, (SELECT id FROM users WHERE employee_no='DT24-0040'), '머신러닝 도입 프로젝트 회고', 'MID', '오늘 v2가 정식 오픈됐습니다. 1월 킥오프부터 지금까지 여정을 돌아봅니다.\n\n1. 머신러닝 처음 도입하면서 걱정했던 것\n팀 내에 머신러닝 경험이 많지 않아서, 모델 선정부터 튜닝까지 시행착오가 있을 걸 예상했습니다.\n\n2. 결과적으로 좋았던 결정\n복잡한 딥러닝 대신 상대적으로 다루기 쉬운 랜덤포레스트를 선택한 게 팀 역량 대비 적절했다고 봅니다. 오탐률 20% 개선이라는 확실한 성과로 이어졌습니다.\n\n3. 남은 과제\nv2로 룰 기반의 한계는 넘었지만, 오탐이 완전히 없어진 건 아닙니다. 다음 단계(v3)에서는 더 정교한 모델을 고민해볼 시점이라고 봅니다.', '2025-12-31 09:00:00', '2025-12-31 09:00:00', NULL),
(113, 15, (SELECT id FROM users WHERE employee_no='DT22-0065'), '초기 대응 타임라인 상세 기록', 'HIGH', '오늘 대응 과정을 시간대별로 상세히 기록해둡니다. 나중에 포스트모템 때 정확한 근거가 필요할 것 같아서요.\n\n1. 10:12 — 이체 지연 최초 감지\n관제 알림으로 처음 확인. 평소 평균 1.2초이던 처리 시간이 15초 이상으로 증가.\n\n2. 10:15 — 긴급 대응팀 소집\n\n3. 10:18 — 초기 조사 시작\n네트워크 구간 모니터링 상으로는 이상 없음을 먼저 확인. 코어뱅킹 연동 쪽 응답이 느려지는 것으로 추정.\n\n4. 10:35 — 임시 조치 적용\n이체 요청 큐잉 방식으로 전환. 타임아웃으로 인한 완전 실패는 방지.\n\n5. 11:05 — 코어뱅킹 배치 종료, 서비스 정상화\n\n원인 조사는 계속 진행 중입니다. 확인되는 대로 업데이트하겠습니다.', '2024-11-15 09:00:00', '2024-11-15 09:00:00', NULL),
(114, 15, (SELECT id FROM users WHERE employee_no='DT22-0053'), '서버 리소스 모니터링 데이터 — 장애 시간대 상세', 'HIGH', '어제 장애 시간대 리소스 모니터링 데이터를 다시 살펴봤습니다.\n\n1. CPU/메모리\n장애 시간대(10:12~11:05) 동안 CPU·메모리 사용률은 평소 대비 특이사항 없었습니다.\n\n2. 커넥션 풀\n다시 자세히 보니, 이체 연동 구간의 DB 커넥션 풀 사용률이 해당 시간대에 평소보다 눈에 띄게 높았습니다. 이 부분이 병목의 단서로 보입니다.\n\n3. 판단\n리소스 부족이 아니라 특정 구간에서의 경합(contention) 문제로 추정됩니다. 코어뱅킹팀과의 협의가 필요한 부분이라 지동원 파트장님께 공유드렸습니다.', '2024-11-16 09:00:00', '2024-11-16 09:00:00', NULL),
(115, 15, (SELECT id FROM users WHERE employee_no='DT22-0058'), '코어뱅킹팀 협의 내용 — 배치 스케줄 변경 확인', 'HIGH', '코어뱅킹팀과 협의한 내용을 상세히 정리합니다.\n\n1. 확인된 사실\n전날 코어뱅킹 측 배치 작업 스케줄이 변경됐습니다. 원래 새벽에 끝나야 할 배치가 오전 10시까지 연장 실행됐습니다.\n\n2. 왜 저희가 몰랐나\n이 스케줄 변경이 저희 쪽에 사전 공지되지 않았습니다. 코어뱅킹팀 내부적으로는 공지했다고 하는데, 저희 인프라팀까지는 전달이 안 됐습니다.\n\n3. 원인 연결\n이 연장 실행 시간대에 이체 연동 구간의 DB 커넥션 풀을 배치 작업과 실거래 처리가 함께 점유하면서 병목이 발생한 것으로 확인됩니다. 어제 발견한 커넥션 풀 이상 현상과 정확히 일치합니다.\n\n4. 다음 단계\n원인이 거의 확정된 것 같습니다. 재발 방지 방안은 포스트모템에서 논의하겠습니다.', '2024-11-17 09:00:00', '2024-11-17 09:00:00', NULL),
(116, 15, (SELECT id FROM users WHERE employee_no='DT22-0022'), '임시 조치 적용 원칙 공지', 'HIGH', '긴급 대응 중 적용한 임시 조치 원칙을 공지드립니다.\n\n1. 원칙\n완전 실패보다는 지연이 낫다는 판단으로, 이체 요청을 큐잉 방식으로 전환했습니다.\n\n2. 고객 영향 최소화\n이 조치로 타임아웃 실패는 막았고, 처리 지연만 발생했습니다. 완전 실패였다면 고객이 재시도해야 하는 불편이 더 컸을 겁니다.\n\n3. 향후 유사 상황 시\n비슷한 지연 상황이 재발하면, 이번처럼 큐잉 전환을 1차 대응으로 우선 적용하는 걸 검토해주시기 바랍니다.\n\n정식 대응 매뉴얼은 포스트모템 이후 정리하겠습니다.', '2024-11-15 09:00:00', '2024-11-15 09:00:00', NULL),
(117, 15, (SELECT id FROM users WHERE employee_no='DT22-0022'), '장애 대응 경과 종합 정리', 'MID', '11/15 장애 이후 지금까지 경과를 종합 정리합니다.\n\n1. 원인\n코어뱅킹 배치 스케줄 변경(사전 공지 누락)으로 인한 DB 커넥션 풀 경합.\n\n2. 대응\n큐잉 전환으로 완전 실패 방지, 배치 종료 후 53분 만에 정상화.\n\n3. 고객 영향\n완전 실패 없음, 처리 지연으로 인한 문의 다수 접수.\n\n4. 남은 절차\n11/20 포스트모템에서 재발 방지 방안(스케줄 상호 통보 프로세스, 커넥션 풀 분리 등)을 논의할 예정입니다.', '2024-11-18 09:00:00', '2024-11-18 09:00:00', NULL),
(118, 15, (SELECT id FROM users WHERE employee_no='DT22-0061'), '유사 배치-실거래 경합 장애 사례 조사', 'LOW', '비슷한 유형의 장애 사례를 찾아봤습니다.\n\n1. 조사 배경\n배치 작업과 실거래 처리가 리소스를 공유하다 발생하는 장애가 저희만의 문제인지 확인하고 싶었습니다.\n\n2. 결과\n비슷한 사례가 업계에 흔히 있는 유형이었습니다. 공통 해법은 배치와 실거래 리소스를 물리적으로 분리하는 것이었습니다.\n\n3. 시사점\n황시온 선임이 제안한 커넥션 풀 분리 방안이 업계에서도 일반적인 해법과 일치합니다. 포스트모템에서 이 방향으로 논의하면 좋겠습니다.', '2024-11-19 09:00:00', '2024-11-19 09:00:00', NULL),
(119, 15, (SELECT id FROM users WHERE employee_no='DT22-0064'), '온콜 대응 매뉴얼 위치 안내', 'LOW', '이번에 대응하면서 매뉴얼 찾는 데 시간이 좀 걸렸다는 얘기가 나와서, 위치를 다시 안내드립니다.\n\n1. 매뉴얼 위치\n인프라팀 공유 문서함 상단에 고정해뒀습니다.\n\n2. 개선 예정\n지금 매뉴얼이 찾기 어렵다는 지적이 있어서, 포스트모템 이후 온콜 대응 매뉴얼 자체를 다시 정비할 예정입니다. 그때 접근성도 같이 개선하겠습니다.\n\n당분간은 이 경로로 확인 부탁드립니다.', '2024-11-19 09:00:00', '2024-11-19 09:00:00', NULL),
(120, 15, (SELECT id FROM users WHERE employee_no='DT22-0022'), '포스트모템 이후 회고', 'MID', '오늘 포스트모템을 마치고 돌아보는 글입니다.\n\n1. 이번 대응에서 잘한 점\n원인 파악을 빠르게 좁혀갔습니다. 리소스 모니터링 데이터와 코어뱅킹팀 협의 내용이 정확히 맞아떨어져서, 원인을 비교적 명확하게 확정할 수 있었습니다.\n\n2. 개선이 필요했던 점\n당직자 소집까지 3분이 걸렸는데, 알림 확인 후 매뉴얼을 찾는 데 시간이 걸린 게 원인이었습니다. 온콜 체계와 매뉴얼 접근성을 다시 정비하기로 했습니다.\n\n3. 재발 방지 방안\n코어뱅킹팀과 배치 스케줄 상호 통보 프로세스를 만들고, DB 커넥션 풀을 물리적으로 분리하기로 했습니다.\n\n4. 배운 점\n다른 팀의 스케줄 변경이 우리 시스템에 영향을 줄 수 있는 지점은, 그 변경을 우리가 알 수 있는 체계가 있어야만 사전에 막을 수 있다는 걸 다시 확인했습니다.', '2024-11-20 09:00:00', '2024-11-20 09:00:00', NULL),
(121, 21, (SELECT id FROM users WHERE employee_no='DT22-0192'), '결제 API 동기 외부 호출 프로파일링 결과 상세', 'MID', '병목 구간 프로파일링 결과 공유드립니다.\n\n1. 확인된 병목\n결제 승인 API 내부에서 외부 PG사 호출을 동기로 처리하고 있었습니다. 트래픽이 몰릴 때 이 부분이 그대로 대기 시간으로 쌓였습니다.\n\n2. 개선 방향\n비동기 처리로 전환하고, 결과는 콜백으로 받는 구조로 바꾸려고 합니다.\n\n3. 예상 효과\n초기 테스트에서 트래픽 몰릴 때 응답 시간이 절반 이하로 줄어드는 걸 확인했습니다. 정식 적용 후 다시 공유드리겠습니다.', '2025-02-20 09:00:00', '2025-02-20 09:00:00', NULL),
(122, 26, (SELECT id FROM users WHERE employee_no='DT22-0176'), '장애 유형별 매뉴얼 초안 — 접근성 개선 필요 사항', 'MID', '매뉴얼 초안 작성하면서 느낀 점 공유드립니다.\n\n1. 8종 매뉴얼 초안\nDB, 네트워크, 외부연동 등 장애 유형별로 초안을 만들었습니다.\n\n2. 신입 대상 모의 훈련에서 발견한 것\n실제로 훈련해보니, 매뉴얼 내용 자체보다 "이 매뉴얼이 어디 있는지 찾는 것"부터 헤매는 경우가 많았습니다. 매뉴얼 내용을 보완하는 것과 별개로, 접근성 개선이 꼭 필요하다고 봅니다.\n\n공용 문서함 상단 고정 및 단축 링크 배포를 제안드립니다.', '2026-02-10 09:00:00', '2026-02-10 09:00:00', NULL),
(123, 30, (SELECT id FROM users WHERE employee_no='DT22-0018'), '스크린리더 접근성 점검 결과 상세', 'HIGH', '1차 접근성 개선 대상 화면 12개 점검 결과입니다.\n\n1. 주요 이슈\n- 이미지 대체 텍스트 누락: 8개 화면\n- 키보드만으로 접근 불가능한 메뉴: 4개 화면\n- 포커스 이동 순서 비논리적: 6개 화면\n\n2. 우선순위\n메뉴 접근 불가 이슈부터 먼저 처리하려고 합니다. 이건 아예 사용이 불가능한 수준이라 심각도가 가장 높습니다.\n\n3. 검증 방식\n실제 스크린리더(NVDA)로 직접 화면을 탐색하면서 확인했습니다. 자동 검사 도구만으로는 놓치는 이슈가 꽤 있었습니다.', '2024-10-20 09:00:00', '2024-10-20 09:00:00', NULL),
(124, 34, (SELECT id FROM users WHERE employee_no='DT22-0142'), '레거시 jQuery 코드 현황 조사', 'LOW', '킥오프 이후 잔존 jQuery 코드 현황을 조사했습니다.\n\n1. 조사 결과\n오래된 화면 6개에서 jQuery 코드가 발견됐습니다. 최신 스택과 혼재된 상태입니다.\n\n2. 전환 난이도\n단순 UI 조작 코드는 전환이 쉬운데, 일부 화면은 jQuery 플러그인에 강하게 의존하고 있어서 대체재부터 찾아야 합니다.\n\n우선순위가 밀리면서 본 착수는 보류 중이지만, 조사 결과는 남겨둡니다. 나중에 재개할 때 참고 바랍니다.', '2025-10-13 09:00:00', '2025-10-13 09:00:00', NULL),
(125, 38, (SELECT id FROM users WHERE employee_no='DT22-0136'), '성능 테스트 환경 구축 진행 — 운영 분리 설계', 'MID', '별도 성능 테스트 환경 구축 진행 상황입니다.\n\n1. 설계 방향\n운영 환경과 완전히 분리된 부하 테스트 환경을 구축 중입니다. 운영 데이터에 영향 없이 마음껏 부하를 걸 수 있게 하는 게 목표입니다.\n\n2. 진행 상황\n인프라 구성은 완료했고, 주요 API 대상 부하 테스트 시나리오를 작성 중입니다.\n\n3. 다음 단계\n시나리오 완성되는 대로 첫 부하 테스트를 진행하고 결과 공유드리겠습니다.', '2025-02-20 09:00:00', '2025-02-20 09:00:00', NULL),
(126, 43, (SELECT id FROM users WHERE employee_no='DT22-0055'), '배포 롤백 자동화 — 실패 감지 기준 상세', 'MID', '자동 롤백이 언제 트리거되는지 기준을 공유드립니다.\n\n1. 트리거 조건\n배포 후 5분 이내 헬스체크 실패율이 일정 기준을 넘으면 자동으로 이전 버전으로 롤백됩니다.\n\n2. 왜 5분인가\n너무 짧으면 정상 배포도 오탐으로 롤백될 수 있고, 너무 길면 장애 시간이 늘어납니다. 몇 차례 테스트 배포로 5분이 적정하다고 판단했습니다.\n\n3. 수동 개입 옵션\n자동 롤백이 원치 않는 상황(의도된 일시적 오류 등)에 대비해 수동으로 취소할 수 있는 옵션도 같이 넣었습니다.', '2024-09-15 09:00:00', '2024-09-15 09:00:00', NULL),
(127, 47, (SELECT id FROM users WHERE employee_no='DT22-0055'), '카오스 엔지니어링 도입 검토 — 국내외 사례 조사', 'LOW', '검토 초기 단계에서 참고할 사례를 찾아봤습니다.\n\n1. 조사 배경\n장애 대응력을 사전에 검증할 방법으로 카오스 엔지니어링이 거론됐는데, 저희 규모에 적합한지부터 확인이 필요했습니다.\n\n2. 참고 사례\n대규모 서비스에서는 상용 도구를 활용해 정기적으로 장애를 주입하는 사례가 많았습니다. 다만 저희 규모에서는 전면 도입보다 특정 컴포넌트 대상 소규모 실험부터 시작하는 게 현실적으로 보입니다.\n\n검토는 계속 진행 중이며, 우선순위 조정으로 본 착수는 잠정 보류 상태입니다.', '2026-03-10 09:00:00', '2026-03-10 09:00:00', NULL),
(128, 50, (SELECT id FROM users WHERE employee_no='DT22-0076'), '재해복구 훈련 1차 — 병목 구간 상세 분석', 'HIGH', '훈련 결과 병목 구간을 분석했습니다.\n\n1. 병목 지점\n백업 데이터센터로의 전환 과정 중, 특히 DNS 전파 대기 시간이 문서 기준보다 훨씬 길게 걸렸습니다.\n\n2. 원인 추정\nDNS TTL 설정이 문서 작성 당시보다 길게 바뀐 채로 방치돼 있었던 것으로 보입니다.\n\n3. 개선 방향\nTTL을 줄이는 것과, 필요시 수동으로 즉시 전환할 수 있는 절차를 추가하는 것 두 가지를 검토 중입니다. 다음 훈련 전까지 보완하겠습니다.', '2025-01-20 09:00:00', '2025-01-20 09:00:00', NULL),
(129, 58, (SELECT id FROM users WHERE employee_no='DT22-0023'), '마이데이터 2.0 연동 모듈 개선 — 연동 모듈 개선 범위', 'MID', '3.0 대응 경험을 바탕으로 2.0 대응 범위를 정리했습니다.\n\n1. 개선 대상\n기존 연동 모듈 중 신규 규격과 안 맞는 필드 매핑 로직을 손봐야 합니다.\n\n2. 3.0 경험이 도움 된 부분\n작년 3.0 대응 때 겪었던 규격 해석 이슈(null 처리 등)를 이번엔 미리 알고 있어서, 비슷한 이슈가 나와도 빠르게 판단할 수 있었습니다.\n\n3. 진행 상황\n순조롭게 진행 중이며, 규제 마감 전 여유 있게 완료할 수 있을 것으로 봅니다.', '2025-10-10 09:00:00', '2025-10-10 09:00:00', NULL),
(130, 62, (SELECT id FROM users WHERE employee_no='DT22-0039'), '개인정보 암호화 누락 테이블 발견 경위', 'HIGH', '정기 점검 중 발견한 암호화 누락 건 상세입니다.\n\n1. 발견 경위\n분기별 정기 점검 과정에서, 일부 레거시 테이블에 암호화가 적용 안 돼 있는 걸 발견했습니다. 시스템이 오래돼서 최근 암호화 정책 적용 시점에 누락된 것으로 추정됩니다.\n\n2. 영향 범위\n해당 테이블 접근 이력을 확인한 결과, 외부 유출 정황은 없었습니다.\n\n3. 조치 계획\n대상 테이블 전체에 암호화를 적용하고, 재점검까지 진행할 예정입니다.', '2025-03-10 09:00:00', '2025-03-10 09:00:00', NULL),
(131, 69, (SELECT id FROM users WHERE employee_no='DT22-0122'), '사내 리소스 배분 도구 고도화 — 초기 기능 개선 방향', 'LOW', '2차 고도화 방향을 정리했습니다.\n\n1. 1차 도구의 문제\n활용도가 낮았던 이유를 다시 살펴보니, 데이터 입력이 수작업이라 다들 갱신을 귀찮아했던 게 컸습니다.\n\n2. 개선 방향\n프로젝트 관리 시스템과 자동 연동해서 수작업 입력을 없애는 방향을 검토했습니다.\n\n논의 중에 PrettyWorks 전사 도입이 결정되면서, 이 개선 작업 자체가 의미가 없어져 중단됐습니다. 검토 내용은 참고용으로 남겨둡니다.', '2026-01-20 09:00:00', '2026-01-20 09:00:00', NULL),
(132, 73, (SELECT id FROM users WHERE employee_no='DT22-0093'), '코어뱅킹 아키텍처 컨설팅 방법론 — 단계별 산출물 정의', 'MID', '정리 중인 방법론의 단계별 산출물을 공유드립니다.\n\n1. 진단 단계\n현황 진단 보고서, 노후도 평가표.\n\n2. 설계 단계\n아키텍처 대안 비교표, 권고안.\n\n3. 로드맵 단계\n우선순위별 실행 로드맵, 개략 견적.\n\n각 단계마다 표준 템플릿을 만들어서, 프로젝트마다 산출물 품질이 담당자 역량에 좌우되지 않도록 하는 게 목표입니다.', '2025-07-15 09:00:00', '2025-07-15 09:00:00', NULL),
(133, 79, (SELECT id FROM users WHERE employee_no='DT23-0025'), '신규 고객군 접촉 우선순위 산정 기준', 'MID', '잠재 고객군 분석 결과와 접촉 우선순위 기준을 공유드립니다.\n\n1. 분석 대상\n2금융권(저축은행, 캐피탈) 중 아직 접촉이 없는 회사들.\n\n2. 우선순위 기준\n자산 규모, IT 투자 계획 공개 여부, 기존 시스템 노후도(공개 정보 기준 추정)를 종합해서 점수화했습니다.\n\n3. 결과\n상위 10개사를 1차 접촉 대상으로 추렸습니다. 명단은 별도 자료로 공유드리겠습니다.', '2025-12-10 09:00:00', '2025-12-10 09:00:00', NULL),
(134, 82, (SELECT id FROM users WHERE employee_no='DT23-0021'), '그룹사 시너지 과제 후보 5건 상세', 'MID', '발굴한 시너지 과제 후보를 상세히 정리했습니다.\n\n1. 후보 목록\n1) 그룹 통합 리워드 프로그램 2) 계열사 간 고객 데이터 연계 마케팅 3) 공동 IT 인프라 활용 4) 그룹 통합 CS 채널 5) 계열사 간 인력 교류 프로그램\n\n2. 우선순위가 높다고 본 것\n1번(통합 리워드)은 실행 난도 대비 효과가 커 보입니다. 2번은 효과는 크지만 데이터 정책 조율이 필요해 시간이 걸릴 것 같습니다.\n\n실행은 각 부서 몫이지만, 발굴 결과는 여기까지 정리해서 마무리합니다.', '2025-06-20 09:00:00', '2025-06-20 09:00:00', NULL),
(135, 86, (SELECT id FROM users WHERE employee_no='DT22-0028'), '계약 유형별 표준 체크리스트 초안', 'MID', '체크리스트 초안을 공유드립니다.\n\n1. 계약 유형 분류\n용역, 구매, 라이선스 세 유형으로 나눠서 체크리스트를 따로 만들었습니다. 유형마다 확인해야 할 포인트가 달라서입니다.\n\n2. 공통 체크 항목\n손해배상 조항, 계약 해지 조건, 지식재산권 귀속은 모든 유형에 공통으로 넣었습니다.\n\n피드백 주시면 반영해서 다음 주 최종본 내겠습니다.', '2025-04-10 09:00:00', '2025-04-10 09:00:00', NULL),
(136, 90, (SELECT id FROM users WHERE employee_no='DT22-0012'), '직군 공통 평가 기준 설계 — 정성/정량 비율 검토', 'MID', '평가 기준 설계 중 고민되는 부분을 공유드립니다.\n\n1. 쟁점\n정량 평가(목표 달성률 등)와 정성 평가(협업 태도 등) 비율을 직군마다 다르게 할지, 공통으로 할지가 쟁점입니다.\n\n2. 검토 방향\n완전히 다르게 하면 공정성 시비가 재발할 수 있고, 완전히 같게 하면 직군 특성을 못 살립니다. 기본 비율은 공통으로 하되, 직군별 세부 항목만 다르게 하는 절충안을 검토 중입니다.\n\n의견 있으시면 말씀 부탁드립니다.', '2025-11-10 09:00:00', '2025-11-10 09:00:00', NULL),
(137, 92, (SELECT id FROM users WHERE employee_no='DT22-0034'), '프로젝트별 실시간 원가 집계 — 설계 방향', 'MID', '원가 관리 체계 고도화 설계 방향을 공유드립니다.\n\n1. 기존 문제\n결산 시점에야 프로젝트 수익성을 알 수 있어서, 문제가 생겨도 대응이 늦었습니다.\n\n2. 설계 방향\n인건비·경비 발생 시점에 바로 해당 프로젝트로 집계되는 구조로 바꾸려고 합니다.\n\n3. 예상 효과\n프로젝트 진행 중에도 실시간으로 수익성을 확인할 수 있게 됩니다. PM들도 이 데이터를 참고해서 중간에 리소스 조정을 할 수 있을 것 같습니다.', '2025-03-20 09:00:00', '2025-03-20 09:00:00', NULL),
(138, 21, (SELECT id FROM users WHERE employee_no='DT22-0166'), '비동기 처리 전환 설계안 상세', 'MID', '3/3 회의에서 발표한 설계안, 자세히 정리해서 공유드립니다.\n\n1. 구조\n결제 승인 API에서 PG사 호출을 동기 대기 대신 비동기로 보내고, 응답은 콜백으로 받는 구조로 바꿉니다.\n\n2. 콜백 유실 대비\nPG사 쪽 사정으로 콜백이 안 올 수도 있어서, 재시도 로직이 필요하다고 판단했습니다. 재시도 큐는 신규 도입보다 사내 메시지 큐를 재사용하는 쪽으로 우선 검토하고 있습니다.\n\n3. 일정\n3월 중 구현 착수, 4월 말 부하 테스트를 목표로 잡고 있습니다.\n\n의견 있으시면 댓글로 남겨주세요.', '2025-03-05 09:00:00', '2025-03-05 09:00:00', NULL),
(139, 21, (SELECT id FROM users WHERE employee_no='DT22-0182'), '타사 결제 시스템 비동기 처리 사례 조사', 'LOW', '비동기 전환 설계 참고할 만한 사례들 찾아봤습니다.\n\n1. 공통 패턴\n결제 승인과 PG사 연동을 분리하고, 연동 결과는 콜백이나 폴링으로 받는 구조가 많았습니다. 저희가 잡은 방향과 비슷합니다.\n\n2. 재시도 처리\n대부분 재시도 큐를 별도로 두고, 일정 횟수 실패하면 수동 개입 알림을 보내는 방식을 쓰고 있었습니다. 저희도 재시도 한도를 넘으면 알림이 가도록 같이 검토하면 좋을 것 같습니다.\n\n참고 자료는 별도로 정리해서 공유드리겠습니다.', '2025-03-17 09:00:00', '2025-03-17 09:00:00', NULL),
(140, 21, (SELECT id FROM users WHERE employee_no='DT22-0195'), '콜백 유실 이슈 상세 — 재현 조건과 원인', 'HIGH', '3/24 회의에서 보고드린 콜백 유실 이슈, 재현 조건 정리했습니다.\n\n1. 재현 조건\nPG사 응답이 지연되는 상황(3초 이상)에서 저희 쪽 타임아웃(2초)이 먼저 걸리는 경우, 이후에 실제로 도착하는 콜백을 받을 곳이 없어서 유실됐습니다.\n\n2. 원인\n저희 타임아웃 설정이 PG사의 최대 응답 지연 시간보다 짧게 잡혀 있었습니다.\n\n3. 대응\n타임아웃을 늘리는 대신, 재시도 큐로 유실분을 회수하는 방향으로 갑니다. 타임아웃을 늘리면 다른 요청 처리에 영향이 갈 수 있어서요.\n\n재시도 큐 연동은 3/28까지 마무리하겠습니다.', '2025-03-26 09:00:00', '2025-03-26 09:00:00', NULL),
(141, 21, (SELECT id FROM users WHERE employee_no='DT22-0166'), '재시도 큐 도입 결정 공지', 'HIGH', '콜백 유실 이슈 대응 관련, 최종 결정 공지드립니다.\n\n1. 결정\n재시도 큐는 신규 도입 대신 사내 메시지 큐를 재사용하기로 확정했습니다.\n\n2. 이유\n신규 도입은 운영 부담이 늘어나는데, 기존 메시지 큐로도 재시도 요건(최대 3회, 실패 시 알림)을 충분히 처리할 수 있다고 판단했습니다.\n\n3. 적용\n오늘부로 연동 작업 들어갑니다. 4월 말 부하 테스트에서 재시도 큐까지 같이 검증하겠습니다.', '2025-03-28 09:00:00', '2025-03-28 09:00:00', NULL),
(142, 21, (SELECT id FROM users WHERE employee_no='DT22-0166'), '2개월 진행 정리', 'MID', '1월 킥오프 이후 진행 상황을 정리했습니다.\n\n1. 병목 확인: 완료 (결제 승인 API의 동기 PG사 호출)\n2. 설계: 완료 (비동기 처리 + 재시도 큐)\n3. 콜백 유실 이슈: 원인 확인 및 대응 방향 확정\n4. 구현: 진행 중, 재시도 큐 연동이 핵심 남은 작업\n\n다음 달 말 부하 테스트를 목표로 순조롭게 가고 있습니다.', '2025-04-01 09:00:00', '2025-04-01 09:00:00', NULL),
(143, 21, (SELECT id FROM users WHERE employee_no='DT22-0170'), '결제 흐름 정리 — 신규 합류자용', 'LOW', '이번 주 합류하신 분들 참고하시라고 결제 흐름 간단히 정리했습니다.\n\n1. 기존 흐름\n결제 승인 요청 → 내부 검증 → PG사 호출(동기) → 응답 대기 → 결과 반환\n\n2. 변경 중인 흐름\n결제 승인 요청 → 내부 검증 → PG사 호출(비동기) → 콜백 대기 → 콜백 도착 시 결과 반환, 유실 시 재시도 큐로 회수\n\n3. 참고\n재시도 큐 연동 부분은 아직 진행 중이라 코드 리뷰 때 이 부분 위주로 보시면 흐름 잡기 편하실 것 같습니다.', '2025-04-14 09:00:00', '2025-04-14 09:00:00', NULL),
(144, 21, (SELECT id FROM users WHERE employee_no='DT22-0192'), '결제 성능 개선 프로젝트 회고', 'MID', '어제(5/20) 종료 보고 이후, 프로젝트 돌아보는 글 남깁니다.\n\n1. 잘한 점\n프로파일링을 먼저 제대로 하고 시작한 게 컸습니다. 의심 구간을 짐작만으로 고치려 했으면 엉뚱한 곳을 만졌을 수도 있었을 것 같습니다.\n\n2. 아쉬운 점\n콜백 유실 이슈는 설계 단계에서 좀 더 미리 생각했으면 3월 말에 급하게 대응 안 해도 됐을 것 같습니다. 다음엔 비동기 전환할 때 "실패 시나리오"를 설계 리뷰에서 처음부터 같이 짚어야겠습니다.\n\n3. 결과\n트래픽 피크 시 응답 시간 평균 60% 단축, 재시도 큐로 안정성도 같이 확보했습니다.', '2025-05-20 16:00:00', '2025-05-20 16:00:00', NULL),
(145, 25, (SELECT id FROM users WHERE employee_no='DT22-0188'), '핵심 배치 15개 선정 기준 정리', 'MID', '9/22 회의에서 말씀드린 배치 선정 기준, 자세히 정리해서 공유드립니다.\n\n1. 전체 현황\n돌고 있는 배치 잡은 총 31개입니다. 이번 리팩토링은 이 중 실행 빈도가 높고 장애 이력이 있는 15개로 범위를 잡았습니다.\n\n2. 제외한 16개\n실행 빈도가 낮거나, 최근 안정적으로 돌고 있거나, 곧 폐기될 예정인 배치들입니다. 굳이 지금 손댈 필요가 없다고 판단했습니다.\n\n3. 담당자 공백 이슈\n선정된 15개 중 3개는 원래 담당하던 분이 이미 퇴사해서, 로직 파악부터 다시 해야 하는 상황입니다. 이 3개는 남기욱 사원이 우선 분석 착수합니다.', '2025-09-25 09:00:00', '2025-09-25 09:00:00', NULL),
(146, 25, (SELECT id FROM users WHERE employee_no='DT22-0164'), '배치 구조 정리 방향 — 모듈 분리 설계', 'MID', '리팩토링 진행 방향 공유드립니다.\n\n1. 기존 문제\n배치 하나에 데이터 조회, 계산, 저장 로직이 한 파일에 다 섞여 있어서 어디를 고쳐야 할지 파악하는 데만 한참 걸립니다.\n\n2. 정리 방향\n조회/계산/저장을 별도 모듈로 나누고, 각 모듈에 무슨 역할인지 주석을 남기려고 합니다. 기능은 그대로 두고 구조만 정리하는 겁니다.\n\n3. 우선순위\n담당자 공백인 3개 배치부터 먼저 정리합니다. 로직 파악과 구조 정리를 같이 해야 해서 시간이 더 걸릴 것 같습니다.', '2025-10-06 09:00:00', '2025-10-06 09:00:00', NULL),
(147, 25, (SELECT id FROM users WHERE employee_no='DT25-0056'), '레거시 배치 리팩토링 참고 사례', 'LOW', '비슷한 작업 참고할 만한 사례 찾아봤습니다.\n\n1. 공통 접근\n기능 변경 없이 구조만 정리하는 경우, 대부분 리팩토링 전/후 결과를 나란히 비교하는 방식으로 검증하고 있었습니다. 저희가 12/15 회의에서 정한 방향과 같습니다.\n\n2. 참고할 점\n리팩토링 중 발견되는 "숨은 로직"은 지우지 말고 명시적으로 남겨두라는 조언이 많았습니다. 이유를 모르고 지웠다가 나중에 장애로 돌아온 사례가 있다고 합니다.\n\n저희도 참고해서 진행하면 좋을 것 같습니다.', '2025-10-15 09:00:00', '2025-10-15 09:00:00', NULL),
(148, 25, (SELECT id FROM users WHERE employee_no='DT22-0195'), '리팩토링 중 발견한 숨은 로직 상세', 'HIGH', '10/20, 11/17 회의에서 말씀드린 숨은 로직, 전수 확인 결과 정리했습니다.\n\n1. 발견 건수\n총 4건입니다. 전부 특정 조건에서만 타는 예외 분기라, 평소 테스트에서는 걸리지 않았던 것들입니다.\n\n2. 대표 사례\n담당자 공백이던 배치 중 하나는, 특정 계좌 타입일 때만 별도 처리를 타는 분기가 있었습니다. 이걸 놓치고 그냥 정리했으면 야간 배치가 조용히 실패했을 수 있습니다.\n\n3. 처리 방향\n로직을 지우지 않고, 조건문과 주석으로 명시화하기로 했습니다. 기능은 하나도 안 건드립니다.\n\n남은 3건도 같은 방식으로 이번 주 안에 마무리하겠습니다.', '2025-11-10 09:00:00', '2025-11-10 09:00:00', NULL),
(149, 25, (SELECT id FROM users WHERE employee_no='DT22-0188'), '숨은 로직 처리 방향 확정 공지', 'HIGH', '11/17 회의에서 결정된 숨은 로직 처리 방향, 공식적으로 공지드립니다.\n\n1. 결정\n발견된 숨은 로직 4건은 전부 삭제하지 않고, 명시적인 조건문과 주석으로 남기기로 확정했습니다.\n\n2. 이유\n이유를 모른 채 지웠다가 나중에 장애로 돌아올 수 있다는 우려가 있었습니다. 기능 변경이 없어야 하는 리팩토링이라, 안전한 쪽으로 결정했습니다.\n\n3. 진행\n남기욱 사원이 4건 전부 명시화 작업을 마쳤습니다. 다음 회의에서 회귀 테스트 계획을 같이 정하겠습니다.', '2025-11-18 09:00:00', '2025-11-18 09:00:00', NULL),
(150, 25, (SELECT id FROM users WHERE employee_no='DT22-0164'), '3개월 진행 정리', 'MID', '9월 킥오프 이후 진행 상황을 정리했습니다.\n\n1. 배치 선정: 완료 (31개 중 15개)\n2. 구조 정리: 완료 (15개 전체)\n3. 숨은 로직: 4건 발견, 전부 명시화 완료\n4. 남은 일정: 회귀 테스트만 남았습니다\n\n담당자 공백이던 3개 배치가 예상보다 시간이 걸렸지만, 전체 일정에는 큰 영향 없이 가고 있습니다.', '2025-12-01 09:00:00', '2025-12-01 09:00:00', NULL),
(151, 25, (SELECT id FROM users WHERE employee_no='DT22-0167'), '리팩토링된 배치 구조 가이드', 'LOW', '리팩토링 끝난 배치들, 신규 합류자나 다른 팀원분들 참고하시라고 가이드 정리했습니다.\n\n1. 기존 구조\n조회·계산·저장 로직이 파일 하나에 섞여 있었습니다.\n\n2. 정리된 구조\n조회/계산/저장을 모듈별로 나눴고, 각 모듈 상단에 역할 주석을 남겼습니다.\n\n3. 숨은 로직 확인법\n예외 분기가 있는 곳은 조건문 위에 "왜 이 분기가 필요한지" 주석을 달아뒀습니다. 코드 보시다가 이상한 조건문이 있으면 대부분 이유가 주석에 있을 겁니다.\n\n궁금한 점 있으면 편하게 물어보세요.', '2025-12-20 09:00:00', '2025-12-20 09:00:00', NULL),
(152, 25, (SELECT id FROM users WHERE employee_no='DT22-0164'), '코어뱅킹 배치 리팩토링 회고', 'MID', '오늘(1/20) 종료 보고 이후, 돌아보는 글 남깁니다.\n\n1. 잘한 점\n숨은 로직을 지우지 않고 명시화하는 쪽으로 결정한 게 맞았다고 봅니다. 기능 변경 없이 가독성만 개선한다는 원칙을 끝까지 지켰습니다.\n\n2. 아쉬운 점\n담당자 공백인 배치 3개 때문에 초반 일정이 예상보다 밀렸습니다. 다음엔 착수 전에 담당자 재직 여부부터 먼저 확인해야겠습니다.\n\n3. 결과\n핵심 배치 15개 구조 정리 및 문서화 완료, 회귀 테스트로 기능 동일함도 확인했습니다.', '2026-01-20 16:00:00', '2026-01-20 16:00:00', NULL),
(153, 28, (SELECT id FROM users WHERE employee_no='DT23-0039'), '기존 화면 스타일 불일치 실태조사', 'MID', '킥오프에서 언급된 스타일 불일치, 실제로 얼마나 심한지 조사해봤습니다.\n\n1. 조사 범위\n주요 화면 22개를 훑어봤습니다.\n\n2. 결과\n버튼 색상만 6가지 변형이 쓰이고 있었고, 인풋 테두리 두께도 화면마다 1px~2px로 제각각이었습니다. 모달은 3개 화면에서 각각 다른 애니메이션을 쓰고 있었습니다.\n\n3. 시사점\n디자이너 한 분이 지적하면 그 화면만 고쳐지고 다른 화면은 그대로 남는 패턴이 반복된 것 같습니다. 공통 컴포넌트로 묶으면 이런 반복을 근본적으로 줄일 수 있을 것 같습니다.', '2024-01-22 09:00:00', '2024-01-22 09:00:00', NULL),
(154, 28, (SELECT id FROM users WHERE employee_no='DT22-0142'), '디자인 토큰 설계 — 컬러/스페이싱 체계', 'MID', '1/29 회의에서 논의한 디자인 토큰, 설계안 공유드립니다.\n\n1. 컬러 토큰\nPrimary/Secondary/Danger/Neutral 4개 계열로 나누고, 계열마다 명도 단계를 5단계로 뒀습니다.\n\n2. 스페이싱 토큰\n4px 단위 배수(4/8/12/16/24/32)로 통일했습니다. 화면마다 임의의 px 값을 쓰던 걸 이걸로 대체합니다.\n\n3. 적용 방식\n컴포넌트 코드에서 값을 직접 쓰지 않고 토큰 변수만 참조하도록 만들 겁니다. 나중에 색상 하나를 바꿔도 토큰 값만 고치면 전체에 반영됩니다.\n\n의견 있으시면 이번 주까지 말씀 부탁드립니다.', '2024-02-02 09:00:00', '2024-02-02 09:00:00', NULL),
(155, 28, (SELECT id FROM users WHERE employee_no='DT23-0037'), '타사 디자인 시스템 벤치마킹', 'LOW', '컴포넌트 설계에 참고하려고 몇몇 공개 디자인 시스템을 훑어봤습니다.\n\n1. 공통점\n대부분 컬러·스페이싱·타이포그래피를 토큰으로 먼저 정의하고, 그 위에 컴포넌트를 얹는 구조였습니다. 저희가 잡은 방향과 같습니다.\n\n2. 참고할 점\n접근성 요건(포커스 표시, 색 대비)을 컴포넌트 명세에 처음부터 포함시켜둔 곳이 많았습니다. 저희도 나중에 따로 붙이기보다 지금부터 같이 챙기면 좋을 것 같습니다.\n\n캡처 자료는 별도로 정리해서 공유드리겠습니다.', '2024-02-26 09:00:00', '2024-02-26 09:00:00', NULL),
(156, 28, (SELECT id FROM users WHERE employee_no='DT22-0149'), '1개월 진행 정리', 'MID', '1월 킥오프 이후 진행 상황을 정리했습니다.\n\n1. 디자인 토큰: 확정 완료 (컬러 4계열, 스페이싱 4px 단위)\n2. 컴포넌트: 버튼·인풋 1차 완성, 나머지 13종 순차 진행 중\n3. 발견된 이슈: 인풋 에러 상태 스타일 불일치 → 수정 완료\n\n다음 달까지 나머지 컴포넌트 완성이 목표입니다.', '2024-02-15 09:00:00', '2024-02-15 09:00:00', NULL),
(157, 28, (SELECT id FROM users WHERE employee_no='DT22-0152'), '모달 컴포넌트 접근성 이슈 상세', 'HIGH', '3/11 회의에서 보고드린 접근성 이슈, 재현 조건 정리했습니다.\n\n1. 재현 조건\n모달을 열었을 때 포커스가 배경 요소에 그대로 남아있어서, 스크린리더 사용자는 모달이 열린 것 자체를 인지하기 어려웠습니다. 키보드로 Tab을 눌러도 배경 요소들 사이에서만 이동했습니다.\n\n2. 원인\n모달 오픈 시 포커스를 모달 내부로 옮기는 처리가 빠져 있었습니다.\n\n3. 대응\n포커스 트랩(모달이 열려있는 동안 포커스를 모달 내부에만 가두는 처리)을 추가하기로 했습니다. 드롭다운도 같은 문제가 있어서 같이 적용합니다.\n\n이번 주 안에 반영하겠습니다.', '2024-03-13 09:00:00', '2024-03-13 09:00:00', NULL),
(158, 28, (SELECT id FROM users WHERE employee_no='DT22-0142'), '컴포넌트 15종 최종 확정 공지', 'HIGH', '컴포넌트 라이브러리 범위 최종 확정 공지드립니다.\n\n1. 확정 목록\n버튼, 인풋, 모달, 드롭다운, 체크박스 등 총 15종입니다.\n\n2. 접근성 반영\n모달·드롭다운에 포커스 트랩을 적용해 접근성 이슈까지 해결한 상태로 확정합니다.\n\n3. 배포 일정\n4/20 종료 보고에서 정식 배포합니다. 다음 화면 작업부터는 이 컴포넌트로 조립하듯 가져다 쓰시면 됩니다.', '2024-03-15 09:00:00', '2024-03-15 09:00:00', NULL),
(159, 28, (SELECT id FROM users WHERE employee_no='DT22-0158'), '공통 컴포넌트 사용 가이드', 'LOW', '컴포넌트 라이브러리 정식 배포됐으니, 사용법 간단히 정리해서 공유드립니다.\n\n1. 가져다 쓰는 법\n디자인 토큰은 이미 컴포넌트 내부에 다 반영돼 있어서, 별도로 색상·간격 값을 지정할 필요 없이 컴포넌트만 불러오면 됩니다.\n\n2. 커스터마이징이 필요할 때\n혹시 특수한 화면이라 스타일을 조금 바꿔야 하면, 컴포넌트를 직접 고치지 말고 담당자(임태오)에게 먼저 말씀해주세요. 다들 각자 고치기 시작하면 다시 예전처럼 제각각이 됩니다.\n\n궁금한 점 있으면 편하게 물어보세요.', '2024-04-19 09:00:00', '2024-04-19 09:00:00', NULL),
(160, 28, (SELECT id FROM users WHERE employee_no='DT22-0156'), '컴포넌트 라이브러리 구축 회고', 'MID', '오늘(4/20) 종료 보고 이후, 돌아보는 글 남깁니다.\n\n1. 잘한 점\n디자인 토큰을 컴포넌트보다 먼저 정의한 게 맞는 순서였습니다. 토큰 없이 컴포넌트부터 만들었으면 나중에 값 하나 바꿀 때마다 15종을 전부 다시 손봐야 했을 겁니다.\n\n2. 아쉬운 점\n접근성 요건을 설계 초반부터 명세에 넣지 못하고 3월에 뒤늦게 발견해서 반영했습니다. 다음 컴포넌트 작업부터는 처음부터 접근성 체크리스트를 같이 놓고 시작해야겠습니다.\n\n3. 결과\n버튼·인풋·모달 등 핵심 컴포넌트 15종 완성, 사용 가이드까지 정리해 배포했습니다.', '2024-04-20 16:00:00', '2024-04-20 16:00:00', NULL),
(161, 30, (SELECT id FROM users WHERE employee_no='DT22-0162'), 'WCAG 기준 적용 사례 조사', 'LOW', '착수 전에 WCAG 기준을 실제로 어떻게 적용했는지 사례를 찾아봤습니다.\n\n1. 조사 방법\n공개된 접근성 개선 사례와 WCAG 2.1 AA 기준 문서를 같이 봤습니다.\n\n2. 우선순위 참고\n대부분 "인지 자체가 안 되는" 이슈(키보드 접근 불가, 스크린리더 미인식)를 최우선으로 처리하고, "불편하지만 가능한" 이슈는 그다음으로 미루는 순서였습니다. 저희도 이 순서를 참고하면 좋을 것 같습니다.\n\n참고 자료는 별도로 정리해서 공유드리겠습니다.', '2024-09-20 09:00:00', '2024-09-20 09:00:00', NULL),
(162, 30, (SELECT id FROM users WHERE employee_no='DT22-0018'), '1차 개선 범위 확정 공지', 'HIGH', '9/30 회의에서 결정된 1차 개선 범위, 공지드립니다.\n\n1. 확정 범위\n메뉴 접근 불가 이슈가 있는 4개 화면을 최우선으로 처리합니다. 이미지 대체 텍스트 작업은 병행합니다.\n\n2. 제외 범위\n포커스 이동 순서 문제는 메뉴 개선과 겹치는 부분이 많아 같이 처리하되, 나머지 화면들은 이번 1차 범위에서 제외하고 2차로 넘깁니다.\n\n3. 일정\n12/13 종료 보고 전까지 확정 범위 전체 완료를 목표로 합니다.', '2024-09-30 15:00:00', '2024-09-30 15:00:00', NULL),
(163, 30, (SELECT id FROM users WHERE employee_no='DT22-0154'), '키보드 접근 메뉴 개선 설계안', 'MID', '9/30 회의에서 맡은 메뉴 개선 설계안 공유드립니다.\n\n1. 문제\n일부 메뉴가 마우스 호버로만 열려서, 키보드로는 하위 메뉴에 진입할 방법이 없었습니다.\n\n2. 설계 방향\n포커스가 메뉴에 도달하면 Enter/Space로 열리고, 화살표 키로 하위 항목을 이동할 수 있게 바꿉니다. 탭 순서도 화면에 보이는 순서와 일치시킵니다.\n\n3. 적용 대상\n4개 화면 중 3개는 구조가 단순해 빠르게 적용 가능하고, 나머지 1개는 중첩 메뉴가 있어 별도로 시간을 더 잡았습니다.', '2024-10-02 09:00:00', '2024-10-02 09:00:00', NULL),
(164, 30, (SELECT id FROM users WHERE employee_no='DT22-0162'), '포커스 이동 순서 문제 상세', 'HIGH', '11/11 회의에서 언급한 포커스 순서 문제, 상세 정리했습니다.\n\n1. 재현 조건\n화면에 보이는 순서와 실제 Tab 이동 순서가 달라서, 스크린리더 사용자는 엉뚱한 순서로 내용을 듣게 됩니다. 6개 화면에서 확인됐습니다.\n\n2. 원인\nHTML 마크업 순서가 화면 배치 순서와 다르게 작성돼 있었습니다. CSS로 위치만 재배치한 경우가 대부분이었습니다.\n\n3. 대응\n메뉴 개선 작업과 같이, 마크업 순서 자체를 화면 순서와 맞추는 방식으로 수정 중입니다.', '2024-11-04 09:00:00', '2024-11-04 09:00:00', NULL),
(165, 30, (SELECT id FROM users WHERE employee_no='DT24-0047'), '2개월 진행 정리', 'MID', '9월 킥오프 이후 진행 상황을 정리했습니다.\n\n1. 이미지 대체 텍스트: 완료 (8개 화면)\n2. 메뉴 접근성: 4개 중 3개 완료, 1개 진행 중\n3. 포커스 순서: 메뉴 개선과 병행 진행 중\n\n남은 작업도 12/13 종료 보고 전까지 마무리할 수 있을 것 같습니다.', '2024-11-15 09:00:00', '2024-11-15 09:00:00', NULL),
(166, 30, (SELECT id FROM users WHERE employee_no='DT22-0154'), '접근성 체크리스트 — 앞으로 화면 작업 시 참고', 'LOW', '1차 개선하면서 정리한 체크리스트, 앞으로 화면 작업하실 때 참고하시라고 공유드립니다.\n\n1. 이미지\n의미 있는 이미지는 대체 텍스트를 꼭 넣어주세요. 장식용 이미지는 빈 alt로 처리하면 됩니다.\n\n2. 키보드 접근\n마우스 호버로만 열리는 요소가 없는지 확인해주세요. 메뉴·드롭다운은 특히 신경 써야 합니다.\n\n3. 마크업 순서\nCSS로 위치만 바꾸지 말고, HTML 마크업 순서 자체를 화면에 보이는 순서와 맞춰주세요.\n\n체크리스트 전체는 위키에 정리해뒀습니다.', '2024-12-10 09:00:00', '2024-12-10 09:00:00', NULL),
(167, 30, (SELECT id FROM users WHERE employee_no='DT24-0047'), '1차 접근성 개선 회고', 'MID', '오늘(12/13) 종료 보고 이후, 돌아보는 글 남깁니다.\n\n1. 잘한 점\n자동 검사 도구만 믿지 않고 실제 스크린리더(NVDA)로 직접 탐색하면서 점검한 게 컸습니다. 자동 도구로는 안 잡히는 이슈가 실제로 꽤 있었습니다.\n\n2. 아쉬운 점\n포커스 순서 문제를 메뉴 개선과 뒤늦게 같이 묶어서 처리하다 보니, 초반에 범위를 나눌 때 좀 더 꼼꼼히 봤으면 더 매끄러웠을 것 같습니다.\n\n3. 결과\n주요 화면 12개 대상 WCAG 기준 충족 완료. 나머지 화면은 감사 지적 사항을 보면서 2차로 이어갑니다.', '2024-12-13 16:00:00', '2024-12-13 16:00:00', NULL),
(168, 33, (SELECT id FROM users WHERE employee_no='DT22-0149'), '차트 라이브러리 후보 비교 조사', 'LOW', '통일할 라이브러리 후보 3종을 비교해봤습니다.\n\n1. 비교 기준\n번들 사이즈, 렌더링 성능(대용량 데이터 기준), API 학습 난이도, 커스터마이징 용이성 4가지로 봤습니다.\n\n2. 결과\nA 라이브러리는 번들 사이즈가 가장 작지만 커스터마이징이 까다로웠고, B는 반대로 커스터마이징은 쉬운데 번들이 컸습니다. C는 두 지표가 중간이면서 API가 제일 직관적이었습니다.\n\n3. 의견\n저는 C가 균형이 좋다고 생각합니다. 회의에서 같이 논의하면 좋겠습니다.', '2025-07-10 09:00:00', '2025-07-10 09:00:00', NULL),
(169, 33, (SELECT id FROM users WHERE employee_no='DT23-0036'), '차트 라이브러리 사용 현황 조사 상세', 'MID', '7/22 회의에서 공유드린 조사, 자세히 정리했습니다.\n\n1. 조사 범위\n다온뱅크·다온증권·다온페이 화면에서 쓰이는 차트를 전부 훑었습니다.\n\n2. 결과\n서비스마다 다른 라이브러리 3종을 쓰고 있었고, 번들 사이즈도 최대 3배 차이가 났습니다. API 스타일도 완전히 달라서, 담당자가 바뀌면 새로 배워야 하는 구조였습니다.\n\n3. 영향\n버그 하나 고치는 방법도 서비스마다 달라서, 같은 유형의 이슈를 세 번 따로 대응한 사례도 있었습니다.', '2025-07-25 09:00:00', '2025-07-25 09:00:00', NULL),
(170, 33, (SELECT id FROM users WHERE employee_no='DT22-0018'), '차트 라이브러리 최종 선정 공지', 'HIGH', '통일할 차트 라이브러리 최종 선정 결과 공지드립니다.\n\n1. 선정 결과\n번들 사이즈·성능·API 학습 난이도를 종합해서 균형이 좋은 쪽으로 확정했습니다.\n\n2. 적용 순서\n다온뱅크 화면부터 먼저 적용하고, 문제없이 안정화되면 다온증권·다온페이 순으로 확대합니다.\n\n3. 일정\n9/12 종료 보고까지 전 서비스 적용을 목표로 합니다.', '2025-07-29 09:00:00', '2025-07-29 09:00:00', NULL),
(171, 33, (SELECT id FROM users WHERE employee_no='DT22-0156'), '공통 래퍼 컴포넌트 설계안', 'MID', '차트 라이브러리 적용 방식 공유드립니다.\n\n1. 왜 래퍼가 필요한가\n각 서비스가 라이브러리 API를 직접 호출하게 두면, 나중에 또 라이브러리를 바꿀 때 이번과 똑같은 문제를 반복하게 됩니다.\n\n2. 설계 방향\n서비스 코드는 래퍼 컴포넌트만 호출하고, 실제 라이브러리 API는 래퍼 내부에만 있게 만듭니다. 라이브러리를 나중에 바꿔도 래퍼만 고치면 됩니다.\n\n3. 지원 차트 유형\n막대·선·파이 3종부터 우선 지원하고, 나머지는 필요할 때 추가하는 방식으로 갑니다.', '2025-08-01 09:00:00', '2025-08-01 09:00:00', NULL),
(172, 33, (SELECT id FROM users WHERE employee_no='DT22-0156'), '1개월 진행 정리', 'MID', '7월 킥오프 이후 진행 상황을 정리했습니다.\n\n1. 라이브러리 선정: 완료\n2. 공통 래퍼 컴포넌트: 1차 완성, 막대·선·파이 3종 지원\n3. 적용: 다온뱅크 화면부터 시작\n\n9월 종료 보고 전까지 전 서비스 적용을 목표로 순조롭게 가고 있습니다.', '2025-08-04 09:00:00', '2025-08-04 09:00:00', NULL),
(173, 33, (SELECT id FROM users WHERE employee_no='DT24-0046'), '라이브러리 교체 중 발견한 성능 이슈', 'HIGH', '8/19 회의에서 보고드린 성능 이슈, 상세 정리했습니다.\n\n1. 재현 조건\n1년치 이상 거래 데이터를 한 번에 그리는 차트(주로 다온뱅크 거래 내역 화면)에서 렌더링이 눈에 띄게 느려졌습니다.\n\n2. 원인\n기존 라이브러리는 대용량 데이터를 자동으로 샘플링해서 그렸는데, 새 라이브러리는 그런 처리가 없어서 전체 데이터를 그대로 그리고 있었습니다.\n\n3. 대응\n일정 개수 이상이면 저희 쪽에서 미리 다운샘플링해서 넘기는 방식으로 처리 중입니다.\n\n다온뱅크 화면 적용 완료 후 결과 다시 공유드리겠습니다.', '2025-08-21 09:00:00', '2025-08-21 09:00:00', NULL),
(174, 33, (SELECT id FROM users WHERE employee_no='DT23-0036'), '공통 차트 컴포넌트 사용법', 'LOW', '차트 라이브러리 통일 거의 마무리돼서, 사용법 간단히 정리해서 공유드립니다.\n\n1. 가져다 쓰는 법\n래퍼 컴포넌트에 데이터와 차트 유형(막대/선/파이)만 넘기면 됩니다. 라이브러리 API를 직접 호출할 필요는 없습니다.\n\n2. 대용량 데이터 주의\n데이터가 많을 때는 미리 다운샘플링된 형태로 넘겨주세요. 안 그러면 렌더링이 느려질 수 있습니다.\n\n궁금한 점 있으면 편하게 물어보세요.', '2025-09-10 09:00:00', '2025-09-10 09:00:00', NULL),
(175, 33, (SELECT id FROM users WHERE employee_no='DT22-0156'), '차트 라이브러리 통일 회고', 'MID', '오늘(9/12) 종료 보고 이후, 돌아보는 글 남깁니다.\n\n1. 잘한 점\n공통 래퍼 컴포넌트를 만들어둔 게 좋은 선택이었습니다. 나중에 라이브러리를 또 바꿔야 할 일이 생겨도 래퍼만 고치면 됩니다.\n\n2. 아쉬운 점\n대용량 데이터 성능 이슈를 선정 단계에서 미리 테스트했으면 8월에 급하게 대응하지 않아도 됐을 것 같습니다. 다음엔 후보 비교할 때 실제 데이터 규모로 테스트해봐야겠습니다.\n\n3. 결과\n전 서비스 차트를 단일 라이브러리로 통일, 공통 래퍼 컴포넌트까지 함께 완성했습니다.', '2025-09-12 16:00:00', '2025-09-12 16:00:00', NULL),
(176, 34, (SELECT id FROM users WHERE employee_no='DT22-0158'), 'jQuery 제거 사례 및 자동화 도구 조사', 'LOW', '전환 계획 참고하려고 관련 사례를 찾아봤습니다.\n\n1. 자동화 도구\njQuery 코드를 자동으로 순수 JS나 최신 프레임워크 문법으로 바꿔주는 마이그레이션 도구가 몇 개 있었는데, 단순 DOM 조작 정도만 커버하고 플러그인 의존 코드는 결국 수작업이 필요했습니다.\n\n2. 참고할 점\n한 번에 다 바꾸기보다, 화면 단위로 하나씩 전환하고 배포하는 방식이 안전하다는 사례가 많았습니다. 저희도 재개하면 이 방식으로 가면 좋을 것 같습니다.\n\n참고 자료는 별도로 정리해서 공유드리겠습니다.', '2025-10-20 09:00:00', '2025-10-20 09:00:00', NULL),
(177, 34, (SELECT id FROM users WHERE employee_no='DT22-0147'), 'jQuery→최신 스택 전환 방안 초안', 'MID', '전환 작업 방안 초안 공유드립니다.\n\n1. 접근 방식\n화면 단위로 하나씩 전환합니다. 한 번에 다 바꾸면 문제 생겼을 때 원인 찾기가 어렵습니다.\n\n2. 우선순위\n플러그인 의존도가 낮은 4개 화면을 먼저 전환하고, 대체재가 필요한 2개는 마지막으로 미룹니다.\n\n3. 검증\n화면별로 전환 후 기존 동작과 비교 테스트를 거칩니다.\n\n대체재 검토가 남은 2개 화면은 별도로 더 봐야 할 것 같습니다.', '2025-10-27 09:00:00', '2025-10-27 09:00:00', NULL),
(178, 34, (SELECT id FROM users WHERE employee_no='DT23-0038'), '플러그인 의존 화면 2개 — 대체재 후보 검토', 'MID', '전환이 까다로운 화면 2개, 대체재 후보 검토 내용입니다.\n\n1. 대상\n날짜 선택기와 이미지 슬라이더에 jQuery 플러그인을 쓰고 있는 화면 2개입니다.\n\n2. 대체재 후보\n둘 다 최신 스택 기준 대체 라이브러리가 있긴 한데, 기존과 옵션(다국어 표시, 커스텀 스타일)이 완전히 같지는 않아서 화면별로 세부 조정이 필요할 것 같습니다.\n\n3. 소요 예상\n두 화면만으로도 2주 정도는 걸릴 것으로 보입니다. 전체 6주 견적 중 상당 부분을 차지합니다.', '2025-10-24 09:00:00', '2025-10-24 09:00:00', NULL),
(179, 34, (SELECT id FROM users WHERE employee_no='DT22-0147'), '전환 규모 산정 근거 상세', 'LOW', '11/3 회의에서 보고드린 6주 견적, 산정 근거 정리했습니다.\n\n1. 단순 전환 (4화면): 화면당 3~4일, 총 2주\n2. 플러그인 대체 (2화면): 화면당 1.5주, 총 3주\n3. 통합 검증: 1주\n\n합쳐서 약 6주입니다. 플러그인 대체 2화면이 절반 가까이 차지합니다.', '2025-10-30 09:00:00', '2025-10-30 09:00:00', NULL),
(180, 34, (SELECT id FROM users WHERE employee_no='DT22-0018'), '우선순위 조정에 따른 보류 결정 공지', 'HIGH', '11/3 회의에서 결정된 보류 관련 공지드립니다.\n\n1. 결정\n레거시 jQuery 코드 제거 작업을 잠정 보류합니다.\n\n2. 이유\n전환 규모가 약 6주로 산정됐는데, 마침 다른 우선순위 작업들이 겹쳐서 이번 분기는 리소스를 배정하기 어렵다고 판단했습니다.\n\n3. 남겨두는 것\n현황 조사, 전환 방안 초안, 규모 산정 자료는 전부 그대로 남겨둡니다. 다음에 재개할 때 이 자료들부터 보시면 바로 이어서 진행하실 수 있습니다.', '2025-11-03 15:00:00', '2025-11-03 15:00:00', NULL),
(181, 34, (SELECT id FROM users WHERE employee_no='DT22-0142'), '보류 시점까지 진행 정리', 'MID', '10월 킥오프 이후 보류 시점까지 진행 상황을 정리했습니다.\n\n1. 현황 조사: 완료 (잔존 화면 6개)\n2. 전환 방안: 초안 완료 (화면 단위 순차 전환)\n3. 규모 산정: 완료 (약 6주)\n4. 착수: 리소스 배정 문제로 보류\n\n조사와 계획 단계까지는 다 끝나 있어서, 리소스만 확보되면 바로 착수할 수 있는 상태입니다.', '2025-11-05 09:00:00', '2025-11-05 09:00:00', NULL),
(182, 34, (SELECT id FROM users WHERE employee_no='DT22-0147'), '재개 시 참고할 인수인계 노트', 'LOW', '이 작업 재개하실 분을 위해 참고 사항 남겨둡니다.\n\n1. 우선 전환 대상\n플러그인 의존도가 낮은 4개 화면부터 시작하시면 됩니다. 상대적으로 빠르게 끝낼 수 있습니다.\n\n2. 까다로운 부분\n날짜 선택기·이미지 슬라이더 화면 2개는 대체재 옵션이 기존과 완전히 같지 않아서, 화면별 세부 조정에 시간이 더 필요합니다.\n\n3. 검증 방식\n화면 단위로 전환 후 기존 동작과 비교 테스트하는 방식을 그대로 따라가시면 됩니다.\n\n궁금한 점 있으면 편하게 물어보세요.', '2025-11-10 09:00:00', '2025-11-10 09:00:00', NULL),
(183, 69, (SELECT id FROM users WHERE employee_no='DT23-0032'), '1차 도구 활용도 저조 원인 분석', 'MID', '2차 고도화 착수 전에, 1차 도구가 왜 안 쓰였는지부터 짚어봤습니다.\n\n1. 사용 로그 확인\n지난 3개월간 접속 로그를 보니, 초기 등록한 몇 팀 외에는 거의 안 쓰이고 있었습니다.\n\n2. 인터뷰 결과\n몇 분께 여쭤보니 "데이터를 손으로 입력해야 하는데, 매번 프로젝트 현황이랑 따로 맞춰 넣는 게 번거롭다"는 의견이 제일 많았습니다.\n\n3. 시사점\n기능이 부족해서가 아니라, 입력 과정 자체가 진입장벽이었던 것 같습니다. 2차 고도화는 이 부분을 우선 겨냥해야 할 것 같습니다.', '2026-01-12 09:00:00', '2026-01-12 09:00:00', NULL),
(184, 69, (SELECT id FROM users WHERE employee_no='DT22-0117'), '사내 도구 활용도 개선 사례 조사', 'LOW', '비슷한 사내 도구 활용도 개선 사례를 찾아봤습니다.\n\n1. 공통 패턴\n수작업 입력을 요구하는 도구는 초반에만 반짝 쓰이다가 금방 방치되는 경우가 많았습니다. 반대로 기존 시스템과 자동 연동되는 도구는 꾸준히 쓰이는 경향이 있었습니다.\n\n2. 시사점\n저희도 프로젝트 관리 시스템과 자동 연동하는 방향이 맞는 것 같습니다. 신우진 선임이 기술적 검토를 진행 중이라고 들었습니다.', '2026-01-15 09:00:00', '2026-01-15 09:00:00', NULL),
(185, 69, (SELECT id FROM users WHERE employee_no='DT22-0123'), '프로젝트 관리 시스템 자동 연동 검토', 'MID', '1/26 회의에서 보고드린 자동 연동 검토 결과, 자세히 정리했습니다.\n\n1. 결론\n기술적으로는 연동 가능합니다. 프로젝트별 인원·기간 데이터를 API로 가져오면 수작업 입력을 없앨 수 있습니다.\n\n2. 소요\n연동 작업에 추가로 3주 정도 더 필요할 것으로 봅니다.\n\n3. 변수\n마침 전사 프로젝트관리 도구(PrettyWorks) 도입이 검토되고 있다는 얘기가 있어서, 이게 확정되면 저희 작업 방향 자체를 다시 봐야 할 수도 있습니다. 확정 여부부터 확인 후 진행하겠습니다.', '2026-01-26 15:00:00', '2026-01-26 15:00:00', NULL),
(186, 69, (SELECT id FROM users WHERE employee_no='DT22-0122'), '1개월 진행 정리', 'MID', '1월 킥오프 이후 진행 상황을 정리했습니다.\n\n1. 원인 분석: 완료 (수작업 입력이 진입장벽)\n2. 개선 방향: 자동 연동으로 결정\n3. 기술 검토: 연동 가능, 3주 추가 소요 예상\n4. 변수: PrettyWorks 도입 검토 소식으로 진행 여부 재확인 중\n\n확정되는 대로 다시 공유드리겠습니다.', '2026-01-22 09:00:00', '2026-01-22 09:00:00', NULL),
(187, 69, (SELECT id FROM users WHERE employee_no='DT22-0122'), 'PrettyWorks 도입 확정에 따른 개발 중단 공지', 'HIGH', '2차 고도화 관련 최종 공지드립니다.\n\n1. 확인 결과\n전사 프로젝트관리 도구(PrettyWorks) 도입이 확정됐습니다.\n\n2. 결정\n저희가 따로 만들던 리소스 배분 도구 고도화는 여기서 개발을 중단하고 보관 처리합니다. 상위 도구가 이미 같은 역할을 대체하게 됩니다.\n\n3. 남기는 것\n지금까지 조사·검토한 자료(활용도 저조 원인, 자동 연동 검토 결과)는 그대로 남겨둡니다. 도구는 사라지지만 조사 내용 자체는 참고할 가치가 있다고 봅니다.', '2026-02-10 09:00:00', '2026-02-10 09:00:00', NULL),
(188, 69, (SELECT id FROM users WHERE employee_no='DT22-0123'), 'PrettyWorks 요구사항 참고용 — 검토 자료 인수인계', 'MID', '저희가 검토했던 자료가 PrettyWorks 쪽 요구사항 정리에 참고가 될 수 있을 것 같아서, 관련 부서에 넘기기 전에 여기 정리해둡니다.\n\n1. 활용도 저조 원인\n수작업 데이터 입력이 진입장벽이었습니다. PrettyWorks는 처음부터 시스템 데이터를 직접 쓰는 구조라 이 문제 자체가 없을 것 같습니다.\n\n2. 자동 연동 검토 결과\n프로젝트별 인원·기간 데이터를 API로 가져오는 방식을 검토했었는데, 이 부분 설계가 PrettyWorks 쪽에도 참고가 될 수 있을 것 같습니다.\n\n필요하시면 상세 자료 공유드리겠습니다.', '2026-02-13 15:00:00', '2026-02-13 15:00:00', NULL),
(189, 69, (SELECT id FROM users WHERE employee_no='DT22-0122'), '2차 고도화 중단 회고', 'MID', '오늘(2/13) 보관 처리 보고 이후, 돌아보는 글 남깁니다.\n\n1. 아쉬운 점\n외부 요인(PrettyWorks 도입)으로 중단된 거라 저희가 뭘 잘못해서는 아니지만, 조금 더 일찍 전사 도구 도입 논의를 파악했으면 자동 연동 검토에 시간을 덜 썼을 것 같습니다.\n\n2. 그래도 남는 것\n활용도 저조 원인 분석과 자동 연동 검토 결과는 PrettyWorks 쪽에 참고 자료로 넘길 수 있게 됐습니다. 헛수고는 아니었다고 생각합니다.\n\n3. 결과\n2차 고도화는 중단됐지만, 조사·검토 자료는 남겨서 상위 도구 설계에 도움이 되도록 인수인계했습니다.', '2026-02-13 17:00:00', '2026-02-13 17:00:00', NULL),
(190, 97, (SELECT id FROM users WHERE employee_no='DT23-0033'), '예산 추적 요구사항 초안 정리', 'MID', '킥오프 이후 요구사항 초안 정리했습니다.\n\n1. 핵심 요구사항\n프로젝트별로 인건비·경비 발생 시점에 예산 소진율을 실시간으로 보여주는 화면입니다.\n\n2. 부가 요구사항\n예산의 80%를 넘으면 PM에게 알림을 보내는 기능도 같이 요청받았습니다.\n\n3. 다음 단계\n이 요구사항을 기준으로 기술적으로 어떻게 구현할지 검토하겠습니다.', '2025-11-10 09:00:00', '2025-11-10 09:00:00', NULL),
(191, 97, (SELECT id FROM users WHERE employee_no='DT22-0018'), '타사 프로젝트 예산 관리 도구 사례', 'LOW', '화면 설계에 참고하려고 몇몇 사례를 찾아봤습니다.\n\n1. 공통 UI 패턴\n예산 대비 소진율을 막대그래프나 게이지 형태로 한눈에 보여주는 화면이 많았습니다.\n\n2. 알림 방식\n임계치(80%, 100%)를 넘을 때만 알림을 보내고, 평소엔 조용히 데이터만 쌓는 방식이 일반적이었습니다.\n\n참고 캡처는 별도로 정리해서 공유드리겠습니다.', '2025-11-17 09:00:00', '2025-11-17 09:00:00', NULL),
(192, 97, (SELECT id FROM users WHERE employee_no='DT23-0033'), '실시간 집계 방식 설계 검토', 'MID', '요구사항 기준으로 구현 방식을 검토했습니다.\n\n1. 접근 방식\n인건비·경비 발생 시점에 바로 해당 프로젝트로 집계되는 구조가 필요합니다.\n\n2. 검토 중 발견한 점\n이 구조, 어디서 많이 본 것 같아서 확인해봤더니 재무팀에서 원가 관리 체계 고도화(92번 프로젝트)로 이미 비슷한 걸 설계하고 있다는 걸 알게 됐습니다. 다음 회의에서 자세히 확인해보겠습니다.', '2025-11-24 09:00:00', '2025-11-24 09:00:00', NULL),
(193, 97, (SELECT id FROM users WHERE employee_no='DT23-0033'), '재무팀 원가관리 체계와의 기능 중복 상세', 'HIGH', '12/8 회의에서 보고드린 중복 관련, 자세히 확인한 내용입니다.\n\n1. 확인 방법\n재무팀 원가 관리 체계 고도화(92번) 프로젝트 설계 문서를 직접 요청해서 봤습니다.\n\n2. 결과\n인건비·경비 발생 시점 실시간 집계, 프로젝트별 소진율 조회 — 저희가 만들려던 것과 핵심 기능이 거의 동일했습니다.\n\n3. 차이점\n저희 쪽은 임계치 알림 기능이 조금 더 있었는데, 이 정도는 92번 쪽에 요청해서 추가하는 게 따로 만드는 것보다 훨씬 효율적이라고 판단됩니다.\n\n재무팀과 협의 후 TF 지속 여부를 결정하겠습니다.', '2025-12-08 15:00:00', '2025-12-08 15:00:00', NULL),
(194, 97, (SELECT id FROM users WHERE employee_no='DT22-0115'), '1개월 진행 정리', 'MID', '11월 킥오프 이후 진행 상황을 정리했습니다.\n\n1. 요구사항 정리: 완료\n2. 구현 방식 검토: 진행 중 재무팀 원가 관리 체계와의 중복 발견\n3. 현재: 재무팀과 협의 중, 중복이면 TF 중단 검토\n\n협의 결과 나오는 대로 다시 공유드리겠습니다.', '2025-11-28 09:00:00', '2025-11-28 09:00:00', NULL),
(195, 97, (SELECT id FROM users WHERE employee_no='DT22-0115'), 'TF 중단 결정 공지', 'HIGH', '예산 추적 도구 도입 TF 관련 최종 공지드립니다.\n\n1. 결정\n재무팀과 협의 결과, 이 TF는 중단하고 원가 관리 체계 고도화(92번) 쪽에 저희가 검토한 임계치 알림 기능을 추가 요청하기로 했습니다.\n\n2. 이유\n같은 기능을 두 팀이 따로 만들 이유가 없고, 재무팀 쪽이 이미 더 진행된 상태였습니다.\n\n3. 정리\n지금까지 정리한 요구사항·설계 검토 자료는 재무팀에 전달합니다.', '2025-12-15 09:00:00', '2025-12-15 09:00:00', NULL),
(196, 97, (SELECT id FROM users WHERE employee_no='DT23-0033'), '정리 자료 재무팀 인수인계 노트', 'LOW', '재무팀에 전달하는 자료, 여기에도 남겨둡니다.\n\n1. 요구사항 문서\nPM 입장에서 필요한 화면·알림 요구사항을 정리해뒀습니다.\n\n2. 임계치 알림 기능\n예산 80% 소진 시 PM에게 알림을 보내는 기능인데, 저희 검토로는 기존 원가 집계 구조에 조건 하나만 추가하면 될 것 같습니다.\n\n궁금한 점 있으면 편하게 물어보세요.', '2025-12-20 15:00:00', '2025-12-20 15:00:00', NULL),
(197, 97, (SELECT id FROM users WHERE employee_no='DT22-0115'), '예산 추적 도구 TF 회고', 'MID', '오늘(12/20) 중단 보고 이후, 돌아보는 글 남깁니다.\n\n1. 아쉬운 점\n착수 전에 재무팀 쪽 진행 상황을 먼저 확인했으면 요구사항 정리에 쓴 3주를 아낄 수 있었을 것 같습니다. 다음엔 비슷한 걸 만들기 전에 다른 팀에 먼저 물어봐야겠습니다.\n\n2. 잘한 점\n중복을 발견했을 때 자존심 세우지 않고 빠르게 중단 결정을 내린 건 맞았다고 봅니다. 계속 밀어붙였으면 두 팀이 같은 기능을 따로 유지보수하는 상황이 됐을 겁니다.\n\n3. 결과\nTF는 중단됐지만, 검토한 요구사항과 임계치 알림 기능은 재무팀 쪽에 그대로 인수인계했습니다.', '2025-12-20 17:00:00', '2025-12-20 17:00:00', NULL),
(198, 16, (SELECT id FROM users WHERE employee_no='DT22-0191'), '레거시 API 정리 프로젝트 회고', 'MID', '이전 시스템에서 넘어온 API가 문서화도 안 된 채 방치돼 있어 유지보수 부담이 컸던 프로젝트가 오늘 종료 보고를 마쳤다. 전체 과정을 되짚어본다.\n\n1. 착수 배경\n임동혁 BE선임이 이전 시스템에서 넘어온 API를 전수 조사한 결과 총 87개였고, 이 중 절반 가까이가 지금도 쓰이는지조차 확실치 않은 상태였다. 사용 로그를 기준으로 저사용 API를 먼저 골라내고, 남는 API는 문서화를 완료하는 것으로 목표를 합의했다.\n\n2. 진행 과정\n폐기 대상으로 판단한 API는 곧바로 지우지 않고, 혹시 몰라 한 달 동안 로그 모니터링을 거쳤다. "진짜 아무도 안 쓰더라고요"라는 확인을 거친 뒤에야 정리를 확정했다.\n\n3. 최종 결과\n87개 중 34개는 실제 미사용으로 확인돼 폐기했고, 나머지 53개는 문서화를 완료했다. 유지보수 대상이 명확해지면서 향후 신규 개발자 온보딩에도 도움이 될 것으로 평가됐다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 프로젝트를 종료한다.', '2024-08-15 15:00:00', '2024-08-15 15:00:00', NULL),
(199, 18, (SELECT id FROM users WHERE employee_no='DT22-0190'), '인증 토큰 정책 개선 프로젝트 회고', 'MID', '서비스마다 제각각이던 토큰 만료 정책을 통일하는 프로젝트가 종료 보고를 마쳤다.\n\n1. 착수 배경\n하유진 BE파트장이 지적한 것처럼, 서비스마다 토큰 만료 시간이 달라 어떤 서비스는 30분마다 재로그인해야 하고 어떤 서비스는 하루 종일 유지되는 등 사용자 입장에서 이해하기 어려운 상황이었다. 만료 정책을 통일하고 갱신 로직을 개선하는 것을 목표로 삼았다.\n\n2. 최종 결과\n전 서비스의 토큰 만료 정책을 액세스 30분 / 리프레시 2주로 통일했고, 자동 갱신 로직도 함께 적용을 완료했다.\n\n3. 효과\n하유진 파트장은 "통일하고 나니 문의도 줄고 코드도 단순해졌습니다"라고 평가했다. 애초 목표했던 정책 통일과 사용자 불편 해소를 모두 달성한 것으로 정리됐다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 프로젝트를 종료한다.', '2024-10-15 15:00:00', '2024-10-15 15:00:00', NULL),
(200, 20, (SELECT id FROM users WHERE employee_no='DT22-0190'), '코드 리뷰 프로세스 개선 TF 회고', 'MID', '파트별로 다르던 코드 리뷰 기준을 표준화하는 TF가 종료 보고를 마쳤다.\n\n1. 착수 배경\n하유진 BE파트장은 "파트마다 리뷰 기준이 달라서, A파트에서는 걸릴 게 B파트에서는 그냥 넘어가고 그럽니다. 품질 편차가 여기서 오는 것 같아요"라고 문제를 짚었다. 공통 체크리스트를 만들어 리뷰 품질을 표준화하는 것이 목표였다.\n\n2. 결과물\n보안·성능·테스트 커버리지 등 12개 항목으로 구성된 공통 체크리스트를 제작해 전 파트에 시범 적용했다.\n\n3. 적용 결과\n시범 적용 결과 리뷰 소요 시간은 다소 늘었지만 반려율은 감소했다. 하유진 파트장은 "당장은 좀 번거로워해도, 결국 재작업이 줄어드는 방향이라 계속 가져가기로 했습니다"라고 밝혔다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 TF를 종료한다.', '2024-11-10 15:00:00', '2024-11-10 15:00:00', NULL),
(201, 22, (SELECT id FROM users WHERE employee_no='DT22-0019'), 'DB 인덱스 정비 프로젝트 회고', 'MID', '쿼리 성능 저하 문제를 해결하기 위한 인덱스 재설계 프로젝트가 종료 보고를 마쳤다.\n\n1. 착수 배경\n서강우 BE팀장은 "서비스가 커지면서 예전엔 안 걸리던 쿼리들이 이제 몇 초씩 걸립니다. 인덱스를 그때그때 땜질식으로 추가해온 게 누적된 결과인 것 같아요"라며 전면 재설계 필요성을 제기했다.\n\n2. 결과\n핵심 테이블 18개의 인덱스를 재설계했고, 느린 쿼리(1초 이상) 비중이 기존 대비 크게 감소했다.\n\n3. 진행 방식\n서강우 팀장은 "인덱스 하나 잘못 걸려 있으면 전체가 밀리는 거라, 이번엔 실행계획까지 다 확인하고 갔습니다"라며 꼼꼼한 검증 과정을 거쳤다고 전했다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 프로젝트를 종료한다.', '2025-04-15 15:00:00', '2025-04-15 15:00:00', NULL),
(202, 23, (SELECT id FROM users WHERE employee_no='DT22-0186'), '그룹 인증 로그 표준화 프로젝트 회고', 'MID', '감사 대응 효율을 높이기 위한 인증 로그 표준화 프로젝트가 종료 보고를 마쳤다.\n\n1. 착수 배경\n임도현 BE선임은 "감사 시즌마다 시스템별로 로그 포맷이 달라서 집계하는 데만 며칠씩 걸립니다. 이번엔 아예 포맷을 통일해버리려고 합니다"라며 배경을 설명했다.\n\n2. 결과\n표준 로그 포맷(JSON 스키마)을 정의하고 전 인증 시스템에 적용을 완료했다.\n\n3. 기대 효과\n임도현 선임은 "다음 감사 때부터는 집계 스크립트 하나로 다 뽑을 수 있을 겁니다"라며 목표 달성을 확인했다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 프로젝트를 종료한다.', '2025-08-15 15:00:00', '2025-08-15 15:00:00', NULL),
(203, 27, (SELECT id FROM users WHERE employee_no='DT22-0188'), '테스트 커버리지 확대 TF 중단 공지', 'HIGH', '핵심 결제·정산 모듈의 테스트 커버리지를 확대하던 TF가 중단됐다. 관련 내용을 공지한다.\n\n1. 착수 배경\n곽하늘 BE사원은 "핵심 결제·정산 모듈 커버리지가 40%도 안 됩니다. 배포할 때마다 다들 불안해하는 게 이해가 갑니다"라며 문제를 제기했고, 우선순위 높은 모듈부터 테스트를 추가하는 것을 목표로 착수했다.\n\n2. 중단 사유\n다온뱅크 여신고도화 프로젝트 쪽으로 인력이 급하게 재배치되면서 TF를 중단하게 됐다.\n\n3. 진행 현황\n중단 시점까지 결제 모듈 커버리지를 40%에서 58%까지 끌어올린 상태다. 계획했던 나머지 모듈에는 손을 대지 못했다.\n\n4. 후속 안내\n곽하늘 사원은 "지금까지 작업한 테스트 코드는 남겨뒀으니 나중에 재개할 수 있을 겁니다"라고 전했다. 재개 시점은 별도 공지 예정이다.', '2025-06-01 15:00:00', '2025-06-01 15:00:00', NULL),
(204, 29, (SELECT id FROM users WHERE employee_no='DT22-0145'), '모바일 반응형 개선 프로젝트 회고', 'MID', '모바일 브라우저 접속 시 레이아웃이 깨지는 문제를 해결한 프로젝트가 종료 보고를 마쳤다.\n\n1. 착수 배경\n최이안 FE선임은 "모바일 브라우저로 들어오면 표가 화면 밖으로 삐져나가거나 버튼이 겹치는 화면이 꽤 있습니다. PC 기준으로만 만들어온 티가 나요"라고 문제를 짚었다.\n\n2. 결과\n주요 화면 20개에 반응형 대응을 적용 완료했다.\n\n3. 남은 과제\n레이아웃 깨짐 문제는 모두 해결했지만, 모바일에서 클릭 영역이 작다는 피드백은 다음 과제로 넘기기로 했다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 프로젝트를 종료한다.', '2024-08-15 15:00:00', '2024-08-15 15:00:00', NULL),
(205, 31, (SELECT id FROM users WHERE employee_no='DT22-0155'), '번들 사이즈 최적화 프로젝트 회고', 'MID', '초기 로딩 속도 개선을 위한 번들 사이즈 최적화 프로젝트가 종료 보고를 마쳤다.\n\n1. 착수 배경\n곽민서 FE선임은 "초기 로딩할 때 안 쓰는 라이브러리까지 다 같이 불러오고 있었습니다. 번들 분석 도구로 찍어보니 생각보다 덩치 큰 게 많더라고요"라며 착수 배경을 설명했다.\n\n2. 결과\n코드 스플리팅과 미사용 의존성 제거를 통해 초기 번들 사이즈를 절반 가까이 줄였다.\n\n3. 효과\n곽민서 선임은 "체감상 초기 로딩이 확실히 빨라졌다는 얘기를 들었습니다"라고 전했다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 프로젝트를 종료한다.', '2025-03-14 15:00:00', '2025-03-14 15:00:00', NULL),
(206, 32, (SELECT id FROM users WHERE employee_no='DT22-0144'), '다크모드 지원 프로젝트 회고', 'MID', '야간 근무자의 눈 피로를 줄이기 위한 다크모드 지원 프로젝트가 종료 보고를 마쳤다.\n\n1. 착수 배경\n배준호 FE파트장은 "야간 근무하는 분들이 화면이 너무 밝아서 눈 아프다는 얘기를 종종 하시더라고요. 사내 시스템에 다크모드가 없다는 게 계속 걸렸습니다"라며 착수 배경을 설명했다.\n\n2. 결과\n컬러 토큰 체계를 재정비해 전 화면에 다크모드 적용을 완료했다.\n\n3. 기대 효과\n배준호 파트장은 "토큰 기반으로 만들어놔서 나중에 테마 추가할 때도 어렵지 않을 겁니다"라며 확장성을 강조했다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 프로젝트를 종료한다.', '2025-06-13 15:00:00', '2025-06-13 15:00:00', NULL),
(207, 35, (SELECT id FROM users WHERE employee_no='DT22-0144'), '접근성 감사 잔여 화면 개선 프로젝트 회고', 'MID', '1차 개선 이후에도 남아 있던 접근성 이슈를 마무리한 프로젝트가 종료 보고를 마쳤다.\n\n1. 착수 배경\n배준호 FE파트장은 "1차 때 놓쳤던 부분들이 이번 감사에서 다시 지적됐습니다. 특히 폼 입력 오류 안내 쪽이요"라며 착수 배경을 설명했다. 남은 화면까지 접근성 기준을 완전히 충족시키는 것이 목표였다.\n\n2. 결과\n1차에서 미흡했던 폼 오류 안내, 포커스 이동 등을 포함해 전 화면이 WCAG AA 기준을 충족하도록 개선을 완료했다.\n\n3. 검증 방식\n배준호 파트장은 "이번엔 감사팀이랑 같이 재점검까지 받고 마무리했습니다"라고 전했다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 프로젝트를 종료한다.', '2026-05-15 15:00:00', '2026-05-15 15:00:00', NULL),
(208, 36, (SELECT id FROM users WHERE employee_no='DT22-0127'), '테스트 자동화 도입 TF 회고', 'MID', '릴리즈마다 반복되던 수작업 회귀 테스트를 자동화한 TF가 종료 보고를 마쳤다.\n\n1. 착수 배경\n문가온 QA파트장은 "회귀 테스트를 릴리즈마다 사람이 손으로 다 돌리고 있습니다. 릴리즈 하나에 이틀씩 걸리는데, 정작 새로 짠 기능 테스트할 시간은 줄어드는 구조예요"라고 문제를 짚었다.\n\n2. 결과\n핵심 시나리오 40건에 대한 자동화를 완료했고, 회귀 테스트 소요 시간을 이틀에서 반나절로 단축했다.\n\n3. 효과\n문가온 파트장은 "완전 자동화는 아니지만, 사람이 봐야 할 부분에 집중할 시간이 생긴 게 제일 큽니다"라고 평가했다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 TF를 종료한다.', '2024-07-12 15:00:00', '2024-07-12 15:00:00', NULL),
(209, 37, (SELECT id FROM users WHERE employee_no='DT22-0020'), '버그 트래킹 프로세스 정비 프로젝트 회고', 'MID', '버그 리포트 품질 문제를 해결하기 위한 프로세스 정비 프로젝트가 종료 보고를 마쳤다.\n\n1. 착수 배경\n정미르 QA팀장은 "버그 리포트에 재현 조건이 부실하면 개발팀이랑 왔다갔다하는 데만 시간이 다 갑니다. 템플릿을 표준화해서 그 왕복을 줄이려고 합니다"라며 착수 배경을 설명했다.\n\n2. 결과\n재현 조건·환경·기대 결과를 필수 항목으로 담은 표준 버그 리포트 템플릿 도입을 완료했다.\n\n3. 효과\n정미르 팀장은 "재현이 안 돼서 반려되는 케이스가 눈에 띄게 줄었습니다"라고 전했다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 프로젝트를 종료한다.', '2024-10-11 15:00:00', '2024-10-11 15:00:00', NULL),
(210, 39, (SELECT id FROM users WHERE employee_no='DT22-0128'), 'QA 온보딩 가이드 제작 프로젝트 회고', 'MID', '신입 QA의 적응 기간을 줄이기 위한 온보딩 가이드 제작 프로젝트가 종료 보고를 마쳤다.\n\n1. 착수 배경\n하승우 QA파트장은 "신입 QA가 프로젝트마다 다른 컨벤션을 파악하는 데 몇 주씩 걸립니다. 문서 하나로 정리해두면 훨씬 빨라질 겁니다"라며 착수 배경을 설명했다.\n\n2. 결과\n프로젝트별 테스트 컨벤션과 툴 사용법을 담은 온보딩 가이드를 완성했다.\n\n3. 적용 계획\n하승우 파트장은 "다음 신입부터 바로 적용해볼 예정입니다"라고 밝혔다.\n\n4. 마무리\n산출물 정리 및 공유를 끝으로 프로젝트를 종료한다.', '2025-07-11 15:00:00', '2025-07-11 15:00:00', NULL),
(211, 41, (SELECT id FROM users WHERE employee_no='DT22-0127'), 'QA 회귀 테스트 자동화 확대 회고', 'MID', '1. 프로젝트 배경\n1차 자동화 이후에도 수작업 비중이 여전히 높다는 지적이 있어, 회귀 테스트 자동화 비율을 추가로 끌어올리는 것을 목표로 시작했다.\n\n2. 진행 결과\n회귀 테스트 자동화 비율을 1차 대비 크게 끌어올렸다. 자동화 대상 케이스를 넓혀 반복 실행 부담을 줄였다.\n\n3. 소감\n문가온 QA파트장은 "완전 자동화까지는 아직 멀었지만, 사람이 매번 반복해야 했던 지루한 케이스들은 많이 덜었습니다"라고 정리했다.', '2026-04-16 15:00:00', '2026-04-16 15:00:00', NULL),
(212, 44, (SELECT id FROM users WHERE employee_no='DT22-0047'), '유휴 클라우드 리소스 비용 절감 회고', 'MID', '1. 프로젝트 배경\n쓰지 않는 인스턴스가 계속 떠 있다는 지적이 이어져, 유휴 리소스를 정리해 비용을 절감하는 것을 목표로 전수 점검에 나섰다.\n\n2. 진행 결과\n미사용 인스턴스·볼륨 정리와 인스턴스 사이징 재조정을 완료해 월 클라우드 비용을 유의미하게 절감했다.\n\n3. 소감\n하준서 DevOps파트장은 "생각보다 안 쓰는 게 많았습니다. 정기 점검 주기를 두는 걸로 재발을 막으려고 합니다"라고 밝혔다.', '2025-03-14 15:00:00', '2025-03-14 15:00:00', NULL),
(213, 46, (SELECT id FROM users WHERE employee_no='DT22-0057'), '장애 알림 채널 통합 회고', 'MID', '1. 프로젝트 배경\n장애 알림이 슬랙, 이메일, 문자로 흩어져 있어 급할 때 어디를 봐야 할지 헷갈린다는 문제 제기로 시작됐다. 알림을 한 채널로 통합해 대응 속도를 높이는 것이 목표였다.\n\n2. 진행 결과\n전체 알림을 단일 대시보드·슬랙 채널로 통합 완료했다.\n\n3. 소감\n안도훈 DevOps선임은 "이제 한 곳만 보면 되니까 초기 대응이 확실히 빨라졌습니다"라고 전했다.', '2026-01-16 15:00:00', '2026-01-16 15:00:00', NULL),
(214, 48, (SELECT id FROM users WHERE employee_no='DT22-0065'), '네트워크 회선 이중화 점검 회고', 'MID', '1. 프로젝트 배경\n이중화됐다고 알려진 구간이 실제로 물리적으로 분리돼 있는지 서류상으로만 확인된 경우가 있을 수 있다는 우려로 전수 점검을 시작했다.\n\n2. 진행 결과\n전수 점검 결과 2개 구간에서 물리 경로 미분리를 확인했고, 즉시 보완을 완료했다.\n\n3. 소감\n서인호 인프라파트장은 "다행히 큰 구간은 아니었지만, 점검 안 했으면 몰랐을 부분입니다"라고 말했다.', '2024-06-14 15:00:00', '2024-06-14 15:00:00', NULL),
(215, 49, (SELECT id FROM users WHERE employee_no='DT22-0058'), '서버 자산 관리 체계 정비 회고', 'MID', '1. 프로젝트 배경\n자산대장을 보고 찾아갔는데 실제로는 다른 장비가 꽂혀 있는 경우가 몇 차례 있어, 실사를 통해 대장을 실제와 맞추는 것을 목표로 시작했다.\n\n2. 진행 결과\n서버 자산 전수 실사를 완료했고, 대장과 실물이 불일치하는 22건을 정정했다.\n\n3. 소감\n지동원 인프라파트장은 "이제 대장 보고 찾아가면 실제로 그 자리에 있을 겁니다"라고 정리했다.', '2024-09-13 15:00:00', '2024-09-13 15:00:00', NULL),
(216, 51, (SELECT id FROM users WHERE employee_no='DT22-0065'), '전력 계통 정기 점검 회고', 'MID', '1. 프로젝트 배경\n전력 설비 노후화가 진행 중이어서 사전 점검 없이 가다가는 갑자기 문제가 생길 수 있다는 우려로 정기 점검을 시작했다.\n\n2. 진행 결과\n전력 설비 전수 점검을 완료했고, 경미하게 노후된 부품 3건을 교체했다.\n\n3. 소감\n서인호 인프라파트장은 "큰 이상은 없었지만, 이런 건 미리 보는 게 마음이 편합니다"라고 말했다.', '2025-06-13 15:00:00', '2025-06-13 15:00:00', NULL),
(217, 52, (SELECT id FROM users WHERE employee_no='DT22-0072'), 'IDC 온도·습도 모니터링 고도화 회고', 'MID', '1. 프로젝트 배경\n기존 센서로는 이상 징후를 늦게 감지해, 온도가 이미 많이 오른 다음에야 알림이 오는 문제가 있었다. 센서 추가와 임계치 알림 정교화를 목표로 시작했다.\n\n2. 진행 결과\n구역별 센서를 추가하고 단계별 임계치 알림 체계 구축을 완료했다.\n\n3. 소감\n배현정 인프라파트장은 "이제 이상 징후를 훨씬 이른 단계에서 잡을 수 있습니다"라고 밝혔다.', '2025-11-14 15:00:00', '2025-11-14 15:00:00', NULL),
(218, 53, (SELECT id FROM users WHERE employee_no='DT22-0058'), '재해복구 모의훈련 재검증 회고', 'MID', '1. 프로젝트 배경\n1차 훈련에서 발견된 병목을 보완했는지 실제로 개선됐는지 재검증할 필요가 있어, 개선된 절차로 2차 모의 훈련을 진행했다.\n\n2. 진행 결과\n2차 훈련 결과 절차 소요 시간이 1차 대비 크게 단축돼 목표 시간 이내 달성을 확인했다.\n\n3. 소감\n지동원 인프라파트장은 "이번엔 문서 기준을 실제로 만족시켰습니다"라고 전했다.', '2026-05-15 15:00:00', '2026-05-15 15:00:00', NULL),
(219, 54, (SELECT id FROM users WHERE employee_no='DT22-0103'), '그룹사 데이터 표준 용어집 구축 회고', 'MID', '1. 프로젝트 배경\n부서마다 같은 지표를 다른 용어로 불러 회의할 때마다 서로 다른 이야기를 하고 있었다는 문제 인식에서 시작됐다. 표준 용어집을 만들어 커뮤니케이션 혼선을 줄이는 것이 목표였다.\n\n2. 진행 결과\n핵심 지표 120개에 대한 표준 용어집을 완성해 부서별로 배포 완료했다.\n\n3. 소감\n백서윤 데이터파트장은 "당장 모든 문서를 바꾸긴 어렵지만, 앞으로 새로 쓰는 문서부터는 이 기준을 따르기로 했습니다"라고 정리했다.', '2024-07-12 15:00:00', '2024-07-12 15:00:00', NULL),
(220, 55, (SELECT id FROM users WHERE employee_no='DT22-0104'), '데이터 파이프라인 모니터링 고도화 회고', 'MID', '1. 프로젝트 배경\n파이프라인이 새벽에 실패해도 다음 날 리포트가 이상하다는 걸 보고서야 알아채는 문제가 있었다. 실시간 모니터링 도입이 목표였다.\n\n2. 진행 결과\n파이프라인 실패 시 즉시 알림이 가도록 모니터링 체계 구축을 완료했다.\n\n3. 소감\n정하람 데이터선임은 "이제 문제를 다음 날이 아니라 그날 새벽에 알 수 있습니다"라고 전했다.', '2024-11-15 15:00:00', '2024-11-15 15:00:00', NULL),
(221, 56, (SELECT id FROM users WHERE employee_no='DT22-0104'), '그룹사 정기 리포트 자동 취합 회고', 'MID', '1. 프로젝트 배경\n매달 정기 리포트를 취합하는 데만 며칠씩 걸리고, 각 시스템에서 데이터를 뽑아 엑셀로 합치는 작업을 사람이 반복하고 있었다. 자동 취합 체계 구축이 목표였다.\n\n2. 진행 결과\n핵심 정기 리포트 6종에 대한 자동 취합 체계 구축을 완료했다.\n\n3. 소감\n정하람 데이터선임은 "며칠 걸리던 작업이 이제 새벽 배치 하나로 끝납니다"라고 말했다.', '2025-04-18 15:00:00', '2025-04-18 15:00:00', NULL),
(222, 57, (SELECT id FROM users WHERE employee_no='DT22-0102'), '데이터 거버넌스 정책 수립 회고', 'MID', '1. 프로젝트 배경\n누가 어떤 데이터에 접근할 수 있는지 기준이 명확하지 않아, 요청이 오면 그때그때 열어주는 식으로 운영되고 있었다. 접근 권한 정책 문서화가 목표였다.\n\n2. 진행 결과\n데이터 등급별 접근 권한 정책을 문서화하고 승인 체계 수립을 완료했다.\n\n3. 소감\n김태율 데이터파트장은 "이제 최소한 누가 왜 접근하는지는 추적할 수 있습니다"라고 정리했다.', '2025-08-15 15:00:00', '2025-08-15 15:00:00', NULL),
(223, 59, (SELECT id FROM users WHERE employee_no='DT22-0102'), '데이터 품질 점검 자동화 회고', 'MID', '1. 프로젝트 배경\n품질 이슈를 리포트 배포 후에야 발견하는 경우가 있어, 사전에 걸러낼 검증 로직이 필요하다는 문제의식에서 시작됐다.\n\n2. 진행 결과\n배포 전 자동 검증 로직(결측치·이상치 탐지)을 적용 완료했다.\n\n3. 소감\n김태율 데이터파트장은 "이제 배포 전에 한 번 걸러지니까 사고 확률이 줄었습니다"라고 밝혔다.', '2026-03-13 15:00:00', '2026-03-13 15:00:00', NULL),
(224, 60, (SELECT id FROM users WHERE employee_no='DT22-0024'), '접근권한 재정비 TF 회고', 'MID', '접근권한 재정비 TF를 마무리하며 진행 경과를 정리한다.\n\n1. 착수 배경\n퇴사자 계정 중 권한이 제때 회수되지 않은 사례가 발견됐고, 부서이동자에게는 이전 부서 권한이 그대로 남아있는 경우도 있었다. 권한 부여·회수 프로세스를 재정비하는 것이 목표였다.\n\n2. 진행 결과\n미회수 상태로 남아있던 권한을 전량 정리했다. 이후 퇴사·부서이동이 발생하면 권한이 자동으로 회수되는 프로세스를 구축해 담당자가 수기로 챙기지 않아도 되게 만들었다.\n\n3. 류경호 보안팀장 코멘트\n"이제 사람이 깜빡해서 놓치는 일은 없을 겁니다."\n\n4. 마무리\n산출물 정리 및 공유로 TF를 종료한다.', '2024-06-14 15:00:00', '2024-06-14 15:00:00', NULL),
(225, 61, (SELECT id FROM users WHERE employee_no='DT23-0011'), '취약점 점검 자동화 회고', 'MID', '취약점 점검 자동화 프로젝트를 마무리하며 결과를 공유한다.\n\n1. 착수 배경\n수동 취약점 점검으로는 신규 배포가 잦은 상황에서 대응 속도를 따라가지 못했다. 배포될 때마다 자동으로 스캔이 도는 체계가 필요하다는 문제의식에서 시작했다.\n\n2. 진행 결과\nCI 파이프라인에 자동 취약점 스캔을 연동해 정기 스캔 자동화를 완료했다.\n\n3. 구자헌 보안선임 코멘트\n"배포 시점마다 자동으로 도는 거라 점검 주기가 확 짧아졌습니다."\n\n4. 마무리\n산출물 정리 및 공유로 프로젝트를 종료한다.', '2024-11-15 15:00:00', '2024-11-15 15:00:00', NULL),
(226, 63, (SELECT id FROM users WHERE employee_no='DT22-0024'), '모의해킹 대응 회고', 'MID', '모의해킹 대응 프로젝트를 마무리하며 결과를 공유한다.\n\n1. 착수 배경\n연례 모의해킹에서 지적된 항목들을 미루지 않고 바로 조치한 뒤 재검증까지 받는 것이 목표였다.\n\n2. 진행 결과\n지적 항목을 전량 조치 완료했고, 재검증에서도 통과 결과를 확인했다.\n\n3. 류경호 보안팀장 코멘트\n"지적된 건 다 막았고, 재검증까지 깔끔하게 나왔습니다."\n\n4. 마무리\n산출물 정리 및 공유로 프로젝트를 종료한다.', '2025-08-15 15:00:00', '2025-08-15 15:00:00', NULL),
(227, 64, (SELECT id FROM users WHERE employee_no='DT22-0024'), 'ISMS-P 사전 점검 TF 회고', 'MID', 'ISMS-P 사전 점검 TF를 마무리하며 결과를 공유한다.\n\n1. 착수 배경\n정식 인증 갱신 심사 전에 내부적으로 미비점을 먼저 걸러내기 위해 착수했다. 갱신 심사 대응팀과는 별개로 사전 점검을 먼저 돌리는 방식으로 진행했다.\n\n2. 진행 결과\n사전 점검 결과 경미한 항목 위주로 확인됐고, 본 심사 대응팀에 결과를 인계 완료했다.\n\n3. 류경호 보안팀장 코멘트\n"이 정도면 본 심사 때 큰 무리는 없을 겁니다."\n\n4. 마무리\n산출물 정리 및 공유로 TF를 종료한다.', '2026-06-12 15:00:00', '2026-06-12 15:00:00', NULL),
(228, 65, (SELECT id FROM users WHERE employee_no='DT22-0116'), '프로젝트 리소스 배분 도구 도입 회고', 'MID', '프로젝트 리소스 배분 도구 도입을 마무리하며 결과를 공유한다.\n\n1. 착수 배경\n여러 프로젝트에 걸쳐 있는 인력의 리소스 현황을 엑셀로만 관리하다 보니 누가 얼마나 여유가 있는지 한눈에 파악하기 어려웠다. 배분 현황을 시각화하는 도구 도입이 목표였다.\n\n2. 진행 결과\n리소스 배분 현황을 시각화하는 대시보드 도입을 완료했다.\n\n3. 정소율 PM실 선임 코멘트\n"PM들끼리 신규 프로젝트 인력 배정 얘기할 때 이 화면 하나 띄워놓고 얘기하면 됩니다."\n\n4. 마무리\n산출물 정리 및 공유로 프로젝트를 종료한다.', '2024-06-14 15:00:00', '2024-06-14 15:00:00', NULL),
(229, 66, (SELECT id FROM users WHERE employee_no='DT22-0121'), 'PM 온보딩 가이드 제작 회고', 'MID', 'PM 온보딩 가이드 제작을 마무리하며 결과를 공유한다.\n\n1. 착수 배경\n신규 PM이 사내 프로젝트 관행과 보고 라인을 파악하는 데 시간이 오래 걸린다는 문제의식에서 시작했다.\n\n2. 진행 결과\n프로젝트 착수부터 종료까지 단계별 체크리스트를 담은 온보딩 가이드를 완성했다.\n\n3. 최한결 PM실 선임 코멘트\n"다음 신규 PM분들한테 바로 드릴 수 있게 됐습니다."\n\n4. 마무리\n산출물 정리 및 공유로 프로젝트를 종료한다.', '2024-10-11 15:00:00', '2024-10-11 15:00:00', NULL),
(230, 67, (SELECT id FROM users WHERE employee_no='DT22-0123'), '대외 프로젝트 계약 관리 표준화 회고', 'MID', '대외 프로젝트 계약 관리 표준화를 마무리하며 결과를 공유한다.\n\n1. 착수 배경\n계약 조건 변경 이력을 담당자마다 다르게 관리하고 있어 담당자가 바뀌면 이력 추적이 어려운 문제가 있었다. 표준 양식 도입으로 관리 일관성을 확보하는 것이 목표였다.\n\n2. 진행 결과\n계약 변경 이력 표준 양식을 도입해 전 대외 프로젝트에 적용 완료했다.\n\n3. 신우진 PM실 선임 코멘트\n"담당자가 바뀌어도 이제 이력은 그대로 남습니다."\n\n4. 마무리\n산출물 정리 및 공유로 프로젝트를 종료한다.', '2025-04-11 15:00:00', '2025-04-11 15:00:00', NULL),
(231, 68, (SELECT id FROM users WHERE employee_no='DT22-0121'), '프로젝트 정기 보고 템플릿 개선 회고', 'MID', '프로젝트 정기 보고 템플릿 개선을 마무리하며 결과를 공유한다.\n\n1. 착수 배경\n프로젝트마다 보고 형식이 달라 경영진 보고 취합에 반나절이 걸리는 문제가 있었다. 공통 템플릿으로 통일해 취합 효율을 높이는 것이 목표였다.\n\n2. 진행 결과\n공통 정기 보고 템플릿을 도입해 전 프로젝트에 적용 완료했다.\n\n3. 최한결 PM실 선임 코멘트\n"이제 취합이 한 시간이면 끝납니다."\n\n4. 마무리\n산출물 정리 및 공유로 프로젝트를 종료한다.', '2025-09-12 15:00:00', '2025-09-12 15:00:00', NULL),
(232, 70, (SELECT id FROM users WHERE employee_no='DT22-0095'), '제안서 템플릿 표준화 회고', 'MID', '제안서 템플릿 표준화를 마무리하며 결과를 공유한다.\n\n1. 착수 배경\n제안서마다 구성과 톤이 작성자에 따라 제각각이라 품질 편차가 있었다. 표준 템플릿 제작으로 품질 편차를 줄이는 것이 목표였다.\n\n2. 진행 결과\n섹션별 표준 구성과 톤앤매너 가이드를 담은 제안서 템플릿을 완성했다.\n\n3. 권도영 컨설팅선임 코멘트\n"이제 급하게 제안서 써야 할 때도 최소한의 품질은 보장됩니다."\n\n4. 마무리\n산출물 정리 및 공유로 프로젝트를 종료한다.', '2024-06-14 15:00:00', '2024-06-14 15:00:00', NULL),
(233, 71, (SELECT id FROM users WHERE employee_no='DT22-0094'), '금융권 규제 동향 스터디 회고', 'MID', '금융권 규제 동향 스터디를 마무리하며 결과를 공유한다.\n\n1. 착수 배경\n규제 동향 파악이 개인 역량에 의존해 담당자에 따라 대응력 편차가 컸다. 정기 스터디 체계를 만들어 팀 전체 대응력을 높이는 것이 목표였다.\n\n2. 진행 결과\n월 1회 정기 스터디 체계가 정착됐고, 규제 변경 사항 공유 문서화도 완료했다.\n\n3. 석민규 컨설팅파트장 코멘트\n"이제 새로운 규제 나오면 팀 전체가 거의 동시에 알게 됩니다."\n\n4. 마무리\n산출물 정리 및 공유로 프로젝트를 종료한다.', '2024-09-12 15:00:00', '2024-09-12 15:00:00', NULL),
(234, 72, (SELECT id FROM users WHERE employee_no='DT22-0016'), '대외 상주 인력 지원 체계 정비 회고', 'MID', '대외 상주 인력 지원 체계 정비를 마무리하며 결과를 공유한다.\n\n1. 착수 배경\n상주 인력이 본사 지원을 받기까지 시간이 걸린다는 불만이 계속 제기됐다. 전담 지원 채널을 만들어 응답 속도를 높이는 것이 목표였다.\n\n2. 진행 결과\n상주 인력 전담 지원 채널을 개설했고, 평균 응답 시간이 단축된 것을 확인했다.\n\n3. 안세희 컨설팅팀장 코멘트\n"이제 현장에서 급한 요청이 와도 바로 대응할 수 있습니다."\n\n4. 마무리\n산출물 정리 및 공유로 프로젝트를 종료한다.', '2025-03-14 15:00:00', '2025-03-14 15:00:00', NULL),
(235, 74, (SELECT id FROM users WHERE employee_no='DT22-0093'), '저축은행권 영업 자료 리뉴얼 회고', 'MID', '저축은행권 영업 자료 리뉴얼을 마무리하며 결과를 공유한다.\n\n1. 착수 배경\n기존 영업 자료가 몇 년 전 레퍼런스로만 채워져 있어 최신 사업 실적을 반영하지 못하고 있었다. 최신 레퍼런스를 반영해 자료를 갱신하는 것이 목표였다.\n\n2. 진행 결과\n서일캐피탈 등 최근 진행한 프로젝트 사례를 반영해 영업 자료 갱신을 완료했다.\n\n3. 편도현 컨설팅파트장 코멘트\n"이제 미팅 나갈 때 자신 있게 보여드릴 자료가 생겼습니다."\n\n4. 마무리\n산출물 정리 및 공유로 프로젝트를 종료한다.', '2025-11-14 15:00:00', '2025-11-14 15:00:00', NULL),
(236, 75, (SELECT id FROM users WHERE employee_no='DT22-0092'), '대외 프로젝트 리스크 관리 체계 수립 중단 공지', 'HIGH', '대외 프로젝트 리스크 관리 체계 수립을 중단하게 되어 경과를 공지한다.\n\n1. 착수 배경\n프로젝트별로 리스크를 조기에 식별할 체계가 없어 문제가 커진 다음에야 알게 되는 경우가 있었다. 리스크 조기 식별 체계를 구축하는 것이 목표였다.\n\n2. 중단 사유\n담당하기로 했던 인력에 공백이 생기면서 착수 직후 진행이 멈췄다.\n\n3. 석다연 컨설팅파트장 코멘트\n"프레임 초안까지는 나와 있으니, 인력 여유가 생기면 이어서 진행할 수 있을 겁니다."\n\n4. 향후 계획\n현재까지 나온 산출물은 정리해 공유하고, 추후 인력 상황을 봐서 재개 여부를 검토한다.', '2026-03-13 15:00:00', '2026-03-13 15:00:00', NULL),
(237, 76, (SELECT id FROM users WHERE employee_no='DT22-0084'), '그룹사 영업 채널 데이터 정리 프로젝트 회고', 'MID', '그룹사 영업 채널 데이터 정리 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n봉현석 영업파트장은 킥오프에서 "그룹사별 담당자 연락 이력이 각자 수첩이랑 메일함에만 있습니다. 담당자 바뀌면 인수인계가 거의 안 되는 수준이에요."라고 문제를 짚었습니다. 데이터를 한곳에 정리해 인수인계 부담을 줄이는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 봉현석 영업파트장은 그룹사별 담당자·이력을 공용 시스템으로 이관 완료했다고 밝혔습니다. "이제 담당자가 바뀌어도 이전 이력을 바로 볼 수 있습니다."라는 소감처럼, 애초 목표였던 인수인계 부담 경감이 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2024-06-14 15:00:00', '2024-06-14 15:00:00', NULL),
(238, 77, (SELECT id FROM users WHERE employee_no='DT22-0014'), '대외 영업 파이프라인 관리 체계 도입 회고', 'MID', '대외 영업 파이프라인 관리 체계 도입 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n황보람 영업팀장은 킥오프에서 "영업 기회가 지금 어느 단계인지 공유할 도구가 없어서, 저도 팀원들한테 물어봐야 알 수 있습니다."라고 문제를 짚었습니다. 파이프라인 관리 체계 도입으로 가시성을 확보하는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 황보람 영업팀장은 영업 기회 단계별 관리 도구 도입을 완료했다고 밝혔습니다. "이제 대시보드 한 번 보면 전체 현황이 파악됩니다."라는 소감처럼, 애초 목표였던 가시성 확보가 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2024-12-13 15:00:00', '2024-12-13 15:00:00', NULL),
(239, 78, (SELECT id FROM users WHERE employee_no='DT22-0089'), '그룹사 계약 갱신 프로세스 정비 회고', 'MID', '그룹사 계약 갱신 프로세스 정비 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n도영재 영업선임은 킥오프에서 "계약 갱신 시점을 놓쳐서 뒤늦게 부랴부랴 대응한 적이 있습니다. 미리 알림 받을 체계가 필요합니다."라고 문제를 짚었습니다. 갱신 일정을 사전에 관리하는 체계를 만드는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 도영재 영업선임은 계약 만료 60일 전 자동 알림 체계 구축을 완료했다고 밝혔습니다. "이제 갱신 시점을 놓칠 일은 없을 겁니다."라는 소감처럼, 애초 목표였던 사전 관리 체계 구축이 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2025-06-13 15:00:00', '2025-06-13 15:00:00', NULL),
(240, 80, (SELECT id FROM users WHERE employee_no='DT22-0015'), '신규 상품 타당성 검토 TF 회고', 'MID', '신규 상품 타당성 검토 TF가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n노진우 사업기획팀장은 킥오프에서 "신규 상품 아이디어가 나올 때마다 사업성 검토가 담당자 감으로 이뤄집니다. 체계적인 검증 프레임이 필요합니다."라고 문제를 짚었습니다. 타당성 검토 프레임을 만들어 의사결정을 지원하는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 노진우 사업기획팀장은 시장성·수익성·리스크 3개 축의 타당성 검토 프레임을 완성했다고 밝혔습니다. "이제 신규 아이디어 나오면 이 틀로 먼저 걸러볼 수 있습니다."라는 소감처럼, 애초 목표였던 검증 프레임 구축이 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2024-07-12 15:00:00', '2024-07-12 15:00:00', NULL),
(241, 81, (SELECT id FROM users WHERE employee_no='DT22-0081'), '사업계획 수립 프로세스 개선 회고', 'MID', '사업계획 수립 프로세스 개선 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n위성현 사업기획파트장은 킥오프에서 "연간 사업계획을 부서마다 다른 양식, 다른 일정으로 올리다 보니 취합이 늦어집니다."라고 문제를 짚었습니다. 공통 프로세스를 정립해 취합 효율을 높이는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 위성현 사업기획파트장은 공통 양식과 표준 일정을 확정해 전 부서 배포를 완료했다고 밝혔습니다. "다음 사업계획 시즌부터 바로 적용됩니다."라는 소감처럼, 애초 목표였던 취합 효율 제고가 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2024-12-13 15:00:00', '2024-12-13 15:00:00', NULL),
(242, 83, (SELECT id FROM users WHERE employee_no='DT22-0082'), '경쟁사 벤치마킹 리포트 프로젝트 회고', 'MID', '경쟁사 벤치마킹 리포트 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n최재훈 사업기획선임은 킥오프에서 "경쟁 금융 IT 자회사들 동향을 정기적으로 파악할 필요가 있다는 얘기가 계속 나왔습니다. 이번에 리포트로 정리해보려고 합니다."라고 배경을 설명했습니다. 벤치마킹 리포트를 작성해 전략 수립에 참고하는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 최재훈 사업기획선임은 주요 경쟁사 3곳 동향 및 시사점 정리를 완료했다고 밝혔습니다. "전략 수립할 때 참고 자료로 바로 쓸 수 있게 정리했습니다."라는 소감처럼, 애초 목표였던 리포트 작성이 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2026-02-13 15:00:00', '2026-02-13 15:00:00', NULL),
(243, 84, (SELECT id FROM users WHERE employee_no='DT22-0027'), '사내 규정집 전면 개정 회고', 'MID', '사내 규정집 전면 개정 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n이서준 경영지원파트장은 킥오프에서 "조직이 커지면서 기존 규정이 실제 운영이랑 안 맞는 부분이 늘었습니다. 예를 들면 결재 라인이 규정이랑 실제가 다른 경우도 있어요."라고 문제를 짚었습니다. 규정을 현행화해 실무 혼선을 줄이는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 이서준 경영지원파트장은 전 규정 현행화 및 실제 운영 기준 반영을 완료했다고 밝혔습니다. "이제 규정 찾아봐서 헷갈리는 일은 줄어들 겁니다."라는 소감처럼, 애초 목표였던 실무 혼선 감소가 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2024-07-12 15:00:00', '2024-07-12 15:00:00', NULL),
(244, 85, (SELECT id FROM users WHERE employee_no='DT22-0011'), '총무 자산 관리 시스템 정비 회고', 'MID', '총무 자산 관리 시스템 정비 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n신동렬 경영지원팀장은 킥오프에서 "사무기기, 비품 관리가 아직도 수기 대장입니다. 분실되거나 정리 안 된 항목이 꽤 있을 겁니다."라고 문제를 짚었습니다. 관리 체계를 정비해 자산 파악을 정확하게 하는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 신동렬 경영지원팀장은 전산 자산 관리 시스템 도입 및 전수 실사를 완료했다고 밝혔습니다. "이제 뭐가 어디 있는지 시스템으로 바로 조회됩니다."라는 소감처럼, 애초 목표였던 정확한 자산 파악이 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2024-11-15 15:00:00', '2024-11-15 15:00:00', NULL),
(245, 87, (SELECT id FROM users WHERE employee_no='DT22-0027'), '사내 준법 교육 체계 개편 회고', 'MID', '사내 준법 교육 체계 개편 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n이서준 경영지원파트장은 킥오프에서 "준법 교육이 매번 형식적으로 진행돼서, 듣고 나서도 실제로 뭘 조심해야 하는지 잘 기억을 못 합니다."라고 문제를 짚었습니다. 실무 사례 중심으로 교육 내용을 개편하는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 이서준 경영지원파트장은 실제 사례 기반 교육 콘텐츠로 개편을 완료했고 시범 교육 만족도 개선을 확인했다고 밝혔습니다. "형식적이라는 얘기는 이제 안 나올 것 같습니다."라는 소감처럼, 애초 목표였던 실효성 있는 교육이 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2025-10-17 15:00:00', '2025-10-17 15:00:00', NULL),
(246, 88, (SELECT id FROM users WHERE employee_no='DT22-0030'), '채용 프로세스 개선 TF 회고', 'MID', '채용 프로세스 개선 TF가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n이지안 HR파트장은 킥오프에서 "채용 단계별 소요 기간이 길어서, 다른 데 먼저 합격한 우수 인재를 놓치는 경우가 있었습니다."라고 문제를 짚었습니다. 프로세스를 간소화해 채용 기간을 단축하는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 이지안 HR파트장은 서류·면접 단계 병목 제거로 채용 소요 기간을 단축했다고 밝혔습니다. "지원자 입장에서도 대기 시간이 줄어서 만족도가 올라갔습니다."라는 소감처럼, 애초 목표였던 채용 기간 단축이 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2024-07-12 15:00:00', '2024-07-12 15:00:00', NULL),
(247, 89, (SELECT id FROM users WHERE employee_no='DT22-0030'), '온보딩 프로그램 개편 회고', 'MID', '온보딩 프로그램 개편 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n이지안 HR파트장은 킥오프에서 "신입 정착률이 기대에 못 미친다는 얘기가 계속 나옵니다. 온보딩이 형식적인 오리엔테이션 수준에 그쳤던 게 원인 같습니다."라고 문제를 짚었습니다. 온보딩 프로그램을 개편해 초기 적응을 돕는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 이지안 HR파트장은 부서별 멘토링 및 단계별 체크인 제도를 포함한 온보딩 프로그램 개편을 완료했다고 밝혔습니다. "초기 몇 달이 제일 중요한데, 이제 그 기간을 훨씬 촘촘하게 챙길 수 있습니다."라는 소감처럼, 애초 목표였던 초기 적응 지원이 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2025-03-14 15:00:00', '2025-03-14 15:00:00', NULL),
(248, 91, (SELECT id FROM users WHERE employee_no='DT22-0037'), '결산 프로세스 자동화 프로젝트 회고', 'MID', '결산 프로세스 자동화 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n오수빈 재무파트장은 킥오프에서 "월별 결산할 때마다 여러 시스템에서 데이터를 수작업으로 집계합니다. 마감까지 시간이 오래 걸리는 이유가 여기 있습니다."라고 문제를 짚었습니다. 집계 과정을 자동화해 결산 소요 시간을 줄이는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 오수빈 재무파트장은 핵심 집계 항목 자동화를 완료해 결산 소요 기간을 단축했다고 밝혔습니다. "이제 마감 막판에 밤새는 일이 많이 줄었습니다."라는 소감처럼, 애초 목표였던 결산 소요 시간 단축이 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2024-09-13 15:00:00', '2024-09-13 15:00:00', NULL),
(249, 93, (SELECT id FROM users WHERE employee_no='DT22-0013'), '지출 결의 정합성 점검 자동화 회고', 'MID', '지출 결의 정합성 점검 자동화 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n조민석 재무팀장은 킥오프에서 "지출 결의 데이터 오류를 사후 감사에서야 발견하는 경우가 있습니다. 미리 걸러내는 검증 로직이 필요합니다."라고 문제를 짚었습니다. 사전 검증 로직을 자동화해 오류를 미리 걸러내는 것을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 결과\n\n종료 보고에서 조민석 재무팀장은 지출 결의 상신 시점 자동 검증 로직 적용을 완료했다고 밝혔습니다. "이제 문제 있는 건은 상신 단계에서부터 걸러집니다."라는 소감처럼, 애초 목표였던 사전 오류 검증이 실제로 달성됐습니다.\n\n3. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2026-04-17 15:00:00', '2026-04-17 15:00:00', NULL),
(250, 94, (SELECT id FROM users WHERE employee_no='DT22-0175'), 'API 문서화 자동화 도입 보류 안내', 'LOW', '1. 배경\n\nAPI 문서가 코드와 따로 관리되다 보니 갱신이 자주 누락되는 문제가 있었습니다. 이를 해결하기 위해 Swagger 등을 활용한 문서 자동화 도입을 검토하는 프로젝트를 시작했습니다.\n\n2. 진행 경과\n\n임재훈 BE파트장 주도로 신태경 BE선임, 배시현 BE사원과 함께 우선 적용 대상 서비스부터 조사하기로 하고 착수했습니다.\n\n3. 현재 상태\n\n조사가 진행되던 중, 다른 과제와의 우선순위 조정으로 프로젝트를 잠정 보류하기로 했습니다. 지금까지 조사한 내용은 그대로 보관해두고, 우선순위가 정리되는 대로 다시 이어갈 예정입니다.', '2026-04-20 10:00:00', '2026-04-20 10:00:00', NULL),
(251, 95, (SELECT id FROM users WHERE employee_no='DT22-0207'), '레거시 인증 모듈 이관 TF 중단 공지', 'HIGH', '1. 중단 배경\n\n구 인증 모듈을 신규 SSO로 이관하기 위해 시작한 TF였습니다. 이관 대상을 절반쯤 정리한 시점에, 그룹 통합인증(SSO) 프로젝트가 먼저 착수되면서 저희가 하려던 작업이 그 프로젝트 범위에 그대로 포함되는 것을 확인했습니다.\n\n2. 결정 사항\n\n중복 작업을 막기 위해 이 TF는 여기서 중단합니다.\n\n3. 후속 조치\n\n지금까지 정리한 이관 대상 목록은 SSO 프로젝트팀에 인계했습니다. 관련 문의는 해당 팀으로 전달해주시기 바랍니다.', '2025-09-15 15:00:00', '2025-09-15 15:00:00', NULL),
(252, 96, (SELECT id FROM users WHERE employee_no='DT23-0041'), '배치 스케줄러 통합 검토 보류 공유', 'LOW', '1. 배경\n\n부서마다 배치 스케줄러를 따로 운영하고 있어, 하나로 통합할 수 있는지 검토하기 위해 프로젝트를 시작했습니다.\n\n2. 진행 경과\n\n정소윤 BE선임 주도로 오건희 BE사원과 함께 부서별 배치 스케줄러 현황 조사부터 시작했습니다.\n\n3. 현재 상태\n\n현황 조사를 진행하던 중, 별도로 진행 중인 코어뱅킹 배치 리팩토링 결과를 먼저 보고 판단하는 것이 낫다고 판단해 잠정 보류하기로 했습니다. 리팩토링 결과가 나오는 대로 다시 검토를 이어갈 예정입니다.', '2026-05-25 10:00:00', '2026-05-25 10:00:00', NULL),
(253, 98, (SELECT id FROM users WHERE employee_no='DT22-0033'), '직무기술서(JD) 표준화 TF 보류 공유', 'LOW', '1. 배경\n\n부서마다 JD 형식이 달라 채용 공고를 낼 때마다 새로 만들다시피 하는 문제가 있었습니다. 이를 해결하기 위해 표준 양식을 만드는 TF를 시작했습니다.\n\n2. 진행 경과\n\n홍수진 HR파트장 주도로 배지윤 선임과 함께 기존 JD 전수 수집부터 착수했습니다.\n\n3. 현재 상태\n\n수집을 진행하던 중, 별도로 진행 중인 평가 제도 개선 결과를 반영해야 한다는 판단에 따라 TF를 잠정 보류하기로 했습니다. 평가 제도 개선이 마무리되는 대로 표준화 작업을 다시 진행할 예정입니다.', '2026-03-20 10:00:00', '2026-03-20 10:00:00', NULL),
(254, 99, (SELECT id FROM users WHERE employee_no='DT22-0052'), '온프레미스-클라우드 하이브리드 전환 검토 TF 중단 공지', 'HIGH', '1. 중단 배경\n\n일부 레거시 시스템의 클라우드 전환 가능성을 검토하기 위해 TF를 시작했습니다. 전환 대상 시스템을 목록화하고 비용을 산정했습니다.\n\n2. 결정 사항\n\n비용 산정 결과 초기 전환 비용이 예상보다 커서, 현재 우선순위 기준으로는 투자 대비 효과가 낮다고 판단해 TF를 중단합니다.\n\n3. 후속 조치\n\n산정한 비용 자료는 남겨두어, 추후 우선순위가 바뀌면 다시 논의할 수 있도록 정리해두었습니다.', '2025-08-15 15:00:00', '2025-08-15 15:00:00', NULL),
(255, 100, (SELECT id FROM users WHERE employee_no='DT22-0073'), '위성 오피스 네트워크 구축 검토 보류 공유', 'LOW', '1. 배경\n\n지방 위성 오피스 설립 논의에 맞춰, 필요한 네트워크 구축 방안을 미리 검토하기 위해 프로젝트를 시작했습니다.\n\n2. 진행 경과\n\n한지석 인프라선임 주도로 문가영 선임과 함께 회선사업자 견적 요청부터 착수했습니다.\n\n3. 현재 상태\n\n검토를 진행하던 중, 위성 오피스 설립 자체가 보류되면서 네트워크 구축 검토도 함께 잠정 보류하기로 했습니다. 오피스 설립 논의가 재개되면 이어서 진행할 예정입니다.', '2026-06-15 10:00:00', '2026-06-15 10:00:00', NULL),
(256, 101, (SELECT id FROM users WHERE employee_no='DT22-0080'), '그룹사 크로스셀 전략 TF 중단 공지', 'HIGH', '1. 중단 배경\n\n그룹사 간 상품 교차 판매 전략을 검토하기 위해 TF를 시작했습니다. 계열사별 상품 매칭까지는 검토를 마쳤습니다.\n\n2. 결정 사항\n\n계열사별로 고객 데이터 공유 범위에 대한 입장이 달라 협의가 진전되지 않아, 착수 두 달 만에 TF를 중단합니다.\n\n3. 후속 조치\n\n지금까지 살펴본 상품 매칭 결과는 정리해서 보관해두었습니다. 이후 계열사 간 데이터 정책이 정리되면 다시 참고할 수 있을 것입니다.', '2025-10-31 15:00:00', '2025-10-31 15:00:00', NULL),
(257, 102, (SELECT id FROM users WHERE employee_no='DT22-0114'), 'PM 지식공유 세션 정례화 프로젝트 회고', 'MID', '1. 추진 배경\n\n신규 프로젝트마다 예전에 다른 프로젝트에서 이미 겪었던 문제를 또 겪는 경우가 많아, 과거 경험을 공유하는 정례 세션을 만들기 위해 시작했습니다.\n\n2. 진행 경과\n\n이도윤 PM파트장 주도로 곽태희, 임서진 선임과 함께 첫 세션 주제 선정부터 시작해 월 1회 정례 공유 세션 체계를 만들었습니다.\n\n3. 결과\n\n세 차례 진행해본 결과 반응이 나쁘지 않아 PM실 정규 일정으로 편입하기로 했습니다. 곽태희 선임은 발표를 준비하면서 예전 프로젝트를 복기하게 된 것이 의외로 도움이 됐다고 소감을 전했습니다.', '2024-12-13 15:00:00', '2024-12-13 15:00:00', NULL),
(258, 103, (SELECT id FROM users WHERE employee_no='DT22-0137'), '테스트 데이터 관리 체계 정비 프로젝트 회고', 'MID', '1. 추진 배경\n\n테스트할 때마다 데이터를 매번 새로 만들다 보니 케이스마다 품질이 들쭉날쭉했습니다. 이를 해결하기 위해 공통 테스트 데이터셋을 만드는 프로젝트를 시작했습니다.\n\n2. 진행 경과\n\n강지호 QA선임 주도로 하도훈, 백현준 선임과 함께 핵심 도메인별 테스트 데이터 요구사항 정리부터 착수했습니다.\n\n3. 결과\n\n공통 테스트 데이터셋과 생성 스크립트를 완성했습니다. QA팀 공용 저장소에 공유해두어, 다른 프로젝트에서도 바로 가져다 쓸 수 있게 됐습니다.', '2025-03-14 15:00:00', '2025-03-14 15:00:00', NULL),
(259, 104, (SELECT id FROM users WHERE employee_no='DT22-0146'), '폼 컴포넌트 검증 로직 표준화 프로젝트 회고', 'MID', '1. 추진 배경\n\n화면마다 입력값 검증 로직을 따로 구현하다 보니, 어떤 화면은 이메일 형식을 검사하고 어떤 화면은 검사하지 않는 등 편차가 컸습니다.\n\n2. 진행 경과\n\n정하나 FE선임 주도로 조은비, 곽민서 선임과 함께 기존 화면별 검증 로직을 전수 조사한 뒤 공통 검증 로직으로 표준화했습니다.\n\n3. 결과\n\n필수값, 형식, 길이 제한 등 기본 검증은 공통 모듈 하나로 처리되게 됐습니다. 에러 메시지 문구도 함께 통일해, 사용자 입장에서 헷갈리는 부분이 줄었습니다.', '2024-10-11 15:00:00', '2024-10-11 15:00:00', NULL),
(260, 105, (SELECT id FROM users WHERE employee_no='DT22-0087'), '고객사 미팅 이력 관리 체계 정비 프로젝트 회고', 'MID', '1. 추진 배경\n\n고객사별 미팅 이력이 담당자 개인 메모에만 남아 있어, 담당자가 바뀌면 인수인계가 거의 되지 않는 문제가 있었습니다.\n\n2. 진행 경과\n\n함지수 영업파트장 주도로 황보람 팀장과 함께 기존 미팅 이력을 취합해 공용 이력 관리 체계를 구축했습니다.\n\n3. 결과\n\n이제 담당자가 바뀌어도 이전 미팅에서 오간 내용을 바로 확인할 수 있게 됐습니다. 신규 인력 인수인계에도 이 체계가 유용하게 쓰일 것으로 기대하고 있습니다.', '2025-06-13 15:00:00', '2025-06-13 15:00:00', NULL),
(261, 106, (SELECT id FROM users WHERE employee_no='DT22-0040'), '취약점 관리 대장 정비 프로젝트 회고', 'MID', '1. 추진 배경\n\n발견된 취약점의 조치 여부가 추적되지 않아, 재발했을 때 예전에 조치했던 건인지 새로 생긴 건인지 확인이 어려웠습니다.\n\n2. 진행 경과\n\n표건우 보안선임 주도로 우진성, 정민혁 선임과 함께 과거 취약점 이력을 취합해 관리 대장을 구축했습니다.\n\n3. 결과\n\n발견부터 조치, 재검증까지 이력을 한 곳에서 추적할 수 있게 됐습니다. 정기 점검 때마다 예전 이력과 대조할 수 있어 재발 여부 확인이 훨씬 수월해질 것으로 기대됩니다.', '2025-02-14 15:00:00', '2025-02-14 15:00:00', NULL),
(262, 107, (SELECT id FROM users WHERE employee_no='DT22-0011'), '사내 비품 발주 프로세스 개선 프로젝트 회고', 'MID', '1. 추진 배경\n\n비품 발주 요청이 이메일로 여기저기 흩어져 들어오면서 요청이 누락되는 경우가 종종 있었습니다.\n\n2. 진행 경과\n\n신동렬 경영지원팀장 주도로 박시우, 김하온 선임과 함께 발주 요청 양식 초안을 작성하고 요청 창구를 하나로 모으는 작업을 진행했습니다.\n\n3. 결과\n\n이제 요청은 한 채널로만 들어오고, 처리 현황도 한눈에 확인할 수 있게 됐습니다. 누락되는 요청이 사라지면서 총무 쪽 문의도 줄었습니다.', '2025-08-15 15:00:00', '2025-08-15 15:00:00', NULL),
(309, 17, (SELECT id FROM users WHERE employee_no='DT22-0187'), '핵심 배치 22개 선정 근거 정리', 'MID', '6/5 회의에서 말씀드린 배치 선정 작업, 세부 근거 정리해서 공유드립니다.\n\n1. 조사 범위\n전체 배치 118개를 전수 조사했습니다. 대상은 야간·새벽에 무인으로 도는 배치 전부입니다.\n\n2. 선정 기준\n- 실패 시 후속 작업 블로킹 여부\n- 야간 무인 실행 여부\n- 최근 6개월 내 실패 이력 존재 여부\n\n3. 결과\n세 기준을 모두 충족하는 배치가 22개로 확인됐습니다. 나머지 96개는 실패해도 후속 작업에 영향이 없거나(단독 배치), 최근 6개월 무사고였습니다.\n\n4. 후속 계획\n1차로 22개에 알림 체계를 우선 적용하고, 안정화되면 나머지도 순차적으로 확대할 예정입니다. 22개 목록은 첨부 파일로 올려뒀습니다.', '2024-06-07 09:00:00', '2024-06-07 09:00:00', NULL),
(310, 17, (SELECT id FROM users WHERE employee_no='DT23-0040'), '슬랙 알림 연동 설계 문서', 'HIGH', '7/10 회의에서 나온 알림 체계 설계, 문서로 정리했습니다.\n\n1. 전체 구조\n배치 스케줄러 → 실패 이벤트 발행 → 알림 서비스가 구독 → 슬랙 웹훅 호출, 순서로 갑니다. 배치 스케줄러 자체를 건드리지 않고 이벤트만 발행하도록 해서 기존 배치 로직에 영향이 없게 했습니다.\n\n2. 채널 분기\n배치를 담당하는 파트(예: 정산, 알림, 리포트)별로 슬랙 채널을 분리했습니다. 담당자가 아닌 파트 채널에까지 알림이 뜨는 걸 막기 위함입니다.\n\n3. 발송 시점\n정태균님 의견대로 재시도 중에는 알림을 보내지 않고, 최종 실패로 확정된 시점에만 발송하도록 했습니다. 재시도로 자동 복구되는 케이스까지 알림이 가면 오히려 신뢰도가 떨어질 것 같아서입니다.\n\n4. 알림 묶음 처리\n최민혁 선임님이 짚어주신 알림 폭주 문제는, 동일 배치가 짧은 시간 내 반복 실패할 경우 1건으로 묶어서 발송하는 방식으로 처리했습니다.\n\n5. 일정\n8월 초까지 22개 핵심 배치 대상으로 1차 개발 완료 목표입니다.', '2024-07-12 09:00:00', '2024-07-12 09:00:00', NULL),
(311, 17, (SELECT id FROM users WHERE employee_no='DT22-0195'), '오탐 알림 발생 배치 3건 — 재현 조건 정리', 'HIGH', '8/14 회의에서 보고드린 오탐 이슈, 재현 조건 정리해서 다시 공유드립니다.\n\n[오탐 발생 배치 3건]\n\n1. 정산 마감 배치\n- 재현: 정상 종료(exit code 0)했지만 마지막 로그 라인이 "처리 완료 확인 필요"로 끝나서 실패로 오판\n- 원인: 판정 로직이 종료 코드가 아니라 로그 마지막 줄 문자열 패턴으로 성공/실패를 판단\n\n2. 리포트 집계 배치\n- 재현: 경고성 로그(WARN)를 마지막 줄에 남기고 정상 종료했는데 실패로 오판\n- 원인: 1번과 동일 (로그 기반 판정)\n\n3. 알림 발송 이력 정리 배치\n- 재현: 정상 종료했지만 로그 마지막 줄이 비어있는 경우 실패로 오판\n- 원인: 1번과 동일\n\n[정리]\n3건 모두 원인이 동일합니다 — 종료 코드가 아니라 로그 텍스트로 성공/실패를 판단하는 구조였습니다. 종료 코드 기준으로 판정 로직을 통일하는 방향으로 회의에서 정리됐고, 제가 이번 주 안에 수정하겠습니다.', '2024-08-16 09:00:00', '2024-08-16 09:00:00', NULL),
(312, 17, (SELECT id FROM users WHERE employee_no='DT22-0187'), '[결정] 배치 성공/실패 판정 로직을 종료 코드 기준으로 통일', 'HIGH', '8/14 회의에서 논의된 오탐 이슈 관련 결정 사항 공지드립니다.\n\n1. 결정 사항\n배치 성공/실패 판정 기준을 로그 텍스트 패턴이 아닌 종료 코드(exit code) 기준으로 통일합니다.\n\n2. 배경\n일부 배치가 정상 종료(exit code 0)했음에도 로그 마지막 줄 문자열 때문에 실패로 오판되어 알림이 발송되는 사례가 3건 확인됐습니다. 오탐이 반복되면 알림 신뢰도 자체가 떨어지기 때문에 우선순위를 높여 처리합니다.\n\n3. 적용 대상\n1차 적용된 22개 핵심 배치 전체, 판정 로직 변경 후 전량 재검증합니다.\n\n4. 일정\n구재현님이 판정 로직 통일 작업과 회귀 검증을 맡아 9월 초까지 완료합니다. 최민혁 선임님이 회귀 테스트 계획을 별도로 수립해주십니다.\n\n질문 있으시면 댓글 남겨주세요.', '2024-08-20 09:00:00', '2024-08-20 09:00:00', NULL),
(313, 17, (SELECT id FROM users WHERE employee_no='DT22-0187'), '7월 중간 진행 상황 요약', 'MID', '중간 점검 겸 진행 상황 정리해서 공유드립니다.\n\n1. 배치 선정\n전체 118개 배치 조사 완료, 22개 핵심 배치 선정 완료(6/5 확정).\n\n2. 알림 체계 개발\n슬랙 웹훅 연동 설계 완료(7/10). 현재 정하윤님·정태균님이 개발 중이며 8월 초 1차 배포 목표로 진행되고 있습니다.\n\n3. 남은 일정\n- 8월 초: 22개 배치 대상 1차 배포\n- 8월 중: 적용 결과 모니터링 및 이슈 대응\n- 9월 초: 최종 검증 및 종료 보고\n\n순조롭게 진행 중이며 별도 리스크는 없습니다.', '2024-07-20 09:00:00', '2024-07-20 09:00:00', NULL),
(314, 17, (SELECT id FROM users WHERE employee_no='DT22-0210'), '[참고] 알림 폭주 방지 관련 자료', 'LOW', '최민혁 선임님이 짚어주신 알림 폭주 방지 관련해서 참고할 만한 자료 찾아서 공유드립니다.\n\n동일 이벤트가 짧은 시간에 반복 발생할 때 알림을 묶어서 보내는 방식(디바운싱/그룹핑)이 일반적으로 쓰이는 것 같습니다. 저희는 "동일 배치가 짧은 시간 내 반복 실패 시 1건으로 묶어서 발송"하는 규칙으로 적용했는데, 이 방향이 무난해 보입니다.\n\n추가로 살펴본 사내 다른 알림 연동 사례들도 비슷하게 시간 윈도우 기반 묶음 처리를 쓰고 있어서, 저희 설계 방향이 크게 벗어나지 않는다고 판단했습니다.', '2024-07-15 09:00:00', '2024-07-15 09:00:00', NULL),
(315, 17, (SELECT id FROM users WHERE employee_no='DT22-0203'), '[온보딩] 배치 모니터링 체계 요약 메모', 'LOW', '신규로 이 프로젝트 관련 작업에 합류하는 분들을 위해 간단히 정리해둡니다.\n\n1. 대상 배치\n전체 118개 중 22개 핵심 배치가 1차 알림 적용 대상입니다(선정 기준: 후속 작업 블로킹 여부, 야간 무인 실행, 최근 6개월 실패 이력).\n\n2. 알림 구조\n배치 실패 이벤트 발행 → 알림 서비스 구독 → 슬랙 웹훅 발송. 채널은 담당 파트별로 분리되어 있습니다.\n\n3. 판정 기준\n종료 코드(exit code) 기준으로 성공/실패를 판정합니다(기존 로그 텍스트 기반 판정은 오탐 이슈로 폐기).\n\n4. 문의처\n구조 관련 문의는 정하윤님, 판정 로직 관련 문의는 저(구재현)에게 편하게 물어봐주세요.', '2024-09-01 09:00:00', '2024-09-01 09:00:00', NULL),
(316, 17, (SELECT id FROM users WHERE employee_no='DT22-0187'), '프로젝트 회고 — 배치 작업 모니터링 고도화', 'MID', '오늘 종료 보고 마치고, 짧게 회고 남겨둡니다.\n\n1. 잘된 점\n실패 감지부터 알림까지 소요 시간을 수 시간에서 3분 이내로 단축했습니다. 새벽에 배치가 실패해도 당직자가 바로 확인할 수 있게 된 게 이번 프로젝트의 가장 큰 성과라고 생각합니다.\n\n2. 어려웠던 점\n1차 적용 이후 일부 배치에서 오탐 알림이 발생했습니다. 정상 종료된 배치가 로그 텍스트 판정 방식 때문에 실패로 잡히는 문제였는데, 초반에 이걸 놓쳤던 게 아쉬웠습니다. 판정 기준을 종료 코드로 통일하고 나서야 안정화됐습니다.\n\n3. 배운 점\n알림 체계는 "일단 빠르게 붙이는 것"보다 "판정 기준을 명확히 하는 것"이 먼저라는 걸 이번에 확실히 배웠습니다. 오탐이 반복되면 알림 자체를 신뢰하지 않게 되니까요.\n\n4. 다음 단계\n핵심 배치 22개는 안정적으로 운영 중입니다. 나머지 96개 배치도 이번에 다진 판정 기준·알림 구조를 그대로 활용해서 순차적으로 확대할 예정입니다.', '2024-09-10 15:00:00', '2024-09-10 15:00:00', NULL),
(286, 19, (SELECT id FROM users WHERE employee_no='DT22-0200'), '연동 끊김 원인 분석 상세 — 로그 재검토 결과', 'HIGH', '어제(8/22) 회의에서 말씀드린 원인 분석, 근거 데이터까지 정리해서 다시 공유드립니다.\n\n1. 분석 범위\n최근 3개월(5/23~8/22) 발생한 끊김 17건 전체 로그를 다시 봤습니다.\n\n2. 원인 1 — keep-alive 타임아웃 불일치\n채널사 API 게이트웨이는 유휴 연결을 60초에서 끊는데, 저희 쪽 keep-alive 설정은 120초입니다. 이 60초 구간에 요청이 들어가면 연결이 이미 끊긴 상태에서 요청을 보내는 셈이 되어 실패합니다. 17건 중 9건이 이 패턴이었습니다.\n\n3. 원인 2 — 재시도가 오히려 차단을 유발\n고정 간격 3회 재시도가 채널사 rate limit 기준(초당 요청 수)을 넘겨서, 재시도 자체가 일시 차단을 유발한 케이스가 6건 있었습니다.\n\n4. 나머지 2건\n네트워크 구간 자체 이슈로, 로직 개선과 무관해 보입니다.\n\n5. 정리\n15/17건이 재시도 로직 개선으로 해소 가능하다고 판단합니다. 9/26 회의에서 지수 백오프 설계안 논의 예정입니다.', '2024-08-23 09:00:00', '2024-08-23 09:00:00', NULL),
(287, 19, (SELECT id FROM users WHERE employee_no='DT22-0196'), '재시도 로직 설계 문서 — 지수 백오프 + 채널별 override', 'MID', '어제(9/26) 회의에서 합의된 설계 최종안 정리해서 공유드립니다.\n\n1. 기본 파라미터\n- 초기 간격: 1초\n- 최대 재시도: 5회\n- 배수(factor): 2\n- 지터: ±20% 랜덤 (동시 재시도 몰림 방지)\n\n2. 채널별 override 구조\n강도연 사원, 구재현 사원 의견대로 채널마다 rate limit 정책이 달라서, 채널별로 이 값들을 override할 수 있게 설정 테이블을 하나 뒀습니다. 값을 안 넣으면 기본값을 그대로 씁니다.\n\n3. 채널별 rate limit 조사 결과(구재현 사원 정리)\n- 카카오톡: 초당 10건\n- 슬랙: 초당 5건\n- 네이버웍스: 초당 8건\n\n이 수치를 기준으로 각 채널 초기값을 다르게 잡을 예정입니다.\n\n4. 다음 단계\n다음 스프린트에 개발 반영, 배포 전 부하 테스트로 rate limit 재차단이 없는지 확인 예정입니다.', '2024-09-27 09:00:00', '2024-09-27 09:00:00', NULL),
(288, 19, (SELECT id FROM users WHERE employee_no='DT22-0203'), '외부 메시징 API 재시도 가이드라인 벤치마킹', 'LOW', '재시도 로직 설계하면서 참고할 만한 외부 자료들 정리해서 공유드립니다.\n\n1. AWS SDK 재시도 전략\n지수 백오프 + 지터를 기본 권장 방식으로 채택하고 있습니다. 저희가 잡은 방향과 동일해서 안심이 됐습니다.\n\n2. 슬랙 API 공식 가이드\nHTTP 429 응답 시 Retry-After 헤더를 우선 신뢰하라고 명시돼 있습니다. 저희 구현에도 이 헤더 값이 있으면 그걸 우선 쓰는 로직을 넣는 게 좋을 것 같습니다.\n\n3. 참고 링크\n내부 위키에 원문 링크 정리해뒀습니다. 설계 문서 리뷰하실 때 같이 참고하시면 좋을 것 같습니다.', '2024-10-10 09:00:00', '2024-10-10 09:00:00', NULL),
(289, 19, (SELECT id FROM users WHERE employee_no='DT22-0197'), '슬랙 채널 오탐 23건 — 재현 조건 및 원인 상세', 'HIGH', '어제(11/7) 회의에서 말씀드린 오탐 이슈, 재현 조건이랑 원인 정리해서 공유드립니다.\n\n1. 현상\n최근 2주(10/24~11/7) 실제 장애 0건인데 슬랙 채널에서만 오탐 알림 23건 발생.\n\n2. 재현 조건\n슬랙 채널 평균 응답시간이 800ms대인데, 감지 임계치를 전 채널 공통 2초로 잡아뒀습니다. 슬랙 쪽 응답이 조금만 튀어도(1.5~2초대) 정상 범위인데도 임계치를 넘겨 오탐으로 잡힌 겁니다.\n\n3. 다른 채널은 왜 괜찮았나\n카카오톡, 네이버웍스는 평균 응답시간이 애초에 400~600ms대라 2초 임계치에 여유가 있었습니다. 슬랙만 특이 케이스였습니다.\n\n4. 대응 방향\n채널별로 baseline 응답시간을 재측정해서 임계치를 각각 다시 잡기로 했습니다(유하람 사원 담당, 11/11까지).', '2024-11-08 09:00:00', '2024-11-08 09:00:00', NULL),
(290, 19, (SELECT id FROM users WHERE employee_no='DT22-0200'), '채널별 장애 감지 임계치 재설정 공지', 'HIGH', '오탐 이슈(11/7 공유) 대응으로 채널별 감지 임계치를 아래와 같이 확정해서 공지드립니다.\n\n- 슬랙: 4초 (기존 2초 → 완화)\n- 카카오톡: 2초 (기존 유지)\n- 네이버웍스: 2.5초 (기존 2초 → 소폭 완화)\n\n유하람 사원이 측정한 채널별 baseline 응답시간에 여유분을 더해 정한 값입니다. 이번 주 배포에 반영하고, 배포 후 1주일 오탐 발생 여부 모니터링하겠습니다. 다시 오탐이 잦으면 임계치를 추가로 조정할 예정이니 다들 알림 로그 눈에 띄면 공유 부탁드립니다.', '2024-11-11 09:00:00', '2024-11-11 09:00:00', NULL),
(291, 19, (SELECT id FROM users WHERE employee_no='DT22-0213'), '12월 중간 진행 요약', 'MID', '연말이라 지금까지 진행 상황 한 번 정리해서 공유드립니다.\n\n1. 재시도 로직\n지수 백오프 + 채널별 override 구조로 개발 완료, 배포 후 부하 테스트에서 rate limit 재차단 없음 확인.\n\n2. 장애 감지 체계\n채널별 임계치 재설정(슬랙 4초/카카오톡 2초/네이버웍스 2.5초) 배포 후 2주간 오탐 0건으로 안정화됨.\n\n3. 남은 일정\n실제 장애 상황에서 새 로직이 어떻게 동작하는지 아직 검증 사례가 없어서, 다음 장애 발생 시 대응 과정을 별도로 기록해두기로 했습니다.\n\n4. 전반 평가\n킥오프 때 목표(감지 지연 단축, 재시도 로직 보강) 기준으로 보면 순조롭게 진행되고 있습니다.', '2024-12-01 09:00:00', '2024-12-01 09:00:00', NULL),
(292, 19, (SELECT id FROM users WHERE employee_no='DT22-0171'), '채널 연동 재시도/감지 로직 인수인계 메모', 'LOW', '이번 프로젝트로 바뀐 채널 연동 구조를 간단히 정리해둡니다. 이후 유지보수하실 분들 참고하시면 좋을 것 같습니다.\n\n1. 재시도 로직\n채널별 override 설정 테이블에서 초기 간격/최대 횟수/배수 값을 조회해서 사용합니다. 값이 없으면 공통 기본값(1초/5회/배수2)을 씁니다.\n\n2. 감지 임계치\n채널마다 다르게 설정돼 있습니다(슬랙 4초/카카오톡 2초/네이버웍스 2.5초). 새 채널 추가 시 반드시 baseline 응답시간부터 재보고 임계치를 잡아야 합니다. 공통값을 그대로 쓰면 슬랙 때처럼 오탐이 날 수 있습니다.\n\n3. 참고 자료\n설계 문서(정예린 선임 작성)와 채널별 rate limit 조사(구재현 사원 작성)를 같이 보시면 이해가 빠릅니다.', '2024-12-19 09:00:00', '2024-12-19 09:00:00', NULL),
(293, 19, (SELECT id FROM users WHERE employee_no='DT22-0196'), '그룹 채널 연동 안정화 프로젝트 회고', 'MID', '오늘 종료 보고를 마치면서, 프로젝트 전체를 돌아보며 회고 남깁니다.\n\n1. 잘한 점\n원인 분석을 먼저 충분히 하고 나서 설계로 넘어간 게 결과적으로 맞았습니다. keep-alive 미스매치와 rate limit 충돌, 두 원인을 명확히 나눠서 봤기 때문에 지수 백오프 + 채널별 override라는 구체적인 해법이 나올 수 있었습니다.\n\n2. 아쉬웠던 점\n장애 감지 임계치를 처음부터 채널 공통값으로 잡은 건 아쉬운 판단이었습니다. 재시도 로직에서 이미 채널별 특성 차이를 겪었는데도 감지 쪽에서 같은 실수를 반복했습니다. 다음에는 처음부터 채널별 특성을 전제로 설계하는 게 나을 것 같습니다.\n\n3. 결과\n감지 시간이 평균 42분에서 3분대로 단축됐고, 12/15 실제 장애 때 지수 백오프 4회차에서 자동 복구되어 사용자 문의 없이 종료됐습니다. 오탐도 임계치 재설정 이후 안정화됐습니다.\n\n4. 다음에 참고할 점\n"일단 공통값으로 시작하고 나중에 세분화"보다 "처음부터 대상별 특성을 가정하고 설계"하는 게 재작업을 줄인다는 걸 이번에 다시 확인했습니다.', '2025-01-20 15:00:00', '2025-01-20 15:00:00', NULL),
(271, 24, (SELECT id FROM users WHERE employee_no='DT22-0199'), '[외부참고] 오픈소스 API 게이트웨이 비교 자료', 'LOW', '킥오프에서 정리한 요구사항(레이트리밋, 인증, 라우팅) 기준으로 후보 솔루션 자료를 정리해서 공유합니다.\n- 레이트리밋: 대부분 플러그인 형태로 기본 지원, 세부 정책 커스터마이징 수준에 차이\n- 인증: JWT 검증 플러그인은 공통 제공, 세션 기반 인증까지 지원하는 건 일부\n- 프로토콜: REST 중심 지원이 많고 gRPC까지 커버하는 건 후보가 좁아짐\n- 운영 부담: 셀프호스팅 시 클러스터 구성/모니터링을 우리 쪽에서 가져가야 함\n\n우리 서비스들이 REST/gRPC가 섞여 있는 걸 감안하면 프로토콜 지원 범위와 운영 부담을 같이 봐야 할 것 같습니다. 25일 회의 전까지 참고해주세요.', '2025-06-10 14:00:00', '2025-06-10 14:00:00', NULL),
(272, 24, (SELECT id FROM users WHERE employee_no='DT22-0198'), '게이트웨이 솔루션 선정 결과 공유', 'MID', '25일 회의에서 논의한 대로 게이트웨이 솔루션 방향을 정리합니다.\n\n- 상용 솔루션 대신 셀프호스팅 오픈소스 게이트웨이로 방향 결정\n- 결정 이유: 운영팀 리소스로 감당 가능한 수준이고, 레이트리밋·인증 플러그인 지원이 요구사항을 충족\n- 기존 서비스들이 REST/gRPC 혼재라 프로토콜 지원 범위도 선정 기준에 포함\n- 다음 단계: 배민아·조현아 담당으로 PoC 환경 구축 진행\n\nPoC 결과는 다음 회의(레이트리밋 정책 설계)에서 같이 공유하겠습니다.', '2025-06-26 11:00:00', '2025-06-26 11:00:00', NULL),
(273, 24, (SELECT id FROM users WHERE employee_no='DT22-0178'), '레이트리밋 정책 설계 문서', 'MID', '23일 회의에서 논의된 레이트리밋 정책 설계 내용을 문서로 정리합니다.\n\n1. 임계치 산정\n서비스별 평시/피크 트래픽 데이터 취합, 피크 기준으로 기본 임계치 초안 산정\n\n2. 초과 요청 처리\n429 응답과 함께 재시도 대기시간 헤더를 내려주는 방식 채택. 클라이언트 쪽 영향도는 별도 검토 필요\n\n3. 정책 관리 방식\n기본 정책은 게이트웨이 설정으로 중앙관리, 서비스별 예외 트래픽은 화이트리스트로 별도 관리\n\n임계치 확정안은 트래픽 데이터 기반으로 이번 주 안에 마무리해서 다시 공유드리겠습니다.', '2025-07-24 10:30:00', '2025-07-24 10:30:00', NULL),
(274, 24, (SELECT id FROM users WHERE employee_no='DT22-0192'), '[이슈] 인증 중앙화 이관 중 하위호환성 문제', 'HIGH', '인증 중앙화 이관 작업 중 발견된 이슈를 공유합니다.\n\n문제 상황\n서비스마다 인증 방식이 달라(일부 자체 세션, 일부 JWT) 게이트웨이 단일 인증 스펙으로 통일하는 작업이 예상보다 지연됐습니다. 특히 레거시 서비스 하나는 기존 클라이언트가 구버전 토큰 포맷을 그대로 사용 중이라, 게이트웨이 인증으로 그대로 전환하면 하위호환이 깨지는 상황을 확인했습니다.\n\n대응 방향(20일 회의 합의)\n과도기 동안 게이트웨이가 신규 토큰과 구버전 토큰을 모두 검증하는 브릿지 방식으로 임시 대응하기로 했습니다. 배하율은 인증 방식 통일 가이드를 작성하고, 저(조현아)는 레거시 서비스 브릿지 검증 로직을 구현합니다.\n\n브릿지 로직은 부하 테스트 전까지 완료 목표로 진행하겠습니다.', '2025-08-21 16:00:00', '2025-08-21 16:00:00', NULL),
(275, 24, (SELECT id FROM users WHERE employee_no='DT22-0198'), '[결정] 인증 브릿지 방식 적용 확정', 'HIGH', '인증 중앙화 이관 이슈 관련 결정 사항을 공지합니다.\n\n배경: 레거시 서비스 중 구버전 토큰 포맷을 쓰는 클라이언트가 있어, 게이트웨이 인증으로 즉시 전환 시 하위호환이 깨지는 문제를 확인했습니다.\n\n결정 사항\n해당 서비스는 게이트웨이가 신/구 토큰을 모두 검증하는 브릿지 방식을 과도기 동안 적용합니다. 신규 토큰 전환이 완료되는 시점에 구토큰 검증 로직을 제거할 예정입니다. 다른 서비스들도 인증 방식 통일 가이드(배하율 작성)를 기준으로 순차 정리합니다.\n\n이 결정으로 기존 클라이언트 영향 없이 인증 중앙화를 진행할 수 있게 됐습니다. 브릿지 검증 로직 구현 후 부하 테스트에서 성능 영향도까지 같이 확인하겠습니다.', '2025-08-28 17:00:00', '2025-08-28 17:00:00', NULL),
(276, 24, (SELECT id FROM users WHERE employee_no='DT22-0173'), '부하 테스트 결과 및 중간 진행상황 요약', 'MID', '24일 회의에서 공유된 부하 테스트 결과와 프로젝트 중간 진행상황을 정리합니다.\n\n부하 테스트 결과\n게이트웨이 경유 시 평균 응답 지연이 소폭 증가했지만, 레이트리밋 덕분에 피크 시 장애 전파는 확실히 감소했습니다. 인증 브릿지 검증 로직이 지연의 주요 원인으로 파악되어 캐싱을 적용했고, 재측정 결과 지연이 허용 범위로 개선돼 성능 기준을 통과했습니다.\n\n중간 진행상황\n게이트웨이 솔루션 선정 완료, 레이트리밋 정책 설계 및 적용 완료, 인증 중앙화는 브릿지 방식으로 레거시 하위호환 이슈를 해결했습니다. 부하 테스트를 통과했고, 다음 단계는 서비스 순차 이전 계획 수립입니다.\n\n일정대로 진행 중이며 다음 회의에서 이전 순서를 확정할 예정입니다.', '2025-09-25 15:00:00', '2025-09-25 15:00:00', NULL),
(277, 24, (SELECT id FROM users WHERE employee_no='DT23-0042'), '[온보딩] 게이트웨이 이전 대상 서비스 가이드', 'MID', '22일 회의에서 확정된 순차 이전 계획을 바탕으로, 이전 작업에 새로 합류하는 분들을 위한 온보딩 자료를 정리합니다.\n\n이전 대상 및 순서\n1차는 트래픽이 크고 장애 영향도가 높은 핵심 서비스를 우선 이전합니다. 2차는 나머지 서비스로, 1차 완료 이후 순차 진행합니다(다음 단계 과제).\n\n1차 대상 서비스 준비 상태\n인증 방식은 브릿지 검증까지 완료되어 이전 준비된 상태입니다. 레이트리밋 정책은 게이트웨이 중앙 설정 기준을 그대로 적용합니다.\n\n작업 시 참고\n인증 관련 이슈는 배하율이 작성한 통일 가이드를 참고하시고, 레이트리밋 초과 시 429 + 재시도 헤더 스펙은 곽은서 문서를 참고하세요.\n\n궁금한 점 있으면 언제든 문의 주세요.', '2025-10-23 11:00:00', '2025-10-23 11:00:00', NULL),
(278, 24, (SELECT id FROM users WHERE employee_no='DT22-0198'), '[회고] 서비스별 API 게이트웨이 통합 구축 프로젝트를 마치며', 'MID', '오늘부로 게이트웨이 통합 구축 프로젝트를 마무리하며 회고를 남깁니다.\n\n잘한 점\n솔루션 선정 단계에서 운영 부담과 프로토콜 지원 범위를 같이 검토해 셀프호스팅 오픈소스 게이트웨이로 무리 없이 방향을 잡았습니다. 레이트리밋 정책을 트래픽 데이터 기반으로 설계해 피크 시 장애 전파를 실제로 줄였고, 인증 중앙화 이관 중 하위호환 이슈를 브릿지 방식으로 풀어 기존 클라이언트 영향 없이 전환했습니다.\n\n아쉬운 점\n서비스별 인증 방식이 제각각이라는 걸 이관 착수 전에 충분히 파악하지 못해 중간에 이슈로 드러났습니다. 인증 브릿지 검증 로직 때문에 부하 테스트 초반 지연이 늘어 재작업(캐싱 적용)이 발생했습니다.\n\n결과\n핵심 서비스 6개를 게이트웨이 뒤로 이전, 레이트리밋·인증 중앙화를 완료했습니다. 나머지 서비스는 다음 단계에서 순차적으로 이전할 계획입니다.\n\n프로젝트에 참여해주신 모든 분들 고생 많으셨습니다.', '2025-11-14 15:00:00', '2025-11-14 15:00:00', NULL),
(301, 40, (SELECT id FROM users WHERE employee_no='DT23-0035'), '기존 웹 중심 체크리스트 갭 조사 결과 공유', 'MID', '킥오프에서 나온 문제의식을 바탕으로, 기존 웹 중심 체크리스트를 기준으로 모바일 앱에서 놓치고 있는 항목을 조사했습니다.\n\n1. 조사 방법\n\n최근 3개월간 모바일 앱에서 발생한 이슈 리포트와 기존 체크리스트 항목을 대조했습니다.\n\n2. 주요 갭\n\n- 기기별 화면 크기·해상도 대응 여부 미점검\n- 네트워크 끊김·재연결 시 동작(오프라인 시나리오) 항목 부재\n- OS 버전별 권한 팝업 차이 미반영\n- 저사양 기종에서의 성능 저하 여부 별도 확인 없음\n\n3. 제안\n\n위 항목들을 다음 회의에서 테스트 대상 기종·OS 버전 선정과 함께 반영 여부를 논의하면 좋겠습니다.', '2025-09-10 09:30:00', '2025-09-10 09:30:00', NULL),
(302, 40, (SELECT id FROM users WHERE employee_no='DT23-0034'), '모바일 테스트 매트릭스 설계안', 'MID', '대상 기종·OS 버전 선정 회의 결과를 바탕으로, 테스트 매트릭스 구조를 설계했습니다.\n\n1. 축 구성\n\n- 기기 티어: 플래그십 / 중급 / 저사양 (3단계)\n- OS 버전: Android 12~14, iOS 16~17\n- 네트워크 조건: Wi-Fi / LTE / 오프라인\n\n2. 셀 정의\n\n각 셀은 기기 티어 x OS 버전 x 네트워크 조건 조합이며, 셀마다 공통 체크리스트 항목(화면 렌더링, 권한 팝업, 오프라인 동작)을 매핑합니다.\n\n3. 다음 단계\n\n이 구조로 초안을 채운 뒤 리뷰 회의에서 검증할 예정입니다.', '2025-09-29 14:00:00', '2025-09-29 14:00:00', NULL),
(303, 40, (SELECT id FROM users WHERE employee_no='DT22-0131'), '저사양 기종 스크롤 성능 이슈 분석', 'HIGH', '매트릭스 리뷰 중 발견된 저사양 기종 스크롤 끊김 현상을 분석했습니다.\n\n1. 증상\n\n갤럭시 A14(저사양 티어)에서 상품 목록 화면 스크롤 시 프레임 드랍이 눈에 띄게 발생. 플래그십·중급 기종에서는 재현되지 않음.\n\n2. 원인 추정\n\n목록 아이템마다 고해상도 썸네일 이미지를 원본 크기로 로드하고 있어, 저사양 기종의 메모리·GPU 처리 한계에서 병목이 발생하는 것으로 추정됨.\n\n3. 처리\n\n개발팀에 썸네일 리사이징 적용을 공유했고, QA 체크리스트에는 저사양 기종 전용 스크롤·렌더링 성능 점검 항목을 추가하기로 함.', '2025-11-12 11:00:00', '2025-11-12 11:00:00', NULL),
(304, 40, (SELECT id FROM users WHERE employee_no='DT23-0034'), '체크리스트에 저사양 기종 성능 항목 반영 결정', 'HIGH', '1. 배경\n\n매트릭스 리뷰 과정에서 저사양 기종에서만 재현되는 스크롤 성능 이슈가 발견되었습니다.\n\n2. 결정 사항\n\n모바일 QA 체크리스트에 저사양 기종 전용 스크롤·렌더링 성능 점검 항목을 정식으로 추가합니다.\n\n3. 후속 조치\n\n체크리스트 최종안에 반영한 뒤, 종료 보고 전까지 전 항목 검증을 완료할 예정입니다.', '2025-11-14 16:00:00', '2025-11-14 16:00:00', NULL),
(305, 40, (SELECT id FROM users WHERE employee_no='DT23-0035'), '모바일 QA 체계 수립 중간 진행 상황', 'MID', '1. 진행 경과\n\n킥오프 이후 기존 체크리스트 갭 조사를 마쳤고, 테스트 대상 기종(플래그십/중급/저사양)과 OS 버전(Android 12~14, iOS 16~17)을 확정했습니다. 이를 바탕으로 테스트 매트릭스 설계안을 작성해 초안 채우기를 진행 중입니다.\n\n2. 남은 일정\n\n매트릭스 초안을 채운 뒤 리뷰 회의를 거쳐 체크리스트 최종안을 확정할 예정입니다.', '2025-10-15 10:00:00', '2025-10-15 10:00:00', NULL),
(306, 40, (SELECT id FROM users WHERE employee_no='DT22-0138'), '모바일 테스트 매트릭스 참고 사례 정리', 'LOW', '테스트 매트릭스 설계에 참고할 만한 외부 사례를 정리했습니다.\n\n1. 참고 자료\n\n- Android 공식 호환성 테스트 가이드의 기기 티어 분류 방식\n- iOS 기기별 지원 버전 정책(Apple 공식 문서)\n- 업계에서 흔히 쓰는 네트워크 조건(Wi-Fi/LTE/오프라인) 시뮬레이션 방식\n\n2. 적용 방향\n\n기기 티어 분류와 네트워크 조건 축은 위 자료를 참고해 저희 매트릭스 설계안에 반영했습니다.', '2025-09-18 13:00:00', '2025-09-18 13:00:00', NULL),
(307, 40, (SELECT id FROM users WHERE employee_no='DT23-0034'), '모바일 QA 체크리스트 활용 가이드', 'MID', '모바일 QA 체계가 자리잡으면서, 신규 투입 인원이 바로 참고할 수 있도록 체크리스트 활용 가이드를 정리했습니다.\n\n1. 체크리스트 구성\n\n기기 티어 x OS 버전 x 네트워크 조건 매트릭스를 기준으로, 셀마다 화면 렌더링·권한 팝업·오프라인 동작·성능(저사양 기종 한정) 항목을 점검합니다.\n\n2. 사용 순서\n\n배포 전 대상 빌드를 매트릭스의 각 셀 기준으로 순회하며 점검하고, 이슈 발견 시 트러블슈팅 문서 양식으로 기록합니다.\n\n3. 참고\n\n과거 발견된 저사양 기종 성능 이슈 사례를 함께 첨부하니 참고하시기 바랍니다.', '2025-12-01 09:30:00', '2025-12-01 09:30:00', NULL),
(308, 40, (SELECT id FROM users WHERE employee_no='DT22-0138'), '모바일 앱 QA 체계 수립 회고', 'MID', '모바일 앱 QA 체계 수립 프로젝트가 종료 보고를 끝으로 마무리됐습니다. 킥오프부터 종료까지의 과정을 회고 차원에서 정리해 공유합니다.\n\n1. 시작 배경\n\n윤하림 QA선임은 킥오프에서 "모바일 앱이 늘면서 기존 웹 중심 체크리스트로는 놓치는 게 많습니다. 기기별 테스트, 오프라인 시나리오 같은 게 빠져 있었어요."라고 문제를 짚었습니다. 모바일 전용 테스트 체계 수립을 목표로 프로젝트를 시작했습니다.\n\n2. 진행 과정\n\n기존 체크리스트 갭 조사를 거쳐 테스트 대상 기종·OS 버전을 확정하고 테스트 매트릭스를 설계했습니다. 매트릭스 리뷰 중 저사양 기종에서만 재현되는 스크롤 성능 이슈를 발견해 체크리스트에 관련 항목을 추가로 반영했습니다.\n\n3. 결과\n\n종료 보고에서 주요 기종 대상 테스트 매트릭스와 모바일 전용 체크리스트를 완성했습니다. "이제 앱 배포 전에 최소한 뭘 봐야 하는지는 명확해졌습니다."라는 소감처럼, 애초 목표였던 모바일 전용 테스트 체계 수립이 실제로 달성됐습니다.\n\n4. 마무리\n\n산출물 정리 및 공유를 마지막으로 프로젝트를 종료합니다. 참여해 주신 분들께 감사드립니다.', '2025-12-12 15:00:00', '2025-12-12 15:00:00', NULL),
(317, 42, (SELECT id FROM users WHERE employee_no='DT22-0054'), '[후속조사] 언어별 CI 요구사항 조사 결과 공유', 'MID', 'Java(Gradle), Node(npm), Python(pip), Go(go build) 4개 언어권 서비스를 대상으로 CI 요구사항을 조사했습니다.\n\n공통으로 확인된 점: 언어별 빌드 도구는 다르지만 lint → build → test → deploy 4단계 골격은 동일하게 묶을 수 있습니다.\n\n차이가 큰 지점: 의존성 캐시 전략이 팀마다 제각각이라 이 부분은 별도 논의가 필요할 것 같습니다. 5/13 리뷰 회의 때 초안과 함께 공유하겠습니다.', '2024-04-15 10:30:00', '2024-04-15 10:30:00', NULL),
(318, 42, (SELECT id FROM users WHERE employee_no='DT22-0021'), '[기술설계] 공통 CI 템플릿 초안 설계', 'HIGH', '조사 결과를 바탕으로 공통 템플릿 초안 구조를 잡았습니다.\n\n- 1단계 lint: 언어별 정적분석 도구 실행\n- 2단계 build: 언어별 빌드 명령 (파라미터화)\n- 3단계 test: 단위테스트 + 커버리지 리포트 업로드\n- 4단계 deploy: 배포 대상 브랜치 조건부 실행\n\n의존성 캐시 단계는 아직 확정 전이라 이번 초안에서는 자리만 비워뒀습니다. 다음 리뷰 회의(5/13)에서 실제 저장소에 적용해보고 피드백 받겠습니다.', '2024-04-25 14:00:00', '2024-04-25 14:00:00', NULL),
(319, 42, (SELECT id FROM users WHERE employee_no='DT22-0050'), '[이슈] 템플릿 초안 리뷰 중 캐시 전략 문제 발견', 'HIGH', '5/13 리뷰 회의에서 초안을 실제 저장소 몇 곳에 적용해보다가 문제를 발견했습니다.\n\n증상: 팀마다 의존성 캐시 방식이 달라서(어떤 팀은 브랜치별 캐시, 어떤 팀은 캐시 미사용) 같은 템플릿을 써도 빌드 시간 편차가 크게 났습니다.\n\n원인: 캐시 키를 정하는 공통 규칙이 없어서 각자 임의로 설정해왔던 것으로 파악됩니다.\n\n대응: 오태양 선임이 언어별 표준 캐시 키 규칙을 정리해서 6/17 회의 때 안건으로 올리기로 했습니다.', '2024-05-14 11:00:00', '2024-05-14 11:00:00', NULL),
(320, 42, (SELECT id FROM users WHERE employee_no='DT22-0048'), '[결정공지] 언어별 표준 캐시 키 규칙 확정', 'HIGH', '캐시 전략 이슈에 대한 해결 방안을 정리했습니다. 6/17 회의에서 아래 규칙으로 최종 확정되었습니다.\n\n- Java(Gradle): build.gradle.lock 해시\n- Node: package-lock.json 해시\n- Python: requirements.txt 해시\n- Go: go.sum 해시\n\nlockfile 해시 기준으로 캐시 키를 통일하면 팀별 편차 없이 동일한 규칙으로 캐시가 재사용됩니다. 적용 결과 빌드 시간이 확연히 줄었습니다. 이번 규칙으로 4종 템플릿에 모두 반영합니다.', '2024-06-17 15:30:00', '2024-06-17 15:30:00', NULL),
(321, 42, (SELECT id FROM users WHERE employee_no='DT22-0021'), '[중간요약] CI 파이프라인 표준화 진행 현황', 'MID', '킥오프(4/1) 이후 현재까지 진행 상황을 정리합니다.\n\n1. 언어별(Java/Node/Python/Go) CI 요구사항 조사 완료\n2. 공통 템플릿 초안 설계 및 1차 리뷰 완료\n3. 리뷰 중 발견된 캐시 전략 이슈 해결 (lockfile 해시 기준 표준 캐시 키 확정)\n4. 남은 작업: 4종 템플릿 최종 확정 및 파일럿 적용\n\n일정상 큰 지연 없이 진행 중이며, 파일럿 적용 결과를 보고 7/11 종료 보고를 준비할 예정입니다.', '2024-06-20 09:00:00', '2024-06-20 09:00:00', NULL),
(322, 42, (SELECT id FROM users WHERE employee_no='DT22-0048'), '[참고자료] CI 캐시 전략 및 재사용 워크플로우 참고 문서', 'LOW', '캐시 키 규칙을 설계하면서 참고했던 외부 자료 정리해서 공유합니다.\n\n- CI 플랫폼 공식 문서의 의존성 캐시 가이드(캐시 키/복원 키 설계 원칙)\n- 재사용 가능한 워크플로우(reusable workflow) 설계 관련 공식 문서\n- 대규모 모노레포에서의 언어별 캐시 전략 사례\n\n특히 캐시 키를 lockfile 해시로 잡는 방식이 여러 사례에서 공통으로 권장되고 있어서, 이번에 확정한 규칙에 참고했습니다.', '2024-06-24 13:20:00', '2024-06-24 13:20:00', NULL),
(323, 42, (SELECT id FROM users WHERE employee_no='DT22-0054'), '[온보딩] 신규 서비스 CI 템플릿 적용 가이드', 'MID', '표준 템플릿이 확정되어, 신규 서비스에 적용하는 방법을 정리했습니다.\n\n1. 언어에 맞는 템플릿(Java/Node/Python/Go) 파일을 저장소에 복사\n2. 서비스명, 배포 대상 브랜치 등 값 부분만 수정\n3. lint/build/test 단계는 그대로 두고, deploy 단계 배포 대상만 확인\n\n기존에는 파이프라인을 처음부터 새로 짜야 했지만, 이제는 템플릿 가져다 값만 바꾸면 되어 세팅 시간이 크게 줄었습니다. 신규 서비스 온보딩 시 이 문서를 참고해주세요.', '2024-07-03 10:00:00', '2024-07-03 10:00:00', NULL),
(324, 42, (SELECT id FROM users WHERE employee_no='DT22-0021'), '[회고] CI 파이프라인 표준화 프로젝트 회고', 'MID', '4/1 킥오프부터 오늘 종료 보고까지, 약 3개월간 프로젝트를 돌아봅니다.\n\n잘한 점: 언어별 요구사항을 먼저 충분히 조사한 덕분에 초안 단계에서 큰 방향을 잘 잡을 수 있었습니다. 리뷰 과정에서 발견된 캐시 전략 이슈도 원인을 명확히 짚고 표준 규칙으로 풀어냈습니다.\n\n아쉬운 점: 캐시 전략처럼 팀마다 관행이 다른 부분은 초기 조사 단계에서 더 깊게 파고들었으면 리뷰 단계에서의 시행착오를 줄일 수 있었을 것 같습니다.\n\n다음에 적용할 점: 표준화 작업은 요구사항 조사 시점에 "관행 차이"까지 함께 파악하는 체크리스트를 만들어두면 좋겠습니다.', '2024-07-11 15:00:00', '2024-07-11 15:00:00', NULL),
(263, 45, (SELECT id FROM users WHERE employee_no='DT22-0057'), '1차 전환 대상 서비스 조사 공유', 'MID', '킥오프에서 논의된 대로 컨테이너 전환 대상 서비스를 정하기 전에, 현재 운영 중인 API들의 상태 의존성을 먼저 조사해봤습니다.\n\n1. 회원 조회 API — 겉보기엔 조회 전용이라 무상태로 보이지만, 세션/캐시 사용 여부는 코드 레벨에서 한 번 더 확인이 필요합니다.\n2. 상품 카탈로그 API — 완전 무상태, DB 조회만 수행. 전환 리스크가 가장 낮아 보입니다.\n3. 주문 조회 API — 무상태로 보이나 조회량이 많아 트래픽 변동 폭이 큽니다.\n\n세 서비스 모두 1차 후보로 올릴 만하다고 판단됩니다. 다음 회의(4/18)에서 최종 대상을 확정하면 좋겠습니다.', '2025-04-10 10:00:00', '2025-04-10 10:00:00', NULL),
(264, 45, (SELECT id FROM users WHERE employee_no='DT22-0050'), '1차 컨테이너 전환 대상 서비스 확정 안내', 'HIGH', '4/18 회의에서 1차 컨테이너 전환 대상 서비스를 확정했습니다.\n\n1. 회원 조회 API\n2. 상품 카탈로그 API\n3. 주문 조회 API\n\n세 서비스 모두 상태 없는(무상태) 구조로 판단해 리스크가 낮은 것부터 먼저 옮기기로 했습니다. 다만 회원 조회 API는 실제 무상태 여부를 마이그레이션 과정에서 한 번 더 검증할 예정입니다.\n\n다음 단계는 오케스트레이션 도구 선정과 아키텍처 설계이며, 5월 중 관련 회의를 진행할 예정입니다. 각 파트에서는 담당 서비스의 배포 구조를 미리 파악해두시면 좋겠습니다.', '2025-04-21 11:00:00', '2025-04-21 11:00:00', NULL),
(265, 45, (SELECT id FROM users WHERE employee_no='DT22-0057'), '쿠버네티스 기반 오케스트레이션 아키텍처 설계 문서', 'MID', '5/20 아키텍처 설계 회의에서 정리된 내용을 문서로 공유합니다.\n\n1. 오케스트레이션 도구: 쿠버네티스로 확정. 생태계가 넓고 HPA(Horizontal Pod Autoscaler) 기반 자동 확장을 표준으로 지원한다는 점이 결정적이었습니다.\n2. 네임스페이스 구조: 서비스별로 네임스페이스를 분리해 운영합니다. 1차 대상인 회원 조회, 상품 카탈로그, 주문 조회 API부터 네임스페이스를 잡습니다.\n3. 배포 파이프라인: CI/CD와 연동해 이미지 빌드부터 배포까지 자동화합니다.\n4. 자동 확장: HPA 기반으로 트래픽에 따라 파드 수를 자동 조정합니다.\n\n다음 단계로 1차 대상 서비스의 컨테이너 이미지 빌드를 진행합니다.', '2025-05-22 14:00:00', '2025-05-22 14:00:00', NULL),
(266, 45, (SELECT id FROM users WHERE employee_no='DT22-0055'), 'HPA(Horizontal Pod Autoscaler) 참고자료 공유', 'LOW', '저희가 채택한 HPA 기반 자동 확장 방식과 관련해, 팀 내 이해를 돕기 위한 참고자료를 정리해 공유합니다.\n\nHPA는 CPU/메모리 사용률 등 지표를 기준으로 파드 수를 자동으로 늘리거나 줄여주는 쿠버네티스 기본 기능입니다. 저희가 5/20 아키텍처 설계 회의에서 채택하기로 한 방식이기도 합니다.\n\n임계값을 어떻게 잡느냐에 따라 반응 속도와 리소스 낭비 사이의 균형이 달라지므로, 앞으로 진행할 자동 스케일링 검증 단계에서 실측을 기반으로 값을 조정할 예정입니다.\n\n관련 자료는 팀 채널에 별도로 첨부해두었으니 참고 부탁드립니다.', '2025-06-05 09:30:00', '2025-06-05 09:30:00', NULL),
(267, 45, (SELECT id FROM users WHERE employee_no='DT22-0049'), '마이그레이션 중 발견된 세션 의존성 및 리소스 이슈', 'HIGH', '7/8 회의에서 논의된 마이그레이션 이슈와 대응 방안을 정리합니다.\n\n1. 세션 의존성 문제 — 회원 조회 API가 무상태인 줄 알았으나, 실제로는 로컬 세션 캐시를 사용하고 있었습니다. 여러 파드로 분산되니 로그인 유지가 되지 않는 문제가 발생했습니다. → 세션을 Redis로 이전해 해결하기로 했습니다.\n\n2. 리소스 사이징 실패 — 초기 리소스 requests/limits를 너무 낮게 잡아 파드가 OOM으로 계속 재시작됐습니다. → 실측 트래픽 기반으로 리소스 값을 재산정합니다.\n\n3. 롤백 전략 부재 — 배포 중 문제가 생겨도 이전 버전으로 되돌릴 절차가 없었습니다. → 즉시 롤백 가능한 배포 절차를 별도로 수립하기로 했습니다.\n\n세 가지 모두 이번 주부터 순차적으로 조치할 예정입니다.', '2025-07-10 13:00:00', '2025-07-10 13:00:00', NULL),
(268, 45, (SELECT id FROM users WHERE employee_no='DT22-0047'), '컨테이너 전환 프로젝트 온보딩 가이드', 'LOW', '프로젝트에 새로 합류하거나 진행 상황을 따라잡아야 하는 분들을 위해 지금까지의 흐름을 정리합니다.\n\n1. 배경과 목표 — 기존 배포 방식으로는 트래픽 급증에 유연하게 대응하기 어려워, 컨테이너 기반으로 전환해 확장성을 확보하는 것이 목표입니다.\n\n2. 1차 전환 대상 — 회원 조회 API, 상품 카탈로그 API, 주문 조회 API 세 가지로, 상태 의존성이 낮은 서비스부터 시작했습니다.\n\n3. 아키텍처 — 쿠버네티스를 오케스트레이션 도구로 채택했고, 서비스별 네임스페이스와 HPA 기반 자동 확장을 사용합니다.\n\n4. 겪었던 이슈 — 회원 조회 API의 숨은 세션 의존성, 리소스 사이징 실패로 인한 OOM, 롤백 절차 부재 등을 마이그레이션 과정에서 발견하고 개선했습니다.\n\n전반적인 흐름은 위와 같으며, 세부 설계 문서와 이슈 대응 내역은 프로젝트 게시판에서 확인할 수 있습니다.', '2025-07-15 10:00:00', '2025-07-15 10:00:00', NULL),
(269, 45, (SELECT id FROM users WHERE employee_no='DT22-0055'), '자동 스케일링 검증 결과 중간 요약', 'MID', '8/26 회의에서 진행한 부하 테스트 결과를 요약합니다.\n\n트래픽이 급증했을 때 파드가 자동으로 늘어나는 것을 확인했습니다. 예전 같으면 수동으로 스케일을 조정해야 했던 상황인데, 이번에는 HPA가 트래픽 증가를 감지해 자동으로 대응했습니다.\n\n다만 트래픽 급증 시점부터 파드가 실제로 늘어나기까지 반응 속도가 다소 느리다는 점이 확인됐습니다. HPA 임계값을 더 낮춰 반응 속도를 개선해보기로 했고, 조정 후 재검증할 예정입니다.\n\n나머지 서비스들도 이번 결과를 기반으로 순차적으로 확장 적용 계획을 수립할 예정입니다.', '2025-08-27 09:00:00', '2025-08-27 09:00:00', NULL),
(270, 45, (SELECT id FROM users WHERE employee_no='DT22-0050'), '컨테이너 오케스트레이션 전환 프로젝트 회고', 'MID', '4월 킥오프부터 오늘 종료 보고까지, 약 6개월 반 동안 진행한 컨테이너 오케스트레이션 전환 프로젝트를 돌아봅니다.\n\n처음 목표는 명확했습니다. 트래픽이 갑자기 몰릴 때 기존 배포 방식으로는 스케일을 늘리는 데 시간이 걸렸고, 컨테이너 기반으로 전환해 확장성을 확보하려 했습니다.\n\n1차 전환 대상으로 회원 조회, 상품 카탈로그, 주문 조회 API를 선정했고, 쿠버네티스와 HPA 기반 자동 확장으로 아키텍처를 설계했습니다. 마이그레이션 과정에서는 회원 조회 API의 숨은 세션 의존성, 리소스 사이징 실패로 인한 OOM, 롤백 절차 부재 같은 문제들을 겪었지만 하나씩 해결해나갔습니다.\n\n이후 진행한 자동 스케일링 검증에서는 트래픽 급증 시 파드가 자동으로 늘어나는 것을 확인했고, HPA 임계값 튜닝까지 마쳤습니다.\n\n종료 보고에서도 이야기했듯, 전환 과정에서 배포 방식 자체가 많이 바뀌어서 팀 내 적응 기간이 필요했지만, 결과적으로는 훨씬 유연한 구조를 갖추게 됐습니다.', '2025-10-17 15:00:00', '2025-10-17 15:00:00', NULL),
(279, 58, (SELECT id FROM users WHERE employee_no='DT22-0104'), '마이데이터 2.0 계좌 유형 코드 매핑 재설계안', 'MID', '신규 규격 계좌 유형 코드 체계 개편에 따른 매핑 재설계안입니다.\n\n1. 변경 배경\n마이데이터 2.0 규격에서 계좌 유형 코드 체계가 전면 개편되어, 기존 연동 모듈의 매핑 테이블 전체를 다시 설계해야 합니다.\n\n2. 재설계 방향\n기존 코드 → 신규 코드 매핑 테이블을 신규로 구성하고, 매핑되지 않는 예외 코드는 별도 처리 로직을 추가합니다.\n\n3. 적용 범위\n연동 모듈 내 필드 매핑 로직 전반에 반영됩니다.', '2025-09-29 09:00:00', '2025-09-29 09:00:00', NULL),
(280, 58, (SELECT id FROM users WHERE employee_no='DT22-0108'), '[이슈] 계좌 유형 코드 매핑 변경에 따른 기존 데이터 마이그레이션 필요', 'HIGH', '테스트 중 발견한 이슈를 공유합니다.\n\n1. 증상\n계좌 유형 코드 매핑 방식이 신규 체계로 바뀌면서, 기존에 쌓여 있던 연동 이력 데이터가 신규 코드 체계와 맞지 않아 조회 시 값이 깨지는 현상이 발생합니다.\n\n2. 원인\n기존 데이터가 구 코드 체계로 저장되어 있어 신규 매핑 로직과 호환되지 않습니다.\n\n3. 대응\n기존 데이터를 신규 코드 체계로 변환하는 마이그레이션 스크립트가 필요합니다. 스크립트 작성 및 검증을 진행할 예정입니다.', '2025-10-28 10:30:00', '2025-10-28 10:30:00', NULL),
(281, 58, (SELECT id FROM users WHERE employee_no='DT22-0023'), '[결정공지] 마이그레이션 스크립트 작성을 최우선 과제로 지정', 'HIGH', '연동 이력 데이터 마이그레이션 관련 대응 방침을 공지합니다.\n\n계좌 유형 코드 체계 개편으로 발생한 기존 데이터 마이그레이션 이슈에 대해, 마이그레이션 스크립트 작성 및 검증을 최우선 과제로 지정합니다.\n\n담당: 임채운(스크립트 초안), 마예린(검증 방안)\n일정: 스크립트 초안 11/10까지, 이후 검증 진행\n\n규제 마감 일정을 고려해 여유 있게 진행하되, 데이터 정합성 검증은 꼼꼼히 확인 부탁드립니다.', '2025-10-28 15:00:00', '2025-10-28 15:00:00', NULL),
(282, 58, (SELECT id FROM users WHERE employee_no='DT22-0108'), '연동 이력 데이터 마이그레이션 스크립트 초안 공유', 'MID', '마이그레이션 스크립트 초안을 공유합니다.\n\n1. 처리 범위\n기존 연동 이력 데이터 중 구 코드 체계로 저장된 항목 전체를 대상으로 합니다.\n\n2. 변환 로직\n구 코드 → 신규 코드 매핑 테이블을 참조해 일괄 변환하며, 매핑 예외 건은 별도 목록으로 추출해 수기 검토합니다.\n\n3. 다음 단계\n마예린님과 함께 변환 전후 데이터 건수 대조 및 표본 검증을 진행할 예정입니다.', '2025-11-07 09:00:00', '2025-11-07 09:00:00', NULL),
(283, 58, (SELECT id FROM users WHERE employee_no='DT24-0040'), '연동 이력 데이터 마이그레이션 검증 결과', 'MID', '마이그레이션 스크립트 적용 후 검증 결과를 공유합니다.\n\n1. 검증 방법\n변환 전후 데이터 건수 대조 및 표본 200건 수기 검토를 진행했습니다.\n\n2. 결과\n건수 불일치 없음, 표본 검토에서도 매핑 오류 발견되지 않았습니다.\n\n3. 결론\n마이그레이션 스크립트를 운영 데이터에 적용해도 문제없다고 판단됩니다.', '2025-11-13 09:00:00', '2025-11-13 09:00:00', NULL),
(284, 58, (SELECT id FROM users WHERE employee_no='DT24-0041'), '마이데이터 2.0 규제 기관 사전 검증 통과 결과 공유', 'MID', '규제 기관 사전 검증 결과를 공유합니다.\n\n제출한 연동 모듈이 지적 사항 없이 사전 검증을 한 번에 통과했습니다. 계좌 유형 코드 매핑 재설계와 데이터 마이그레이션이 사전에 마무리된 덕분에 심사 과정에서 별도 보완 요청이 없었습니다.\n\n규제 마감까지 여유가 있는 상태이며, 남은 기간은 최종 산출물 정리에 활용할 예정입니다.', '2025-11-25 09:00:00', '2025-11-25 09:00:00', NULL),
(285, 58, (SELECT id FROM users WHERE employee_no='DT22-0023'), '[회고] 마이데이터 2.0 연동 모듈 개선 프로젝트 회고', 'LOW', '프로젝트를 마무리하며 회고를 남깁니다.\n\n1. 잘된 점\n작년 3.0 대응 경험 덕분에 규격 해석 이슈를 빠르게 판단할 수 있었고, 계좌 유형 코드 매핑처럼 예상치 못한 큰 변경도 재설계·마이그레이션·검증 순으로 무리 없이 대응했습니다.\n\n2. 아쉬운 점\n기존 데이터 마이그레이션 필요성을 설계 초기 단계에서 미리 점검했다면 일정에 더 여유가 있었을 것 같습니다.\n\n3. 다음에 참고할 점\n규격 변경 시 필드 매핑뿐 아니라 기존 데이터 호환성도 초기 분석 단계에 포함시켜야 합니다.', '2025-12-12 15:00:00', '2025-12-12 15:00:00', NULL),
(294, 62, (SELECT id FROM users WHERE employee_no='DT22-0044'), '레거시 테이블 암호화 적용 설계안', 'MID', '1. 적용 대상\n\n정기 점검에서 발견된 레거시 테이블 전체이며, 개인정보에 해당하는 컬럼(이름, 연락처, 주민등록번호 등)을 우선 대상으로 합니다.\n\n2. 암호화 방식\n\n컬럼 단위 암호화를 적용하고, 기존 운영 중인 서비스와의 호환을 위해 애플리케이션 레벨에서 암복호화를 처리하는 방식으로 설계했습니다.\n\n3. 키 관리\n\n키는 별도 키 관리 모듈에서 관리하며, 테이블별로 키를 분리해 특정 키 노출 시 영향 범위를 최소화했습니다.', '2025-02-20 10:00:00', '2025-02-20 10:00:00', NULL),
(295, 62, (SELECT id FROM users WHERE employee_no='DT22-0041'), '암호화 적용 중 인덱스 재구성 이슈 대응', 'HIGH', '1. 이슈 개요\n\n서비스 중인 일부 테이블에 암호화 컬럼을 적용하는 과정에서 기존 인덱스가 깨지는 문제가 발생했습니다.\n\n2. 원인\n\n암호화된 컬럼 값이 기존 인덱스 구조와 맞지 않아, 조회 성능에 영향을 줄 수 있는 상태였습니다.\n\n3. 대응\n\n트래픽이 적은 새벽 시간대에 인덱스를 재구성하는 것으로 대응했습니다. 재구성 작업은 서비스 영향 없이 마무리됐습니다.', '2025-04-16 11:00:00', '2025-04-16 11:00:00', NULL),
(296, 62, (SELECT id FROM users WHERE employee_no='DT22-0039'), '서비스 중인 테이블 무중단 마이그레이션 방식 확정', 'HIGH', '1. 배경\n\n대상 테이블 중 일부는 이미 서비스 중이라, 다운타임 없이 암호화를 적용해야 하는 상황이었습니다.\n\n2. 결정 사항\n\n서비스 중인 테이블은 신규 컬럼에 암호화된 값을 먼저 채운 뒤 애플리케이션 전환, 이후 기존 컬럼을 제거하는 단계적 방식으로 마이그레이션하기로 결정했습니다.\n\n3. 적용 범위\n\n이 방식은 서비스 중인 테이블 전체에 동일하게 적용합니다.', '2025-03-20 14:00:00', '2025-03-20 14:00:00', NULL),
(297, 62, (SELECT id FROM users WHERE employee_no='DT22-0039'), '개인정보 암호화 적용 확대 중간 진행상황', 'MID', '1. 진행 현황\n\n대상 테이블 전수조사를 마쳤고, 확인된 테이블에 대해 순차적으로 암호화를 적용하고 있습니다.\n\n2. 완료된 부분\n\n서비스 영향이 없는 테이블은 이미 적용을 마쳤습니다.\n\n3. 남은 작업\n\n서비스 중인 테이블은 무중단 마이그레이션 방식으로 순서대로 진행 중이며, 인덱스 재구성 등 이슈는 발생 즉시 대응하고 있습니다.', '2025-04-02 10:00:00', '2025-04-02 10:00:00', NULL),
(298, 62, (SELECT id FROM users WHERE employee_no='DT22-0024'), '개인정보보호법 암호화 대상 항목 참고자료', 'LOW', '1. 참고 배경\n\n대상 테이블 선정 기준을 정할 때, 개인정보보호법령상 암호화 의무 대상 항목을 다시 확인했습니다.\n\n2. 확인 내용\n\n주민등록번호, 비밀번호 등은 원문 저장이 금지되어 있고, 그 외 고유식별정보나 민감정보도 안전성 확보조치 기준에 따라 암호화가 권고됩니다.\n\n3. 활용\n\n이번 전수조사 시 대상 컬럼 판단 기준으로 활용했습니다.', '2025-02-10 09:30:00', '2025-02-10 09:30:00', NULL),
(299, 62, (SELECT id FROM users WHERE employee_no='DT22-0040'), '개인정보 암호화 적용 확대 참여자 온보딩 자료', 'LOW', '1. 프로젝트 개요\n\n정기 점검에서 발견된 레거시 테이블의 암호화 누락 건을 조치하는 프로젝트입니다.\n\n2. 진행 방식\n\n대상 테이블을 전수조사한 뒤, 서비스 영향이 없는 테이블부터 우선 적용하고 있습니다.\n\n3. 참고할 자료\n\n설계안과 참고 법령 자료를 함께 확인하시면 진행 배경을 이해하는 데 도움이 됩니다.', '2025-02-06 09:00:00', '2025-02-06 09:00:00', NULL),
(300, 62, (SELECT id FROM users WHERE employee_no='DT22-0039'), '개인정보 암호화 적용 확대 프로젝트 회고', 'MID', '1. 추진 배경\n\n정기 점검 중 일부 레거시 테이블에 암호화가 누락된 것이 발견되어, 대상 테이블 전체에 암호화를 적용하는 프로젝트를 시작했습니다.\n\n2. 진행 경과\n\n서준혁 보안파트장 주도로 정민혁, 백승아, 구자헌, 류경호, 표건우와 함께 전수조사부터 순차 적용까지 진행했습니다. 서비스 중인 테이블은 무중단 마이그레이션 방식으로 처리했고, 중간에 나온 인덱스 재구성 이슈도 대응했습니다.\n\n3. 결과\n\n발견된 누락 테이블 전량에 암호화를 적용했고, 재점검에서도 이상이 없음을 확인했습니다. 정기 점검 항목에도 추가해 재발을 방지하도록 했습니다.', '2025-05-16 15:00:00', '2025-05-16 15:00:00', NULL);
